INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a3a8df0-23dc-4c1e-acfc-67144119c682', '病中題主人庭鶴', '病中題主人庭鹤', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["遼水華亭舊所聞，病中毛羽最憐君。","稻粱且足身兼健，何必青雲與白雲。"]', '["遼水华亭旧所闻，病中毛羽最怜君。","稻粱且足身兼健，何必青云與白云。"]', '诗', 'shi', '', NULL, '病中題主人庭鶴 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05ed6c66-7717-4ae4-992e-4d924d4445e6', '蟬', '蟬', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["天地工夫一不遺，與君聲調借君緌。","風棲露飽今如此，應忘當年滓濁時。"]', '["天地工夫一不遺，與君声調借君緌。","风棲露飽今如此，應忘當年滓濁时。"]', '诗', 'shi', '', NULL, '蟬 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bb18e69-a6ba-4654-8e85-6c2eb8278a26', '薛陽陶觱篥歌', '薛陽陶觱篥歌', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["平泉上相東征日，曾爲陽陶歌觱篥。","烏江太守會稽侯，相次三篇皆俊逸。","橋山殯葬衣冠後，金印蒼黃南去疾。","龍樓冷落夏口寒，從此風流爲廢物。","人間至藝難得主，懷抱差池恨星律。","邗溝僕射戎政閑，試渡瓜洲吐伊鬱。","西風九月草樹秋，萬喧沈寂登高樓。","左篁揭指徵羽吼，煬帝起坐淮王愁。","高飄咽滅出滯氣，下感知己時橫流。","穿空激遠不可遏，髣髴似向伊水頭。","伊水林泉今已矣，因取遺編認前事。","武宗皇帝御宇時，四海恬然知所自。","掃除桀黠似提箒，制壓羣豪若穿鼻。","九鼎調和各有門，謝安空儉真兒戲。","功高近代竟誰知，藝小似君猶不棄。","勿惜喑嗚更一吹，與君共下難逢淚。"]', '["平泉上相东征日，曾爲陽陶歌觱篥。","烏江太守會稽侯，相次三篇皆俊逸。","橋山殯葬衣冠後，金印蒼黄南去疾。","龙楼冷落夏口寒，從此风流爲廢物。","人间至藝难得主，懷抱差池恨星律。","邗溝僕射戎政闲，試渡瓜洲吐伊鬱。","西风九月草樹秋，万喧沈寂登高楼。","左篁揭指徵羽吼，煬帝起坐淮王愁。","高飄咽滅出滯氣，下感知己时橫流。","穿空激远不可遏，髣髴似向伊水头。","伊水林泉今已矣，因取遺編認前事。","武宗皇帝御宇时，四海恬然知所自。","掃除桀黠似提箒，制壓羣豪若穿鼻。","九鼎調和各有门，謝安空儉真兒戲。","功高近代竟誰知，藝小似君猶不棄。","勿惜喑嗚更一吹，與君共下难逢泪。"]', '诗', 'shi', '', NULL, '薛陽陶觱篥歌 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('656ca402-52dd-4131-8a96-5b768d0f856f', '酬丘光庭', '酬丘光庭', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["正月十一日書札，五月十六日到來。","柳吟秦望咫尺地，鯉魚何處閑裴回？","故人情意未疎索，次第序述眉眼開。","上言二年隔煙水，下有數幅真瓊瑰。","行吟坐讀口不倦，瀑泉激射琅玕摧。","壁池蘭蕙日已老，村酒蘸甲時幾桮。","鶴齡鴻算不復見，雨後蓑笠空莓苔。","自從黃寇擾中土，人心波蕩猶未迴。","道殷合眼拜九列，張濬掉舌升三台。","朝廷濟濟百揆序，寧將對面容姦回。","禍生有基妖有漸，翠華西幸蒙塵埃。","三川梗塞兩河閉，大明宮殿生蒿萊。","懦夫早歲不量力，策蹇仰北高崔嵬。","千門萬戶扃鎖密，良匠不肯雕散材。","君今得意尚如此，況我麋鹿悠悠哉。","榮衰貴賤目所睹，莫嫌頭白黃金臺。"]', '["正月十一日书札，五月十六日到来。","柳吟秦望咫尺地，鯉鱼何处闲裴回？","故人情意未疎索，次第序述眉眼开。","上言二年隔煙水，下有數幅真瓊瑰。","行吟坐读口不倦，瀑泉激射琅玕摧。","壁池蘭蕙日已老，村酒蘸甲时幾桮。","鹤齡鴻算不复见，雨後蓑笠空莓苔。","自從黄寇擾中土，人心波蕩猶未迴。","道殷合眼拜九列，張濬掉舌升三台。","朝廷濟濟百揆序，寧將对面容姦回。","禍生有基妖有漸，翠华西幸蒙塵埃。","三川梗塞兩河閉，大明宮殿生蒿萊。","懦夫早歲不量力，策蹇仰北高崔嵬。","千门万戶扃鎖密，良匠不肯雕散材。","君今得意尚如此，況我麋鹿悠悠哉。","榮衰貴賤目所睹，莫嫌头白黄金台。"]', '诗', 'shi', '', NULL, '酬丘光庭 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25df70d9-524a-44bd-a037-c7b50e7e27f1', '投宣武鄭尚書二十韻', '投宣武鄭尚书二十韻', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["漢代簪纓盛，梁園雉堞雄。","物情須重德，時論在明公。","族大踰開魏，高神本降嵩。","世家惟蹇諤，官業即清通。","翰苑論思外，綸闈嘯傲中。","健豪驚綵鳳，高步出冥鴻。","履歷雖吾道，行藏必聖聰。","絳霄無繫滯，浙水忽西東。","庾監高樓月，袁郎滿扇風。","四年將故事，兩地有全功。","去去才須展，行行道益隆。","避權辭憲署，仗節出南宮。","雁影相承接，龍圖共始終。","自然須作礪，不必恨臨戎。","幕下蓮花盛，竿頭㺗佩紅。","騎兒逢郭伋，戰士得文翁。","人地應無比，簞瓢奈屢空。","因思一枝桂，已作斷根蓬。","往事應歸捷，勞歌且責躬。","殷勤信陵館，今日自途窮。"]', '["漢代簪纓盛，梁园雉堞雄。","物情須重德，时論在明公。","族大踰开魏，高神本降嵩。","世家惟蹇諤，官業即清通。","翰苑論思外，綸闈嘯傲中。","健豪驚綵鳳，高步出冥鴻。","履歷雖吾道，行藏必聖聰。","絳霄無繫滯，浙水忽西东。","庾監高楼月，袁郎满扇风。","四年將故事，兩地有全功。","去去才須展，行行道益隆。","避權辞憲署，仗節出南宮。","雁影相承接，龙圖共始終。","自然須作礪，不必恨臨戎。","幕下蓮花盛，竿头㺗佩紅。","騎兒逢郭伋，戰士得文翁。","人地應無比，簞瓢奈屢空。","因思一枝桂，已作斷根蓬。","往事應归捷，勞歌且責躬。","殷勤信陵館，今日自途窮。"]', '诗', 'shi', '', NULL, '投宣武鄭尚書二十韻 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93fd4881-1591-40c0-aa9c-1fe53cf28348', '投浙東王大夫二十韻', '投浙东王大夫二十韻', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["越嶺千峰秀，淮流一派長。","暫憑開物手，來展濟時方。","舊跡蘭亭在，高風桂樹香。","地清無等級，天闊任徊翔。","麈尾談何勝，螭頭筆更狂。","直曾批鳳詔，高已冠鵷行。","嘯傲辭民部，雍容出帝鄉。","趙堯推印綬，句踐與封疆。","水占仙人吹，城留御史牀。","嘉賓鄒潤甫，百姓賀知章。","席煖飛鸚鵡，塵輕駐驌驦。","夜歌珠斷續，晴舞雪悠揚。","化向棠陰布，春隨棣萼芳。","盛名韜不得，雄略晦彌彰。","自愧三冬學，來窺數仞牆。","感深惟刻骨，時去欲霑裳。","想望魚燒尾，咨嗟鼠嚙腸。","可能因蹇拙，便合老滄浪。","題柱心猶壯，移山志不忘。","深慚百般病，今日問醫王。"]', '["越嶺千峰秀，淮流一派长。","暫憑开物手，来展濟时方。","旧跡蘭亭在，高风桂樹香。","地清無等級，天闊任徊翔。","麈尾談何勝，螭头笔更狂。","直曾批鳳詔，高已冠鵷行。","嘯傲辞民部，雍容出帝乡。","趙堯推印綬，句踐與封疆。","水占仙人吹，城留御史牀。","嘉賓鄒潤甫，百姓賀知章。","席煖飞鸚鵡，塵轻駐驌驦。","夜歌珠斷續，晴舞雪悠揚。","化向棠陰布，春隨棣萼芳。","盛名韜不得，雄略晦彌彰。","自愧三冬学，来窺數仞牆。","感深惟刻骨，时去欲霑裳。","想望鱼燒尾，咨嗟鼠嚙腸。","可能因蹇拙，便合老滄浪。","題柱心猶壯，移山志不忘。","深慚百般病，今日问醫王。"]', '诗', 'shi', '', NULL, '投浙東王大夫二十韻 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43dff396-d559-4a13-aebc-6c3a49106ebb', '寄剡縣主簿', '寄剡縣主簿', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["金庭養真地，珠篆會稽官。","境勝堪長往，時危喜暫安。","洞連滄海闊，山擁赤城寒。","他日拋塵土，因君擬煉丹。"]', '["金庭養真地，珠篆會稽官。","境勝堪长往，时危喜暫安。","洞連滄海闊，山擁赤城寒。","他日拋塵土，因君擬煉丹。"]', '诗', 'shi', '', NULL, '寄剡縣主簿 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee5e99d4-99ce-48c2-8c40-7cac55b41eed', '中秋不見月', '中秋不见月', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["風簾淅淅漏燈痕，一半秋光此夕分。","天爲素娥孀怨苦，併教西北起浮雲。"]', '["风簾淅淅漏灯痕，一半秋光此夕分。","天爲素娥孀怨苦，併教西北起浮云。"]', '诗', 'shi', '', NULL, '中秋不見月 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1ee057f-f8c1-42b8-9b93-76fb0ce0b3b7', '答宗人衮', '答宗人衮', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["崑崙水色九般流，飲即神仙憩即休。","敢恨守株曾失意，始知緣木更難求。","鴒原謾欲均餘力，鶴髪那堪問舊遊。","遙望北辰當上國，羨君歸掉五諸侯。"]', '["崑崙水色九般流，饮即神仙憩即休。","敢恨守株曾失意，始知緣木更难求。","鴒原謾欲均餘力，鹤髪那堪问旧游。","遙望北辰當上国，羨君归掉五諸侯。"]', '诗', 'shi', '', NULL, '答宗人衮 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abd590ad-4fe8-4649-900a-29ca58ac224c', '早行', '早行', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["雨灑江聲風又吹，扁舟正與睡相宜。","無端戍鼓催前去，別却青山向曉時。"]', '["雨灑江声风又吹，扁舟正與睡相宜。","無端戍鼓催前去，別却青山向晓时。"]', '诗', 'shi', '', NULL, '早行 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a8a2c14-79aa-4b70-b64f-1bffc3da08bc', '詠白菊', '詠白菊', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["雖被風霜競欲催，皎然顏色不低摧。","已疑素手能粧出，又似金錢未染來。","香散自宜飄淥酒，葉交仍得蔭香苔。","尋思閉戶中宵見，應認寒窗雪一堆。"]', '["雖被风霜競欲催，皎然顏色不低摧。","已疑素手能粧出，又似金錢未染来。","香散自宜飄淥酒，葉交仍得蔭香苔。","尋思閉戶中宵见，應認寒窗雪一堆。"]', '诗', 'shi', '', NULL, '詠白菊 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06268909-4216-483a-9eda-7e8fa0f7a603', '晚泊宿松', '晚泊宿松', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["解纜隨江流，晚泊古淮岸。","歸雲送春和，繁星麗雲漢。","春深胡雁飛，人喧水禽散。","仰君邈難親，沈思夜將旦。"]', '["解纜隨江流，晚泊古淮岸。","归云送春和，繁星丽云漢。","春深胡雁飞，人喧水禽散。","仰君邈难親，沈思夜將旦。"]', '诗', 'shi', '', NULL, '晚泊宿松 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38f597b5-438a-4ff6-9b38-9cf47637e5f3', '錢塘遇默師憶潤州舊遊', '錢塘遇默師憶潤州旧游', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["歌敲玉唾壺，醉擊珊瑚枝。","石羊妙善街，甘露平泉碑。","捫苔想豪傑，剔蘚看文詞。","歸來北固山，水檻光參差。"]', '["歌敲玉唾壺，醉擊珊瑚枝。","石羊妙善街，甘露平泉碑。","捫苔想豪傑，剔蘚看文词。","归来北固山，水檻光參差。"]', '诗', 'shi', '', NULL, '錢塘遇默師憶潤州舊遊 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76bdbeba-eb3a-4907-b488-92d718252ddb', '江南別', '江南別', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["去年今夜江南別，鴛鴦翅冷飛蓬爇。","今年今夜江北邊，鯉魚腸斷音書絕。","男兒心事無了時，出門上馬不自知。"]', '["去年今夜江南別，鴛鴦翅冷飞蓬爇。","今年今夜江北邊，鯉鱼腸斷音书絕。","男兒心事無了时，出门上马不自知。"]', '诗', 'shi', '', NULL, '江南別 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24dc017c-0acd-42bf-b425-4e5c6064f20b', '四頂山', '四頂山', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["勝景天然別，精神入畫圖。","一山分四頂，三面瞰平湖。","過夏僧無熱，凌冬草不枯。","遊人來至此，願剃髪和鬚。"]', '["勝景天然別，精神入畫圖。","一山分四頂，三面瞰平湖。","過夏僧無熱，凌冬草不枯。","游人来至此，願剃髪和鬚。"]', '诗', 'shi', '', NULL, '四頂山 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('044096d3-e7c3-42d9-9a3e-1ded241c8b41', '姥山', '姥山', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["臨塘古廟一神仙，繡幌花容色儼然。","爲逐朝雲來此地，因隨暮雨不歸天。","眉分初月湖中鑑，香散餘風竹上煙。","借問邑人沈水事，已經秦漢幾千年。"]', '["臨塘古廟一神仙，繡幌花容色儼然。","爲逐朝云来此地，因隨暮雨不归天。","眉分初月湖中鑑，香散餘风竹上煙。","借问邑人沈水事，已經秦漢幾千年。"]', '诗', 'shi', '', NULL, '姥山 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b40e8056-4761-44a8-bb86-1bc4e8a22afa', '岐王宅', '岐王宅', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["朱邸平臺隔禁闈，貴遊陳跡尚依稀。","雲低雍畤祈年去，雨細長楊從獵歸。","申白賓朋傳道義，應劉文彩寄音徽。","承平舊物惟君盡，猶寫雕鞍伴六飛。"]', '["朱邸平台隔禁闈，貴游陳跡尚依稀。","云低雍畤祈年去，雨細长楊從獵归。","申白賓朋傳道義，應劉文彩寄音徽。","承平旧物惟君尽，猶寫雕鞍伴六飞。"]', '诗', 'shi', '', NULL, '岐王宅 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bce38b1-7faa-45dd-8ce7-96966f1bcea1', '長明燈', '长明灯', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["破暗長明世代深，煙和香氣兩沈沈。","不知初點何人在，秪見當年火至今。","曉似紅蓮開沼面，夜如寒月鎮潭心。","孤光自有龍神護，雀戲蛾飛不敢侵。"]', '["破暗长明世代深，煙和香氣兩沈沈。","不知初点何人在，秪见當年火至今。","晓似紅蓮开沼面，夜如寒月鎮潭心。","孤光自有龙神護，雀戲蛾飞不敢侵。"]', '诗', 'shi', '', NULL, '長明燈 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abd010b3-9dc8-4b4c-bf71-2ab48bd21504', '堋口逢人', '堋口逢人', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["艱難別離久，中外往還深。","已改當時髪，空餘舊日心。"]', '["艱难別離久，中外往還深。","已改當时髪，空餘旧日心。"]', '诗', 'shi', '', NULL, '堋口逢人 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0343d78e-0909-409a-92b7-93da28dbc88a', '遇邊使', '遇邊使', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["累年無的信，每夜望邊城。","袖掩千行淚，書封一尺金。"]', '["累年無的信，每夜望邊城。","袖掩千行泪，书封一尺金。"]', '诗', 'shi', '', NULL, '遇邊使 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fd0ecc8-0541-409e-b799-8a3c28f57a3a', '移住別友', '移住別友', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["自到西川住，惟君別有情。","常逢對門遠，又隔一重城。"]', '["自到西川住，惟君別有情。","常逢对门远，又隔一重城。"]', '诗', 'shi', '', NULL, '移住別友 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67238820-3542-463b-a332-09a7a62b8945', '宮詞', '宮词', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["巧畫蛾眉獨出羣，當時人道便承恩。","經年不見君王面，落日黃昏空掩門。"]', '["巧畫蛾眉独出羣，當时人道便承恩。","經年不见君王面，落日黄昏空掩门。"]', '诗', 'shi', '', NULL, '宮詞 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0463eb51-53a6-43e2-9c01-f2c50e230415', '涇溪', '涇溪', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["涇溪石險人競懼，終歲不聞傾覆人。","却是平流無石處，時時聞說有沈淪。"]', '["涇溪石險人競懼，終歲不闻傾覆人。","却是平流無石处，时时闻说有沈淪。"]', '诗', 'shi', '', NULL, '涇溪 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6367b6e2-d4a1-4224-b560-8372242c49e9', '題杜甫集', '題杜甫集', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["楚水悠悠浸楚亭，楚南天地兩無情。","忍交孫武重泉下，不見時人說用兵。"]', '["楚水悠悠浸楚亭，楚南天地兩無情。","忍交孫武重泉下，不见时人说用兵。"]', '诗', 'shi', '', NULL, '題杜甫集 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0580ca82-2c37-4b9b-bc82-82d6899b23c6', '感弄猴人賜朱紱', '感弄猴人賜朱紱', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["十二三年就試期，五湖煙月奈相違。","何如買取胡孫弄，一笑君王便著緋。"]', '["十二三年就試期，五湖煙月奈相違。","何如買取胡孫弄，一笑君王便著緋。"]', '诗', 'shi', '', NULL, '感弄猴人賜朱紱 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21aa5e67-97b1-40c1-9e74-19a3b07d3383', '題磻溪垂釣圖', '題磻溪垂釣圖', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["呂望當年展廟謨，直鉤釣國更誰如。","若教生在西湖上，也是須供使宅魚。"]', '["呂望當年展廟謨，直鉤釣国更誰如。","若教生在西湖上，也是須供使宅鱼。"]', '诗', 'shi', '', NULL, '題磻溪垂釣圖 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7b3ebdd-e208-4a78-ba9a-2582bb0b5411', '春風', '春风', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["也知有意吹噓切，爭奈人間善惡分。","但是粃糠細微物，等閑擡舉到青雲。"]', '["也知有意吹噓切，爭奈人间善惡分。","但是粃糠細微物，等闲擡舉到青云。"]', '诗', 'shi', '', NULL, '春風 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d308178f-d9f2-4c3e-bb2b-654142f693af', '竹下殘雪', '竹下殘雪', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["牆下濃陰對此君，小山尖險玉爲羣。","夜來解凍風雖急，不向寒城減一分。"]', '["牆下濃陰对此君，小山尖險玉爲羣。","夜来解凍风雖急，不向寒城減一分。"]', '诗', 'shi', '', NULL, '竹下殘雪 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7fc83db-33c4-465d-aedd-38e0d709d00f', '杏花', '杏花', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["暖氣潛催次第春，梅花已謝杏花新。","半開半落閑園裏，何異榮枯世上人。"]', '["暖氣潛催次第春，梅花已謝杏花新。","半开半落闲园裏，何異榮枯世上人。"]', '诗', 'shi', '', NULL, '杏花 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81bd221d-5447-40f5-af88-e3756cf5f35f', '鎮海軍所貢', '鎮海軍所貢', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["簷前飛雪扇前塵，千里移添上苑春。","他日丁寧柿林院，莫宣恩澤與閑人。"]', '["簷前飞雪扇前塵，千里移添上苑春。","他日丁寧柿林院，莫宣恩澤與闲人。"]', '诗', 'shi', '', NULL, '鎮海軍所貢 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('151a54e2-00a6-4f9b-8811-3cff804feb3a', '席上歌水調', '席上歌水調', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["餘聲宛宛拂庭梅，通濟渠邊去又回。","若使煬皇魂魄在，爲君應合過江來。"]', '["餘声宛宛拂庭梅，通濟渠邊去又回。","若使煬皇魂魄在，爲君應合過江来。"]', '诗', 'shi', '', NULL, '席上歌水調 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bcca360-220b-4952-b7e8-147be14fd945', '題新榜', '題新榜', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["黃土原邊狡兔肥，犬如流電馬如飛。","灞陵老將無功業，猶憶當時夜獵歸。"]', '["黄土原邊狡兔肥，犬如流電马如飞。","灞陵老將無功業，猶憶當时夜獵归。"]', '诗', 'shi', '', NULL, '題新榜 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57a81627-e395-4593-a5f9-94db08580faf', '句', '句', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["夏窗七葉連陰暗。","賴家橋上潏河邊。","細看月輪真有意，已知青桂近嫦娥。","一箇禰衡容不得，思量黃祖謾英雄。","張華謾出如丹語，不及劉侯一紙書。","山雨霏微宿上亭，雨中因想雨淋鈴。","老僧齋罷關門睡，不管波濤四面生。"]', '["夏窗七葉連陰暗。","賴家橋上潏河邊。","細看月輪真有意，已知青桂近嫦娥。","一箇禰衡容不得，思量黄祖謾英雄。","張华謾出如丹語，不及劉侯一紙书。","山雨霏微宿上亭，雨中因想雨淋鈴。","老僧斋罷关门睡，不管波濤四面生。"]', '诗', 'shi', '', NULL, '句 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c2649e-94cc-40d3-94d6-f043a2f178ed', '比紅兒詩 一', '比紅兒诗 一', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["姓字看侵尺五天，芳菲占斷百花鮮。","馬嵬好笑當時事，虛賺明皇幸蜀川。"]', '["姓字看侵尺五天，芳菲占斷百花鲜。","马嵬好笑當时事，虛賺明皇幸蜀川。"]', '诗', 'shi', '', NULL, '比紅兒詩 一 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f12917-909d-473b-b75d-c67f4274fe66', '比紅兒詩 二', '比紅兒诗 二', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["金谷園中花正繁，墜樓從道感深恩。","齊奴却是來東市，不爲紅兒死更冤。"]', '["金谷园中花正繁，墜楼從道感深恩。","齊奴却是来东市，不爲紅兒死更冤。"]', '诗', 'shi', '', NULL, '比紅兒詩 二 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91baf145-703d-455e-9de4-3178a25468a5', '比紅兒詩 三', '比紅兒诗 三', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["陷却平陽爲小憐，周師百萬戰長川。","更教乞與紅兒貌，舉國山川不值錢。"]', '["陷却平陽爲小怜，周師百万戰长川。","更教乞與紅兒貌，舉国山川不值錢。"]', '诗', 'shi', '', NULL, '比紅兒詩 三 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5115c0b1-6faa-4af3-b838-d4bcd690ac8d', '比紅兒詩 四', '比紅兒诗 四', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["一曲都緣張麗華，六宮齊唱後庭花。","若教比竝紅兒貌，枉破當年國與家。"]', '["一曲都緣張丽华，六宮齊唱後庭花。","若教比竝紅兒貌，枉破當年国與家。"]', '诗', 'shi', '', NULL, '比紅兒詩 四 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d69c475-ebef-4767-b2ee-f95f5f41c71c', '比紅兒詩 五', '比紅兒诗 五', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["樂營門外柳如陰，中有佳人畫閣深。","若是五陵公子見，買時應不啻千金。"]', '["乐營门外柳如陰，中有佳人畫閣深。","若是五陵公子见，買时應不啻千金。"]', '诗', 'shi', '', NULL, '比紅兒詩 五 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df78dfc0-2640-476d-b3a0-fcc444c4a556', '比紅兒詩 六', '比紅兒诗 六', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["青絲高綰石榴裙，腸斷當筵酒半醺。","置向漢宮圖畫裏，入胡應不數昭君。"]', '["青絲高綰石榴裙，腸斷當筵酒半醺。","置向漢宮圖畫裏，入胡應不數昭君。"]', '诗', 'shi', '', NULL, '比紅兒詩 六 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('995762fa-6cdb-4dd5-b791-4d6a5a2f84e6', '比紅兒詩 七', '比紅兒诗 七', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["斜凭欄杆醉態新，歛眸微盻不勝春。","當時若遇東昏主，金葉蓮花是此人。"]', '["斜凭欄杆醉態新，歛眸微盻不勝春。","當时若遇东昏主，金葉蓮花是此人。"]', '诗', 'shi', '', NULL, '比紅兒詩 七 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe71a808-e391-4347-b14b-010a68f4bacc', '比紅兒詩 八', '比紅兒诗 八', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["匼匝千山與萬山，碧桃花下景長閑。","神仙得似紅兒貌，應免劉郎憶世間。"]', '["匼匝千山與万山，碧桃花下景长闲。","神仙得似紅兒貌，應免劉郎憶世间。"]', '诗', 'shi', '', NULL, '比紅兒詩 八 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d22f0d5-cfe0-49c3-9626-3303a09dd5e0', '比紅兒詩 九', '比紅兒诗 九', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["越山重疊越溪斜，西子休憐解浣紗。","得似紅兒今日貌，肯教將去與夫差。"]', '["越山重叠越溪斜，西子休怜解浣紗。","得似紅兒今日貌，肯教將去與夫差。"]', '诗', 'shi', '', NULL, '比紅兒詩 九 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a34eb77f-f02c-4a01-a51d-3b2f02635208', '比紅兒詩 十', '比紅兒诗 十', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["詔下人間覓好花，月眉雲髻選人家。","紅兒若向當時見，繫臂先封第一紗。"]', '["詔下人间覓好花，月眉云髻選人家。","紅兒若向當时见，繫臂先封第一紗。"]', '诗', 'shi', '', NULL, '比紅兒詩 十 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e2a0765-2acf-4fcc-a642-4471eb046e77', '比紅兒詩 十一', '比紅兒诗 十一', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["鋒鏑縱橫不敢看，淚垂玉筯正汍瀾。","應緣近似紅兒貌，始得深宮奉五官。"]', '["鋒鏑縱橫不敢看，泪垂玉筯正汍瀾。","應緣近似紅兒貌，始得深宮奉五官。"]', '诗', 'shi', '', NULL, '比紅兒詩 十一 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0c160c9-cc4c-40e1-aee2-61355cb85ee3', '比紅兒詩 十二', '比紅兒诗 十二', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["金縷濃薰百和香，臉紅眉黛入時妝。","當時便向喬家見，未敢將心在窈娘。"]', '["金縷濃薰百和香，臉紅眉黛入时妝。","當时便向喬家见，未敢將心在窈娘。"]', '诗', 'shi', '', NULL, '比紅兒詩 十二 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a3df723-26e1-4895-b101-992d3f60f3c2', '比紅兒詩 十三', '比紅兒诗 十三', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["通宵甲帳散香塵，漢帝精神禮百神。","若見紅兒醉中態，也應休憶李夫人。"]', '["通宵甲帳散香塵，漢帝精神禮百神。","若见紅兒醉中態，也應休憶李夫人。"]', '诗', 'shi', '', NULL, '比紅兒詩 十三 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8f28cea-40ca-4610-8146-84fa16a9cb80', '比紅兒詩 十四', '比紅兒诗 十四', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["拔得芙蓉出水新，魏家公子信才人。","若教瞥見紅兒貌，不肯留情付洛神。"]', '["拔得芙蓉出水新，魏家公子信才人。","若教瞥见紅兒貌，不肯留情付洛神。"]', '诗', 'shi', '', NULL, '比紅兒詩 十四 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71094f9c-6a99-4ac2-aa15-2fe64d977b0e', '比紅兒詩 十五', '比紅兒诗 十五', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["芳姿不合竝常人，雲在遙天玉在塵。","因事愛思荀奉倩，一生閑坐枉傷神。"]', '["芳姿不合竝常人，云在遙天玉在塵。","因事愛思荀奉倩，一生闲坐枉傷神。"]', '诗', 'shi', '', NULL, '比紅兒詩 十五 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40abf11d-56dc-44dd-bbf5-b7e08d0fc020', '比紅兒詩 十六', '比紅兒诗 十六', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["筆底如風思湧泉，賦中休謾說嬋娟。","紅兒若在東家住，不得登牆爾許年。"]', '["笔底如风思湧泉，賦中休謾说嬋娟。","紅兒若在东家住，不得登牆爾許年。"]', '诗', 'shi', '', NULL, '比紅兒詩 十六 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75a198bc-6224-4a92-8d2d-a2c0733a8606', '比紅兒詩 十七', '比紅兒诗 十七', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["一抹濃紅傍臉斜，妝成不語獨攀花。","當時若是逢韓壽，未必埋蹤在賈家。"]', '["一抹濃紅傍臉斜，妝成不語独攀花。","當时若是逢韓壽，未必埋蹤在賈家。"]', '诗', 'shi', '', NULL, '比紅兒詩 十七 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f68ba854-2bc3-4cb3-954e-1650e07019de', '比紅兒詩 十八', '比紅兒诗 十八', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["樹褭西風日半沈，地無人跡轉傷心。","阿嬌得似紅兒貌，不費長門買賦金。"]', '["樹褭西风日半沈，地無人跡轉傷心。","阿嬌得似紅兒貌，不費长门買賦金。"]', '诗', 'shi', '', NULL, '比紅兒詩 十八 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('833f445e-49b4-4e6a-a22c-2220fda9592c', '比紅兒詩 十九', '比紅兒诗 十九', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["五雲高捧紫金堂，花下投壺侍玉皇。","從到世人都不識，也應知有杜蘭香。"]', '["五云高捧紫金堂，花下投壺侍玉皇。","從到世人都不識，也應知有杜蘭香。"]', '诗', 'shi', '', NULL, '比紅兒詩 十九 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6323813-4218-4833-b157-c4e8446059ed', '比紅兒詩 二十', '比紅兒诗 二十', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["戲水源頭指舊蹤，當時一笑也難逢。","紅兒若爲迴桃臉，豈比連催舉五烽。"]', '["戲水源头指旧蹤，當时一笑也难逢。","紅兒若爲迴桃臉，豈比連催舉五烽。"]', '诗', 'shi', '', NULL, '比紅兒詩 二十 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c834af82-e5c3-4010-8a90-16b0a8ceaa85', '比紅兒詩 二十一', '比紅兒诗 二十一', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["虢國夫人照夜璣，若爲求得與紅兒。","醉和香態濃春睡，一樹繁花偃繡幃。"]', '["虢国夫人照夜璣，若爲求得與紅兒。","醉和香態濃春睡，一樹繁花偃繡幃。"]', '诗', 'shi', '', NULL, '比紅兒詩 二十一 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9062b081-3c60-4e36-acc6-070e13201bcd', '比紅兒詩 二十二', '比紅兒诗 二十二', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["知有持盈玉葉冠，剪雲裁月照人寒。","若使紅兒風帽戴，直使瑤池會上看。"]', '["知有持盈玉葉冠，剪云裁月照人寒。","若使紅兒风帽戴，直使瑤池會上看。"]', '诗', 'shi', '', NULL, '比紅兒詩 二十二 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c74506df-e921-410d-874b-11e42400bf96', '比紅兒詩 二十三', '比紅兒诗 二十三', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["明媚何曾讓玉環，破瓜年幾百花顏。","若教貌向南朝見，定却梅妝似等閑。"]', '["明媚何曾讓玉环，破瓜年幾百花顏。","若教貌向南朝见，定却梅妝似等闲。"]', '诗', 'shi', '', NULL, '比紅兒詩 二十三 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11113a24-3cc2-47cd-9399-012923dec033', '比紅兒詩 二十四', '比紅兒诗 二十四', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["世事悠悠未足稱，肯將閑事更爭能。","自從命向紅兒去，不欲留心在裂繒。"]', '["世事悠悠未足稱，肯將闲事更爭能。","自從命向紅兒去，不欲留心在裂繒。"]', '诗', 'shi', '', NULL, '比紅兒詩 二十四 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ffd2413-b20f-4710-a3ee-afa1e39aa918', '比紅兒詩 二十五', '比紅兒诗 二十五', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["自隱新從夢裏來，嶺雲微步下陽臺。","含情一向春風笑，羞殺凡花盡不開。"]', '["自隐新從梦裏来，嶺云微步下陽台。","含情一向春风笑，羞殺凡花尽不开。"]', '诗', 'shi', '', NULL, '比紅兒詩 二十五 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d92efa0b-11ef-443a-9cd5-612833296cda', '比紅兒詩 二十六', '比紅兒诗 二十六', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["捨却青娥換玉鞍，古來公子苦無端。","莫言一匹追風馬，天驥牽來也不看。"]', '["捨却青娥換玉鞍，古来公子苦無端。","莫言一匹追风马，天驥牽来也不看。"]', '诗', 'shi', '', NULL, '比紅兒詩 二十六 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd2b35df-290f-4d2d-a235-a4923a92a7c2', '比紅兒詩 二十七', '比紅兒诗 二十七', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["檻外花低瑞露濃，夢魂驚覺暈春容。","憑君細看紅兒貌，最稱嚴妝待曉鐘。"]', '["檻外花低瑞露濃，梦魂驚覺暈春容。","憑君細看紅兒貌，最稱嚴妝待晓鐘。"]', '诗', 'shi', '', NULL, '比紅兒詩 二十七 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81634d75-7372-4294-9331-a5b7ea26cc6d', '比紅兒詩 二十八', '比紅兒诗 二十八', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["薄羅輕剪越溪紋，鵶翅低垂兩鬢分。","料得相如偷見面，不應琴裏挑文君。"]', '["薄羅轻剪越溪紋，鵶翅低垂兩鬢分。","料得相如偷见面，不應琴裏挑文君。"]', '诗', 'shi', '', NULL, '比紅兒詩 二十八 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff8cf61c-defd-4151-b745-b36f404c7737', '比紅兒詩 二十九', '比紅兒诗 二十九', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["南國東隣各一時，後來惟有杜紅兒。","若教楚國宮人見，羞把腰身竝柳枝。"]', '["南国东隣各一时，後来惟有杜紅兒。","若教楚国宮人见，羞把腰身竝柳枝。"]', '诗', 'shi', '', NULL, '比紅兒詩 二十九 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a363e26a-4d65-4c65-a69d-8096adc4850a', '比紅兒詩 三十', '比紅兒诗 三十', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["照耀金釵簇膩鬟，見時直向畫屏間。","黃姑阿母能判剖，十斛明珠也是閑。"]', '["照耀金釵簇膩鬟，见时直向畫屏间。","黄姑阿母能判剖，十斛明珠也是闲。"]', '诗', 'shi', '', NULL, '比紅兒詩 三十 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b15ca13f-c7b1-4cf8-8284-5a06537b49e1', '比紅兒詩 三十一', '比紅兒诗 三十一', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["輕小休誇似燕身，生來占斷紫宮春。","漢皇若遇紅兒貌，掌上無因著別人。"]', '["轻小休誇似燕身，生来占斷紫宮春。","漢皇若遇紅兒貌，掌上無因著別人。"]', '诗', 'shi', '', NULL, '比紅兒詩 三十一 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('627645b2-64f5-4820-85cd-f632ee91aaee', '比紅兒詩 三十二', '比紅兒诗 三十二', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["鸚鵡娥如裛露紅，鏡前眉樣自深宮。","稍教得似紅兒貌，不嫁南朝沈侍中。"]', '["鸚鵡娥如裛露紅，镜前眉樣自深宮。","稍教得似紅兒貌，不嫁南朝沈侍中。"]', '诗', 'shi', '', NULL, '比紅兒詩 三十二 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('623cddfa-c76d-4124-9990-09e6312f3711', '比紅兒詩 三十三', '比紅兒诗 三十三', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["擬將心地學安禪，爭奈紅兒笑靨圓。","何物把來堪比竝，野塘初綻一枝蓮。"]', '["擬將心地学安禪，爭奈紅兒笑靨圓。","何物把来堪比竝，野塘初綻一枝蓮。"]', '诗', 'shi', '', NULL, '比紅兒詩 三十三 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9843b04e-e2b7-412a-b732-2d251495ac7a', '比紅兒詩 三十四', '比紅兒诗 三十四', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["浸草漂花遶檻香，最憐穿度樂營牆。","殷勤留滯緣何事，曾照紅兒一面妝。"]', '["浸草漂花遶檻香，最怜穿度乐營牆。","殷勤留滯緣何事，曾照紅兒一面妝。"]', '诗', 'shi', '', NULL, '比紅兒詩 三十四 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('189c44ee-665f-45a3-8b91-a84d9da849e2', '比紅兒詩 三十五', '比紅兒诗 三十五', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["雕陰舊俗騁嬋娟，有箇紅兒賽洛川。","常笑世人語虛誕，今朝自見火中蓮。"]', '["雕陰旧俗騁嬋娟，有箇紅兒賽洛川。","常笑世人語虛誕，今朝自见火中蓮。"]', '诗', 'shi', '', NULL, '比紅兒詩 三十五 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b067cf3-276d-4ccd-83ec-e2d66ffe4021', '比紅兒詩 三十六', '比紅兒诗 三十六', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["渡口諸儂樂未休，竟陵西望路悠悠。","石城有箇紅兒貌，兩槳無因迎莫愁。"]', '["渡口諸儂乐未休，竟陵西望路悠悠。","石城有箇紅兒貌，兩槳無因迎莫愁。"]', '诗', 'shi', '', NULL, '比紅兒詩 三十六 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d517df33-bcf1-48bd-a07f-2e10fec94ffe', '比紅兒詩 三十七', '比紅兒诗 三十七', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["誰向深山識大仙，勸人山上引春泉。","定知不及紅兒貌，枉却工夫溉玉田。"]', '["誰向深山識大仙，勸人山上引春泉。","定知不及紅兒貌，枉却工夫溉玉田。"]', '诗', 'shi', '', NULL, '比紅兒詩 三十七 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5adb67da-9cfd-4916-872c-f82ac3a62493', '比紅兒詩 三十八', '比紅兒诗 三十八', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["傾國傾城總絕倫，紅兒花下認真身。","十年東北看燕趙，眼冷何曾見一人。"]', '["傾国傾城總絕倫，紅兒花下認真身。","十年东北看燕趙，眼冷何曾见一人。"]', '诗', 'shi', '', NULL, '比紅兒詩 三十八 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c21c4e63-d934-4719-88db-eaed333e426b', '比紅兒詩 三十九', '比紅兒诗 三十九', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["今時自是不諳知，前代由來豈見遺。","一笑陽城人便惑，何堪教見杜紅兒。"]', '["今时自是不諳知，前代由来豈见遺。","一笑陽城人便惑，何堪教见杜紅兒。"]', '诗', 'shi', '', NULL, '比紅兒詩 三十九 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60763208-6856-45d6-a7dc-9c2f5b96c92f', '比紅兒詩 四十', '比紅兒诗 四十', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["京口喧喧百萬人，競傳河鼓謝星津。","柰花似雪簪雲髻，今日夭容是後身。"]', '["京口喧喧百万人，競傳河鼓謝星津。","柰花似雪簪云髻，今日夭容是後身。"]', '诗', 'shi', '', NULL, '比紅兒詩 四十 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6853996b-8008-4218-932d-23146c75f435', '比紅兒詩 四十一', '比紅兒诗 四十一', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["青史書時未是真，可能纖手却強秦。","再三爲謝齊皇后，要解連環別與人。"]', '["青史书时未是真，可能纖手却強秦。","再三爲謝齊皇后，要解連环別與人。"]', '诗', 'shi', '', NULL, '比紅兒詩 四十一 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9a05bd4-c0d5-4efc-978f-0ab75f28d17e', '比紅兒詩 四十二', '比紅兒诗 四十二', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["繡帳鴛鴦對刺紋，博山微暖麝微曛。","詩成若有紅兒貌，悔道當時月墜雲。"]', '["繡帳鴛鴦对刺紋，博山微暖麝微曛。","诗成若有紅兒貌，悔道當时月墜云。"]', '诗', 'shi', '', NULL, '比紅兒詩 四十二 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e18eed56-1004-4ae4-a450-4a24348621c7', '比紅兒詩 四十三', '比紅兒诗 四十三', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["薄粉輕朱取次施，大都端正亦相宜。","只如花下紅兒態，不籍城中半額眉。"]', '["薄粉轻朱取次施，大都端正亦相宜。","只如花下紅兒態，不籍城中半額眉。"]', '诗', 'shi', '', NULL, '比紅兒詩 四十三 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f1a4414-794e-4462-a2c9-f5a6cb13d863', '比紅兒詩 四十四', '比紅兒诗 四十四', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["妝成渾欲認前朝，金鳳雙釵逐步搖。","未必慕容宮裏伴，舞風歌月勝纖腰。"]', '["妝成渾欲認前朝，金鳳雙釵逐步搖。","未必慕容宮裏伴，舞风歌月勝纖腰。"]', '诗', 'shi', '', NULL, '比紅兒詩 四十四 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('686ee78b-ebc0-49b0-8045-e04f38340e06', '比紅兒詩 四十五', '比紅兒诗 四十五', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["琥珀釵成恩正深，玉兒妖惑蕩君心。","莫教回首看妝面，始覺曾虛擲萬金。"]', '["琥珀釵成恩正深，玉兒妖惑蕩君心。","莫教回首看妝面，始覺曾虛擲万金。"]', '诗', 'shi', '', NULL, '比紅兒詩 四十五 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61220555-4104-41af-a341-0954c6bc0c30', '比紅兒詩 四十六', '比紅兒诗 四十六', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["自有閑花一面春，臉檀眉黛一時新。","殷勤爲報梁家婦，休把啼妝賺後人。"]', '["自有闲花一面春，臉檀眉黛一时新。","殷勤爲報梁家婦，休把啼妝賺後人。"]', '诗', 'shi', '', NULL, '比紅兒詩 四十六 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f452cb4d-099d-4e88-b391-055d482008bc', '比紅兒詩 四十七', '比紅兒诗 四十七', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["輕梳小髻號慵來，巧中君心不用媒。","可得紅兒拋醉眼，漢皇恩澤一時迴。"]', '["轻梳小髻號慵来，巧中君心不用媒。","可得紅兒拋醉眼，漢皇恩澤一时迴。"]', '诗', 'shi', '', NULL, '比紅兒詩 四十七 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1abaaf29-3b56-4be0-8906-e3b0f7c6ad24', '比紅兒詩 四十八', '比紅兒诗 四十八', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["千里長江旦暮潮，吳都風俗尚纖腰。","周郎若見紅兒貌，料得無心念小喬。"]', '["千里长江旦暮潮，吳都风俗尚纖腰。","周郎若见紅兒貌，料得無心念小喬。"]', '诗', 'shi', '', NULL, '比紅兒詩 四十八 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c3a3140-008a-4177-b3f9-ebc10885dc1b', '比紅兒詩 四十九', '比紅兒诗 四十九', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["月落潛奔暗解攜，本心誰道獨單棲。","還緣交甫非良偶，不肯終身作羿妻。"]', '["月落潛奔暗解携，本心誰道独單棲。","還緣交甫非良偶，不肯終身作羿妻。"]', '诗', 'shi', '', NULL, '比紅兒詩 四十九 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c9d3e0c-1b70-4fa5-a14f-12f4082c4670', '比紅兒詩 五十', '比紅兒诗 五十', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["漢皇曾識許飛瓊，寫向人間作畫屏。","昨日紅兒花下見，大都相似更娉婷。"]', '["漢皇曾識許飞瓊，寫向人间作畫屏。","昨日紅兒花下见，大都相似更娉婷。"]', '诗', 'shi', '', NULL, '比紅兒詩 五十 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db74640f-a50d-4153-a58e-ea43021c052f', '比紅兒詩 五十一', '比紅兒诗 五十一', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["魏帝休誇薛夜來，霧綃雲縠稱身裁。","紅兒秀發君知否，倚檻繁花帶露開。"]', '["魏帝休誇薛夜来，霧綃云縠稱身裁。","紅兒秀發君知否，倚檻繁花带露开。"]', '诗', 'shi', '', NULL, '比紅兒詩 五十一 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8d9d76c-f8fd-4dcc-8b41-d70b7a467bc2', '比紅兒詩 五十二', '比紅兒诗 五十二', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["曉月雕梁燕語頻，見花難可比他人。","年年媚景歸何處，長作紅兒面上春。"]', '["晓月雕梁燕語頻，见花难可比他人。","年年媚景归何处，长作紅兒面上春。"]', '诗', 'shi', '', NULL, '比紅兒詩 五十二 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7d67ecd-260f-4b51-879d-29d2005c79b3', '比紅兒詩 五十三', '比紅兒诗 五十三', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["逗玉濺盆冬殿開，邀恩先賜夜明苔。","紅兒若是三千數，多少芳心似死灰。"]', '["逗玉濺盆冬殿开，邀恩先賜夜明苔。","紅兒若是三千數，多少芳心似死灰。"]', '诗', 'shi', '', NULL, '比紅兒詩 五十三 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff2ad0f-01bd-4767-a4cb-18accd30dd0e', '比紅兒詩 五十四', '比紅兒诗 五十四', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["畫簾垂地紫金牀，暗引羊車駐七香。","若見紅兒此中住，不勞鹽篠灑宮廊。"]', '["畫簾垂地紫金牀，暗引羊车駐七香。","若见紅兒此中住，不勞鹽篠灑宮廊。"]', '诗', 'shi', '', NULL, '比紅兒詩 五十四 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e11b141-5dd2-419f-9472-8d4549262993', '比紅兒詩 五十五', '比紅兒诗 五十五', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["蘇小空勻一面妝，便留名字在錢塘。","藏鴉門外諸年少，不識紅兒未是狂。"]', '["蘇小空勻一面妝，便留名字在錢塘。","藏鴉门外諸年少，不識紅兒未是狂。"]', '诗', 'shi', '', NULL, '比紅兒詩 五十五 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03bb4352-a77c-4c6a-8cbf-f71c21d2ff31', '比紅兒詩 五十六', '比紅兒诗 五十六', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["一首長歌萬恨來，惹愁漂泊水難迴。","崔徽有底多頭面，費得微之爾許才。"]', '["一首长歌万恨来，惹愁漂泊水难迴。","崔徽有底多头面，費得微之爾許才。"]', '诗', 'shi', '', NULL, '比紅兒詩 五十六 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02c31b55-f809-4dd9-a006-4e6a1214a422', '比紅兒詩 五十七', '比紅兒诗 五十七', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["昔年黃閣識奇章，愛說真珠似窈娘。","若見紅兒深夜態，便應休說繡衣裳。"]', '["昔年黄閣識奇章，愛说真珠似窈娘。","若见紅兒深夜態，便應休说繡衣裳。"]', '诗', 'shi', '', NULL, '比紅兒詩 五十七 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08e4d798-aa70-4179-99e9-3dba785c10c9', '比紅兒詩 五十八', '比紅兒诗 五十八', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["鳳折鶯離恨轉深，此身難負百年心。","紅兒若向隋朝見，破鏡無因更重尋。"]', '["鳳折鶯離恨轉深，此身难負百年心。","紅兒若向隋朝见，破镜無因更重尋。"]', '诗', 'shi', '', NULL, '比紅兒詩 五十八 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35feb6ed-2694-451f-8254-7576f6f229a3', '比紅兒詩 五十九', '比紅兒诗 五十九', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["行綰穠雲立暗軒，我來猶愛不成冤。","當時若見紅兒貌，未必邢相有此言。"]', '["行綰穠云立暗軒，我来猶愛不成冤。","當时若见紅兒貌，未必邢相有此言。"]', '诗', 'shi', '', NULL, '比紅兒詩 五十九 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a39eba98-7a5e-46e9-8ec9-990243e699ea', '比紅兒詩 六十', '比紅兒诗 六十', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["總似紅兒媚態新，莫論千度笑爭春。","任伊孫武心如鐵，不辦軍前殺此人。"]', '["總似紅兒媚態新，莫論千度笑爭春。","任伊孫武心如鐵，不辦軍前殺此人。"]', '诗', 'shi', '', NULL, '比紅兒詩 六十 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d48789da-224e-4c28-b630-2bce485affda', '比紅兒詩 六十一', '比紅兒诗 六十一', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["暖塘爭赴盪舟期，行唱菱歌著豔詞。","爲問東山謝丞相，可能諸妓勝紅兒。"]', '["暖塘爭赴盪舟期，行唱菱歌著豔词。","爲问东山謝丞相，可能諸妓勝紅兒。"]', '诗', 'shi', '', NULL, '比紅兒詩 六十一 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60476b3f-0089-44e1-8880-e5876543c785', '比紅兒詩 六十二', '比紅兒诗 六十二', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["吳興皇后欲辭家，澤國重臺展曙華。","今日紅兒貌傾國，恐須真宰別開花。"]', '["吳兴皇后欲辞家，澤国重台展曙华。","今日紅兒貌傾国，恐須真宰別开花。"]', '诗', 'shi', '', NULL, '比紅兒詩 六十二 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe095972-9ef0-45b2-8213-6f066927cebe', '比紅兒詩 六十三', '比紅兒诗 六十三', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["陌上行人歌黍離，三千門客欲何之。","若教麤及紅兒貌，爭取樓前斬愛姬。"]', '["陌上行人歌黍離，三千门客欲何之。","若教麤及紅兒貌，爭取楼前斬愛姬。"]', '诗', 'shi', '', NULL, '比紅兒詩 六十三 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cb44b2a-bcf7-4327-a02f-9f7c2a56127f', '比紅兒詩 六十四', '比紅兒诗 六十四', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["休話如臯一笑時，金𩩉中臆錦離披。","陋容枉把雕弓射，射盡春禽未展眉。"]', '["休話如臯一笑时，金𩩉中臆錦離披。","陋容枉把雕弓射，射尽春禽未展眉。"]', '诗', 'shi', '', NULL, '比紅兒詩 六十四 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1677f456-809b-4acf-bee7-92e21aa1aeda', '比紅兒詩 六十五', '比紅兒诗 六十五', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["長恨西風送早秋，低眉深恨嫁牽牛。","若同人世長相對，爭作夫妻得到頭。"]', '["长恨西风送早秋，低眉深恨嫁牽牛。","若同人世长相对，爭作夫妻得到头。"]', '诗', 'shi', '', NULL, '比紅兒詩 六十五 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a20fb73b-3a5f-4bb4-bc7a-933aacc30635', '比紅兒詩 六十六', '比紅兒诗 六十六', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["謝娘休漫逞風姿，未必娉婷勝柳枝。","聞道只因嘲落絮，何曾得似杜紅兒。"]', '["謝娘休漫逞风姿，未必娉婷勝柳枝。","闻道只因嘲落絮，何曾得似杜紅兒。"]', '诗', 'shi', '', NULL, '比紅兒詩 六十六 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67758da2-9aea-4fa8-88a0-9d6b82569838', '比紅兒詩 六十七', '比紅兒诗 六十七', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["總傳桃葉渡江時，只爲王家一首詩。","今日紅兒自堪賦，不須重唱舊來詞。"]', '["總傳桃葉渡江时，只爲王家一首诗。","今日紅兒自堪賦，不須重唱旧来词。"]', '诗', 'shi', '', NULL, '比紅兒詩 六十七 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66ccfeaf-0afe-4c08-b371-f7942d73007c', '比紅兒詩 六十八', '比紅兒诗 六十八', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["巫山洛浦本無情，總爲佳人便得名。","今日雕陰有神豔，後來公子莫相輕。"]', '["巫山洛浦本無情，總爲佳人便得名。","今日雕陰有神豔，後来公子莫相轻。"]', '诗', 'shi', '', NULL, '比紅兒詩 六十八 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fe95965-0127-46a7-b2ef-0186448ac23a', '比紅兒詩 六十九', '比紅兒诗 六十九', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["幾拋雲髻恨金墉，淚洗花顏百戰中。","應有紅兒些子貌，却言皇后長深宮。"]', '["幾拋云髻恨金墉，泪洗花顏百戰中。","應有紅兒些子貌，却言皇后长深宮。"]', '诗', 'shi', '', NULL, '比紅兒詩 六十九 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac8f3200-c886-436f-8470-2fbc40cee571', '比紅兒詩 七十', '比紅兒诗 七十', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["倚檻還應有所思，半開東閣見嬌姿。","可中得似紅兒貌，若遇韓朋好殺伊。"]', '["倚檻還應有所思，半开东閣见嬌姿。","可中得似紅兒貌，若遇韓朋好殺伊。"]', '诗', 'shi', '', NULL, '比紅兒詩 七十 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76961a46-727f-45a9-9aed-67c63058dd6f', '比紅兒詩 七十一', '比紅兒诗 七十一', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["曉向妝臺與畫眉，鏡中長欲助嬌姿。","若教得似紅兒貌，走馬章臺任道遲。"]', '["晓向妝台與畫眉，镜中长欲助嬌姿。","若教得似紅兒貌，走马章台任道遲。"]', '诗', 'shi', '', NULL, '比紅兒詩 七十一 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1c1e4a3-4c1e-43e9-ad6f-7a692b8de559', '比紅兒詩 七十二', '比紅兒诗 七十二', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["練得霜華助翠鈿，相期朝謁玉皇前。","依稀有似紅兒貌，方得吹簫引上天。"]', '["練得霜华助翠鈿，相期朝謁玉皇前。","依稀有似紅兒貌，方得吹簫引上天。"]', '诗', 'shi', '', NULL, '比紅兒詩 七十二 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64593fe3-27b3-4486-8c73-e7472cfde4df', '比紅兒詩 七十三', '比紅兒诗 七十三', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["重門深掩幾枝花，未勝紅兒莫大誇。","王相不能探物理，可能虛上短轅車。"]', '["重门深掩幾枝花，未勝紅兒莫大誇。","王相不能探物理，可能虛上短轅车。"]', '诗', 'shi', '', NULL, '比紅兒詩 七十三 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b44fbc3-93bc-4bc6-b9a7-8ca466d19e29', '比紅兒詩 七十四', '比紅兒诗 七十四', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["前代休憐事可奇，後來還出有光輝。","爭知晝臥紗窗裏，不見神人覆玉衣。"]', '["前代休怜事可奇，後来還出有光輝。","爭知晝臥紗窗裏，不见神人覆玉衣。"]', '诗', 'shi', '', NULL, '比紅兒詩 七十四 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96fc80c7-a798-4841-9e5c-871f58d06737', '比紅兒詩 七十五', '比紅兒诗 七十五', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["化羽嘗聞赴九天，只疑塵世是虛傳。","自從一見紅兒貌，始信人間有謫仙。"]', '["化羽嘗闻赴九天，只疑塵世是虛傳。","自從一见紅兒貌，始信人间有謫仙。"]', '诗', 'shi', '', NULL, '比紅兒詩 七十五 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('270caa14-0611-4c73-bd14-8215fa28e39d', '比紅兒詩 七十六', '比紅兒诗 七十六', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["從道長陵小市東，巧將花貌占春風。","紅兒若是同時見，未必伊先入紫宮。"]', '["從道长陵小市东，巧將花貌占春风。","紅兒若是同时见，未必伊先入紫宮。"]', '诗', 'shi', '', NULL, '比紅兒詩 七十六 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40ef3ea3-22a6-461f-8a2b-a011ebf8c718', '比紅兒詩 七十七', '比紅兒诗 七十七', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["人間難免是深情，命斷紅兒向此生。","不似前時李丞相，枉拋才力爲鶯鶯。"]', '["人间难免是深情，命斷紅兒向此生。","不似前时李丞相，枉拋才力爲鶯鶯。"]', '诗', 'shi', '', NULL, '比紅兒詩 七十七 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5662a5a-00f1-4a52-82ce-9835a0a76cb5', '比紅兒詩 七十八', '比紅兒诗 七十八', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["鳳舞香飄繡幕風，暖穿馳道百花中。","還緣有似紅兒貌，始道迎將入漢宮。"]', '["鳳舞香飄繡幕风，暖穿驰道百花中。","還緣有似紅兒貌，始道迎將入漢宮。"]', '诗', 'shi', '', NULL, '比紅兒詩 七十八 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3125e54-d800-4281-a2b2-595040e7e60b', '比紅兒詩 七十九', '比紅兒诗 七十九', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["休道將軍出世才，盡驅諸妓下歌臺。","都緣沒箇紅兒貌，致使輕教後閣開。"]', '["休道將軍出世才，尽驱諸妓下歌台。","都緣沒箇紅兒貌，致使轻教後閣开。"]', '诗', 'shi', '', NULL, '比紅兒詩 七十九 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea6278f0-3327-43cf-882e-cf82ad2291f8', '比紅兒詩 八十', '比紅兒诗 八十', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["馮媛須知住漢宮，將身只是解當熊。","不聞有貌傾人國，爭得今朝更似紅。"]', '["馮媛須知住漢宮，將身只是解當熊。","不闻有貌傾人国，爭得今朝更似紅。"]', '诗', 'shi', '', NULL, '比紅兒詩 八十 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cf8b684-301f-4668-a0e9-4a33cc2cdd5b', '比紅兒詩 八十一', '比紅兒诗 八十一', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["能將一笑使人迷，花豔何須上大堤。","疎屬便同巫峽路，洛川真是武陵溪。"]', '["能將一笑使人迷，花豔何須上大堤。","疎屬便同巫峽路，洛川真是武陵溪。"]', '诗', 'shi', '', NULL, '比紅兒詩 八十一 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caeb49a8-5819-4799-8546-62e2ee95937d', '比紅兒詩 八十二', '比紅兒诗 八十二', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["辭輦當時意可知，寵深還恐寵先衰。","若教得似紅兒貌，占却君恩自不疑。"]', '["辞輦當时意可知，寵深還恐寵先衰。","若教得似紅兒貌，占却君恩自不疑。"]', '诗', 'shi', '', NULL, '比紅兒詩 八十二 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a132ad66-a7f5-4cf8-9039-501234b07c27', '比紅兒詩 八十三', '比紅兒诗 八十三', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["三吳時俗重風光，未見紅兒一面妝。","好寫妖嬈與教看，便應休更話真娘。"]', '["三吳时俗重风光，未见紅兒一面妝。","好寫妖嬈與教看，便應休更話真娘。"]', '诗', 'shi', '', NULL, '比紅兒詩 八十三 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68602aae-0354-44a5-8a0e-b55e9b4abd68', '比紅兒詩 八十四', '比紅兒诗 八十四', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["波平楚澤浸星辰，臺上君王宴早春。","畢竟章華會中客，冠纓虛絕爲何人。"]', '["波平楚澤浸星辰，台上君王宴早春。","畢竟章华會中客，冠纓虛絕爲何人。"]', '诗', 'shi', '', NULL, '比紅兒詩 八十四 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74becf1f-4f55-4e40-8fd0-09c0e72ab1c7', '比紅兒詩 八十五', '比紅兒诗 八十五', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["紅兒不向漢宮生，便使雙成謾得名。","疑是麻姑惱塵世，暫教微步下層城。"]', '["紅兒不向漢宮生，便使雙成謾得名。","疑是麻姑惱塵世，暫教微步下層城。"]', '诗', 'shi', '', NULL, '比紅兒詩 八十五 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c9a0923-b63d-455a-9cc1-368f7e90b72b', '比紅兒詩 八十六', '比紅兒诗 八十六', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["天碧輕紗只六銖，宛如含露透肌膚。","便教漢曲爭明媚，應沒心情更弄珠。"]', '["天碧轻紗只六銖，宛如含露透肌膚。","便教漢曲爭明媚，應沒心情更弄珠。"]', '诗', 'shi', '', NULL, '比紅兒詩 八十六 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('531e9264-c993-4084-a4b3-e79170015596', '比紅兒詩 八十七', '比紅兒诗 八十七', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["共嗟含恨向衡陽，方寸花牋寄沈郎。","不似紅兒些子貌，當時爭得少年狂。"]', '["共嗟含恨向衡陽，方寸花牋寄沈郎。","不似紅兒些子貌，當时爭得少年狂。"]', '诗', 'shi', '', NULL, '比紅兒詩 八十七 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8761ab06-216f-4fbe-8466-c98068fee128', '比紅兒詩 八十八', '比紅兒诗 八十八', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["淺色桃花亞短牆，不因風送也聞香。","凝情盡日君知否，還似紅兒淡薄妝。"]', '["淺色桃花亞短牆，不因风送也闻香。","凝情尽日君知否，還似紅兒淡薄妝。"]', '诗', 'shi', '', NULL, '比紅兒詩 八十八 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77499824-5ddf-4770-a8b8-8b672e085fe6', '比紅兒詩 八十九', '比紅兒诗 八十九', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["火色櫻桃摘得初，仙宮只有世間無。","凝情盡日君知否，真似紅兒口上朱。"]', '["火色櫻桃摘得初，仙宮只有世间無。","凝情尽日君知否，真似紅兒口上朱。"]', '诗', 'shi', '', NULL, '比紅兒詩 八十九 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca1b9c5f-e95d-4d6c-9558-1d00e4c7c7e3', '比紅兒詩 九十', '比紅兒诗 九十', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["宿雨初晴春日長，入簾花氣靜難忘。","凝情盡日君知否，真似紅兒舞袖香。"]', '["宿雨初晴春日长，入簾花氣静难忘。","凝情尽日君知否，真似紅兒舞袖香。"]', '诗', 'shi', '', NULL, '比紅兒詩 九十 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a695742-0317-47a5-99b4-c7cc028a3d94', '比紅兒詩 九十一', '比紅兒诗 九十一', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["初月纖纖映碧池，池波不動獨看時。","凝情盡日君知否，真似紅兒罷舞眉。"]', '["初月纖纖映碧池，池波不动独看时。","凝情尽日君知否，真似紅兒罷舞眉。"]', '诗', 'shi', '', NULL, '比紅兒詩 九十一 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f579f6a-a7aa-435f-bdb2-bfa4cd421587', '比紅兒詩 九十二', '比紅兒诗 九十二', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["濃豔濃香雪壓枝，褭煙和露曉風吹。","紅兒被掩妝成後，含笑無人獨立時。"]', '["濃豔濃香雪壓枝，褭煙和露晓风吹。","紅兒被掩妝成後，含笑無人独立时。"]', '诗', 'shi', '', NULL, '比紅兒詩 九十二 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceff3574-8f5e-49c1-a037-29e15bf87d54', '比紅兒詩 九十三', '比紅兒诗 九十三', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["樓上嬌歌褭夜霜，近來休數踏歌娘。","紅兒謾唱伊州遍，認取輕敲玉韻長。"]', '["楼上嬌歌褭夜霜，近来休數踏歌娘。","紅兒謾唱伊州遍，認取轻敲玉韻长。"]', '诗', 'shi', '', NULL, '比紅兒詩 九十三 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3e0be92-8f86-4b4d-b95c-1cb17d15eb77', '比紅兒詩 九十四', '比紅兒诗 九十四', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["金粟妝成扼臂環，舞腰輕薄瑞雲間。","紅兒生在開元末，羞殺新豐謝阿蠻。"]', '["金粟妝成扼臂环，舞腰轻薄瑞云间。","紅兒生在开元末，羞殺新豐謝阿蠻。"]', '诗', 'shi', '', NULL, '比紅兒詩 九十四 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6468afd-ebea-42a5-8cc3-a767699ea31e', '比紅兒詩 九十五', '比紅兒诗 九十五', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["君看紅兒學醉妝，誇裁宮襭砑裙長。","誰能更把閑心力，比竝當時武媚娘。"]', '["君看紅兒学醉妝，誇裁宮襭砑裙长。","誰能更把闲心力，比竝當时武媚娘。"]', '诗', 'shi', '', NULL, '比紅兒詩 九十五 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d46b6a56-03a6-4c4d-8215-5f52e02caab4', '比紅兒詩 九十六', '比紅兒诗 九十六', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["梔子同心裛露垂，折來深恐沒人知。","花前醉客頻相問，不贈紅兒贈阿誰。"]', '["梔子同心裛露垂，折来深恐沒人知。","花前醉客頻相问，不贈紅兒贈阿誰。"]', '诗', 'shi', '', NULL, '比紅兒詩 九十六 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84413e00-9309-4525-a6ad-667060ae69e2', '比紅兒詩 九十七', '比紅兒诗 九十七', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["雲間翡翠一雙飛，水上鴛鴦不暫離。","寫向人間百般態，與君題作比紅詩。"]', '["云间翡翠一雙飞，水上鴛鴦不暫離。","寫向人间百般態，與君題作比紅诗。"]', '诗', 'shi', '', NULL, '比紅兒詩 九十七 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea19a565-d34a-459a-b5f0-46a40c89078e', '比紅兒詩 九十八', '比紅兒诗 九十八', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["舊恨長懷不語中，幾回偷泣向春風。","還緣不及紅兒貌，却得生教入楚宮。"]', '["旧恨长懷不語中，幾回偷泣向春风。","還緣不及紅兒貌，却得生教入楚宮。"]', '诗', 'shi', '', NULL, '比紅兒詩 九十八 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1cde0ca-ca8b-4752-9a84-7a476dfa041e', '比紅兒詩 九十九', '比紅兒诗 九十九', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["一舸春深指鄂君，好風從度水成紋。","越人若見紅兒貌，繡被應羞徹夜薰。"]', '["一舸春深指鄂君，好风從度水成紋。","越人若见紅兒貌，繡被應羞徹夜薰。"]', '诗', 'shi', '', NULL, '比紅兒詩 九十九 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76a06d68-949a-4fa1-b742-0eeb039e197a', '比紅兒詩 一百', '比紅兒诗 一百', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["花落塵中玉墮泥，香魂應上窈娘堤。","欲知此恨無窮處，長倩城烏夜夜啼。"]', '["花落塵中玉墮泥，香魂應上窈娘堤。","欲知此恨無窮处，长倩城烏夜夜啼。"]', '诗', 'shi', '', NULL, '比紅兒詩 一百 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b59ebaa7-8bae-4973-a57a-e032b22a2e74', '句', '句', '9ad7bac2-f5b9-48d2-a8a3-5266ab4fb88f', '唐', '["窗前遠岫懸生碧，簾外殘霞挂熟紅。"]', '["窗前远岫懸生碧，簾外殘霞挂熟紅。"]', '诗', 'shi', '', NULL, '句 羅虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00702981-1884-4b20-99fc-354e8ced4aa0', '星精亭', '星精亭', 'a9bcb2a2-efcb-4dba-9b56-0af85ed23a33', '唐', '["星沈萬古痕，孤絕勢無鄰。","地窄少留竹，空多剩占雲。","釣篷和雨看，樵斧帶霜聞。","莫惜尋常到，清風不負人。"]', '["星沈万古痕，孤絕勢無鄰。","地窄少留竹，空多剩占云。","釣篷和雨看，樵斧带霜闻。","莫惜尋常到，清风不負人。"]', '诗', 'shi', '', NULL, '星精亭 鄭損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f57365ae-b81f-4729-ac92-8b9da3ebf708', '釣閣', '釣閣', 'a9bcb2a2-efcb-4dba-9b56-0af85ed23a33', '唐', '["小閣愜幽尋，周遭萬竹森。","誰知一沼內，亦有五湖心。","釣直魚應笑，身閑樂自深。","晚來春醉熟，香餌任浮沈。"]', '["小閣愜幽尋，周遭万竹森。","誰知一沼內，亦有五湖心。","釣直鱼應笑，身闲乐自深。","晚来春醉熟，香餌任浮沈。"]', '诗', 'shi', '', NULL, '釣閣 鄭損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30f95f18-fa3a-4bb9-8a75-61744687a5f1', '玉聲亭', '玉声亭', 'a9bcb2a2-efcb-4dba-9b56-0af85ed23a33', '唐', '["世間泉石本無價，那更天然落景中。","漢佩琮琤寒溜雨，秦簫縹緲夜敲風。","一方清氣羣陰伏，半局閑棋萬慮空。","借問主人能住久，後來好事有誰同。"]', '["世间泉石本無價，那更天然落景中。","漢佩琮琤寒溜雨，秦簫縹緲夜敲风。","一方清氣羣陰伏，半局闲棋万慮空。","借问主人能住久，後来好事有誰同。"]', '诗', 'shi', '', NULL, '玉聲亭 鄭損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5efaec0e-670b-4f46-89a6-214d5cf06f5b', '藝堂', '藝堂', 'a9bcb2a2-efcb-4dba-9b56-0af85ed23a33', '唐', '["堂開凍石千年翠，藝講秋膠百步威。","揖讓未能忘典禮，英雄孰不慣戎衣。","風波險似金機駭，日月忙如雪羽飛。","莫怪尊前頻浩歎，男兒志願與時違。"]', '["堂开凍石千年翠，藝講秋膠百步威。","揖讓未能忘典禮，英雄孰不慣戎衣。","风波險似金機駭，日月忙如雪羽飞。","莫怪尊前頻浩歎，男兒志願與时違。"]', '诗', 'shi', '', NULL, '藝堂 鄭損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85edeea7-a75d-43df-aebd-b92720f096ee', '星精石', '星精石', 'a9bcb2a2-efcb-4dba-9b56-0af85ed23a33', '唐', '["突險呀空龍虎蹲，由來英氣蓄寒根。","蒼苔點染雲生靨，老雨淋漓鐵漬痕。","松韻遠趨疑認祖，山陰輕覆似憐孫。","孤巖恰恰容幽搆，可愛江南釋子園。"]', '["突險呀空龙虎蹲，由来英氣蓄寒根。","蒼苔点染云生靨，老雨淋漓鐵漬痕。","松韻远趨疑認祖，山陰轻覆似怜孫。","孤巖恰恰容幽搆，可愛江南釋子园。"]', '诗', 'shi', '', NULL, '星精石 鄭損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdca155c-6b4e-493f-8e12-f9705df9e1eb', '泛香亭', '泛香亭', 'a9bcb2a2-efcb-4dba-9b56-0af85ed23a33', '唐', '["流杯處處稱佳致，何似斯亭出自然。","山溜穿雲來幾里，石盤和蘚鑿何年。","聲交鳴玉歌沈板，色幌寒金酒滿船。","莫怪坐中難得醉，醒人心骨有潺湲。"]', '["流杯处处稱佳致，何似斯亭出自然。","山溜穿云来幾里，石盤和蘚鑿何年。","声交鳴玉歌沈板，色幌寒金酒满船。","莫怪坐中难得醉，醒人心骨有潺湲。"]', '诗', 'shi', '', NULL, '泛香亭 鄭損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ef9625-cf5a-4a58-a217-26c26733f917', '巴州寒食晚眺', '巴州寒食晚眺', '86b128ea-edda-475d-9680-cb903b68ce80', '唐', '["東望青天周與秦，杏花榆葉故園春。","野寺一傾寒食酒，晚來風景重愁人。"]', '["东望青天周與秦，杏花榆葉故园春。","野寺一傾寒食酒，晚来风景重愁人。"]', '诗', 'shi', '', NULL, '巴州寒食晚眺 張禕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8493466b-7eb6-4de2-8143-12786a652f70', '題擊甌樓', '題擊甌楼', '86b128ea-edda-475d-9680-cb903b68ce80', '唐', '["駐旌元師遺風在，擊缶高人逸興酣。","水轉巴文清溜急，山連蒙岫翠光涵。"]', '["駐旌元師遺风在，擊缶高人逸兴酣。","水轉巴文清溜急，山連蒙岫翠光涵。"]', '诗', 'shi', '', NULL, '題擊甌樓 張禕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6107fb38-ce0c-497c-a35f-ac7d24961f84', '題司空圖壁', '題司空圖壁', '454dc637-1421-4704-a021-dc91cd2a6062', '唐', '["姓氏司空貴，官班御史卑。","老夫如且在，不用歎屯奇。"]', '["姓氏司空貴，官班御史卑。","老夫如且在，不用歎屯奇。"]', '诗', 'shi', '', NULL, '題司空圖壁 盧攜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ce5740-8899-4cc1-ae6b-7aad23851365', '愁詩', '愁诗', '9bacc4a8-ec2f-46cb-a4ea-451bdc657f1f', '唐', '["到來難遣去難留，著骨黏心萬事休。","潘岳愁絲生鬢裏，婕妤悲色上眉頭。","長途詩盡空騎馬，遠雁聲初獨倚樓。","更有相思不相見，酒醒燈背月如鉤。"]', '["到来难遣去难留，著骨黏心万事休。","潘岳愁絲生鬢裏，婕妤悲色上眉头。","长途诗尽空騎马，远雁声初独倚楼。","更有相思不相见，酒醒灯背月如鉤。"]', '诗', 'shi', '', NULL, '愁詩 李廷璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b2492bf-0268-4378-9572-b1d9991e930b', '題菖蒲廢觀', '題菖蒲廢观', 'a731dd1c-efe0-42cc-86d7-8e45b94dd037', '唐', '["本是安期燒藥處，今來改作坐禪宮。","數僧梵響滿樓月，深谷猨聲半夜風。","金簡事移松閣逈，綵雲影散閬山空。","我來不見修真客，却得真如問遠公。"]', '["本是安期燒藥处，今来改作坐禪宮。","數僧梵响满楼月，深谷猨声半夜风。","金簡事移松閣逈，綵云影散閬山空。","我来不见修真客，却得真如问远公。"]', '诗', 'shi', '', NULL, '題菖蒲廢觀 許三畏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f709530-f1bd-452c-af6d-eb87040360ab', '致孫狀元訴醵罰錢', '致孫狀元訴醵罰錢', '2282e45b-baeb-4ee2-9ea3-be8b74abda23', '唐', '["未識都君面，頻輸復分錢。","苦心事筆硯，得志助花鈿。","徒步求秋賦，持杯給暮饘。","力微多謝病，非不奉同年。"]', '["未識都君面，頻輸复分錢。","苦心事笔硯，得志助花鈿。","徒步求秋賦，持杯給暮饘。","力微多謝病，非不奉同年。"]', '诗', 'shi', '', NULL, '致孫狀元訴醵罰錢 盧嗣業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4962c05-fe08-4951-a08c-d92d4b36600e', '紅薔薇', '紅薔薇', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["曉啼珠露渾無力，繡簇羅襦不著行。","若綴壽陽公主額，六宮爭肯學梅妝。"]', '["晓啼珠露渾無力，繡簇羅襦不著行。","若綴壽陽公主額，六宮爭肯学梅妝。"]', '诗', 'shi', '', NULL, '紅薔薇 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92867325-bf68-467d-955c-7d786fd1f323', '楊柳枝五首 一', '楊柳枝五首 一', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["解凍風來末上青，解垂羅袖拜卿卿。","無端褭娜臨官路，舞送行人過一生。"]', '["解凍风来末上青，解垂羅袖拜卿卿。","無端褭娜臨官路，舞送行人過一生。"]', '诗', 'shi', '', NULL, '楊柳枝五首 一 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76816c38-6228-4031-987d-c51b7ae83754', '楊柳枝五首 二', '楊柳枝五首 二', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["吳王宮裏色偏深，一簇纖條萬縷金。","不憤錢塘蘇小小，引郎松下結同心。"]', '["吳王宮裏色偏深，一簇纖條万縷金。","不憤錢塘蘇小小，引郎松下結同心。"]', '诗', 'shi', '', NULL, '楊柳枝五首 二 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18b8df01-9b32-498d-9bac-a846ffd84ba2', '楊柳枝五首 三', '楊柳枝五首 三', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["橋北橋南千萬條，恨伊張緒不相饒。","金羈白馬臨風望，認得羊家靜婉腰。"]', '["橋北橋南千万條，恨伊張緒不相饒。","金羈白马臨风望，認得羊家静婉腰。"]', '诗', 'shi', '', NULL, '楊柳枝五首 三 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ec5727e-4722-4438-af80-5b74d4ef8a2a', '楊柳枝五首 四', '楊柳枝五首 四', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["狂雪隨風撲馬飛，惹煙無力被春欺。","莫交移入靈和殿，宮女三千又妬伊。"]', '["狂雪隨风撲马飞，惹煙無力被春欺。","莫交移入靈和殿，宮女三千又妬伊。"]', '诗', 'shi', '', NULL, '楊柳枝五首 四 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6de0bcf-3042-4e60-a4c8-a5a349addcaf', '楊柳枝五首 五', '楊柳枝五首 五', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["褭翠籠煙拂暖波，舞裙新染麴塵羅。","章華臺畔隋堤上，傍得春風爾許多。"]', '["褭翠籠煙拂暖波，舞裙新染麴塵羅。","章华台畔隋堤上，傍得春风爾許多。"]', '诗', 'shi', '', NULL, '楊柳枝五首 五 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db0a1e37-c624-4b33-ad24-94398d599802', '及第後宿平康里詩', '及第後宿平康里诗', 'd51e3cd6-bb8b-40ed-8ff8-9516746e1b7a', '唐', '["春來無處不閑行，楚潤相看別有情。","好是五更殘酒醒，時時聞喚狀頭聲。"]', '["春来無处不闲行，楚潤相看別有情。","好是五更殘酒醒，时时闻喚狀头声。"]', '诗', 'shi', '', NULL, '及第後宿平康里詩 鄭合 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83f5d2a2-8465-4c96-8cf5-1e24ddc1e90b', '賀裴廷裕蜀中登第詩', '賀裴廷裕蜀中登第诗', 'a542d160-ed77-4344-8f9b-0d0a846b576c', '唐', '["銅梁千里曙雲開，仙籙新從紫府來。","天上已張新羽翼，世間無復舊塵埃。","嘉禎果中君平卜，賀喜須斟卓氏杯。","應笑戎藩刀筆吏，至今泥滓曝魚鰓。"]', '["銅梁千里曙云开，仙籙新從紫府来。","天上已張新羽翼，世间無复旧塵埃。","嘉禎果中君平卜，賀喜須斟卓氏杯。","應笑戎藩刀笔吏，至今泥滓曝鱼鰓。"]', '诗', 'shi', '', NULL, '賀裴廷裕蜀中登第詩 李搏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1dcabfb-6314-4406-a45f-4162149e5977', '復謔廷裕', '复謔廷裕', 'a542d160-ed77-4344-8f9b-0d0a846b576c', '唐', '["曾隨風水化凡鱗，安上門前一字新。","聞道蜀江風景好，不知何似杏園春。"]', '["曾隨风水化凡鱗，安上门前一字新。","闻道蜀江风景好，不知何似杏园春。"]', '诗', 'shi', '', NULL, '復謔廷裕 李搏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e5447e5-dc6e-4519-bee1-09481b758b9a', '弔賈島', '弔賈島', '79533707-e7a6-41ef-98c2-b48ee2fb2f7f', '唐', '["一一玄微縹緲成，盡吟方便爽神情。","宣宗謫去爲閑事，韓愈知來已振名。","海底也應搜得淨，月輪常被翫教傾。","如何未隔四十載，不遇論量向此生。"]', '["一一玄微縹緲成，尽吟方便爽神情。","宣宗謫去爲闲事，韓愈知来已振名。","海底也應搜得淨，月輪常被翫教傾。","如何未隔四十載，不遇論量向此生。"]', '诗', 'shi', '', NULL, '弔賈島 李克恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bbdfa76-fd12-449f-963f-d99ff6c24bec', '君山', '君山', 'ecb8a59e-89b3-4e8b-aff3-76b2d4d7b21e', '唐', '["曾游方外見麻姑，說道君山此本無。","云是崑崙山頂石，海風吹落洞庭湖。"]', '["曾游方外见麻姑，说道君山此本無。","云是崑崙山頂石，海风吹落洞庭湖。"]', '诗', 'shi', '', NULL, '君山 程賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab1178b9-4801-40c5-a563-b9114e399f0e', '東歸詩', '东归诗', 'f66c6624-9289-4c82-bb26-baba7f4bc7bf', '唐', '["九重丹詔下塵埃，深鎖文闈罷選才。","桂樹放教遮月長，杏園終待隔年開。","自從玉帳論兵後，不許金門諫獵來。","今日灞陵橋上過，路人應笑臘前迴。"]', '["九重丹詔下塵埃，深鎖文闈罷選才。","桂樹放教遮月长，杏园終待隔年开。","自從玉帳論兵後，不許金门諫獵来。","今日灞陵橋上過，路人應笑臘前迴。"]', '诗', 'shi', '', NULL, '東歸詩 盧尚卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3094805-6555-451f-a470-cc323adbcc47', '題玉芝雙奉院', '題玉芝雙奉院', '80a12542-2f41-49a9-8ae6-61dd4987e6db', '唐', '["入門如洞府，花木與時稀。","夜坐山當戶，秋吟葉滿衣。","犬隨童子出，鳥避俗人飛。","至藥應將熟，年年火氣微。"]', '["入门如洞府，花木與时稀。","夜坐山當戶，秋吟葉满衣。","犬隨童子出，鸟避俗人飞。","至藥應將熟，年年火氣微。"]', '诗', 'shi', '', NULL, '題玉芝雙奉院 顧在鎔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c03b5b7-c53d-4da6-90d2-4552f40a24e8', '宿麻平驛', '宿麻平驛', '80a12542-2f41-49a9-8ae6-61dd4987e6db', '唐', '["及到怡情處，暫忘登陟勞。","青山看不厭，明月坐來高。","犬爲孤村吠，猨因冷木號。","微吟還獨酌，多興憶同袍。"]', '["及到怡情处，暫忘登陟勞。","青山看不厭，明月坐来高。","犬爲孤村吠，猨因冷木號。","微吟還独酌，多兴憶同袍。"]', '诗', 'shi', '', NULL, '宿麻平驛 顧在鎔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8051063e-2f72-4ec8-b708-5fe6e91796d4', '題光福上方塔', '題光福上方塔', '80a12542-2f41-49a9-8ae6-61dd4987e6db', '唐', '["蒼島孤生白浪中，倚天高塔勢翻空。","煙凝遠岫列寒翠，霜染疎林墮碎紅。","汀沼或栖彭澤雁，樓臺深貯洞庭風。","六時金磬落何處，偏傍蘆葦驚釣翁。"]', '["蒼島孤生白浪中，倚天高塔勢翻空。","煙凝远岫列寒翠，霜染疎林墮碎紅。","汀沼或栖彭澤雁，楼台深貯洞庭风。","六时金磬落何处，偏傍蘆葦驚釣翁。"]', '诗', 'shi', '', NULL, '題光福上方塔 顧在鎔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d9187f6-5ce1-4d0d-8c64-89a78062aefe', '枯木詩辭召命作', '枯木诗辞召命作', 'ae4efaf8-d8bb-4185-9a72-270e76aae79e', '唐', '["枯木傍溪崖，由來歲月賒。","有根盤水石，無葉接煙霞。","二月苔爲色，三冬雪作花。","不因星使至，誰識是靈槎。"]', '["枯木傍溪崖，由来歲月賒。","有根盤水石，無葉接煙霞。","二月苔爲色，三冬雪作花。","不因星使至，誰識是靈槎。"]', '诗', 'shi', '', NULL, '枯木詩辭召命作 翁洮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f55ae53-5d28-4ed4-903f-722e4a8f3d2f', '贈進士王雄', '贈進士王雄', 'ae4efaf8-d8bb-4185-9a72-270e76aae79e', '唐', '["河清海晏少波濤，幾載垂鉤不得鰲。","空向人間修諫草，又來江上詠離騷。","笳吹古堞邊聲遠，嶽倚晴空楚色高。","何事明廷有徐庶，總教三徑臥蓬蒿。"]', '["河清海晏少波濤，幾載垂鉤不得鰲。","空向人间修諫草，又来江上詠離騷。","笳吹古堞邊声远，嶽倚晴空楚色高。","何事明廷有徐庶，總教三徑臥蓬蒿。"]', '诗', 'shi', '', NULL, '贈進士王雄 翁洮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8586f5d9-1996-4180-b4ad-1c5ff27b6f31', '漁者', '漁者', 'ae4efaf8-d8bb-4185-9a72-270e76aae79e', '唐', '["一葉飄然任浪吹，雨蓑煙笠肯忘機。","只貪濁水張羅衆，却笑清流把釣稀。","葦岸夜依明月宿，柴門晴櫂白雲歸。","到頭得喪終須達，誰道漁樵有是非。"]', '["一葉飄然任浪吹，雨蓑煙笠肯忘機。","只貪濁水張羅衆，却笑清流把釣稀。","葦岸夜依明月宿，柴门晴櫂白云归。","到头得喪終須達，誰道漁樵有是非。"]', '诗', 'shi', '', NULL, '漁者 翁洮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('331c965b-59bc-4aa1-9d92-ffeae5363c43', '上子男壽昌宰', '上子男壽昌宰', 'ae4efaf8-d8bb-4185-9a72-270e76aae79e', '唐', '["陶公爲政卓潘齊，入縣看花柳滿堤。","百里江山聊展驥，九臯雲月怪驅雞。","高樓野色迎襟袖，比屋歌聲遠鼓鼙。","只恐攀轅留不住，明時霄漢有丹梯。"]', '["陶公爲政卓潘齊，入縣看花柳满堤。","百里江山聊展驥，九臯云月怪驱雞。","高楼野色迎襟袖，比屋歌声远鼓鼙。","只恐攀轅留不住，明时霄漢有丹梯。"]', '诗', 'shi', '', NULL, '上子男壽昌宰 翁洮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51845837-bc79-4637-83ab-3b1b01b1c439', '贈方干先生', '贈方干先生', 'ae4efaf8-d8bb-4185-9a72-270e76aae79e', '唐', '["由來箕踞任天真，別有詩名出世塵。","不愛春宮分桂樹，欲教天子枉蒲輪。","城頭鼙鼓三聲曉，島外湖山一簇春。","獨向若耶溪上住，誰知不是釣鰲人。"]', '["由来箕踞任天真，別有诗名出世塵。","不愛春宮分桂樹，欲教天子枉蒲輪。","城头鼙鼓三声晓，島外湖山一簇春。","独向若耶溪上住，誰知不是釣鰲人。"]', '诗', 'shi', '', NULL, '贈方干先生 翁洮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5f8aec8-f9c4-42c3-9231-a2bcaac4bfc6', '贈進士李德新接海棠梨', '贈進士李德新接海棠梨', 'ae4efaf8-d8bb-4185-9a72-270e76aae79e', '唐', '["蜀人猶說種難成，何事江東見接生。","席上若微桃李伴，花中堪作牡丹兄。","高軒日午爭濃豔，小徑風移旋落英。","一種呈妍今得地，劒峯梨嶺謾縱橫。"]', '["蜀人猶说種难成，何事江东见接生。","席上若微桃李伴，花中堪作牡丹兄。","高軒日午爭濃豔，小徑风移旋落英。","一種呈妍今得地，劒峯梨嶺謾縱橫。"]', '诗', 'shi', '', NULL, '贈進士李德新接海棠梨 翁洮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ed1a442-e3f4-4e4e-90e0-5d0a486d411f', '春日題航頭橋', '春日題航头橋', 'ae4efaf8-d8bb-4185-9a72-270e76aae79e', '唐', '["故園橋上絕埃塵，此日凭欄興自新。","雲影晚將仙掌曙，水光迷得武陵春。","薜蘿煙裏高低路，楊柳風前去住人。","莫怪馬卿題姓字，終朝雲雨化龍津。"]', '["故园橋上絕埃塵，此日凭欄兴自新。","云影晚將仙掌曙，水光迷得武陵春。","薜蘿煙裏高低路，楊柳风前去住人。","莫怪马卿題姓字，終朝云雨化龙津。"]', '诗', 'shi', '', NULL, '春日題航頭橋 翁洮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a039c3-7a33-47de-9d8a-f3588903567b', '和方干題李頻莊', '和方干題李頻莊', 'ae4efaf8-d8bb-4185-9a72-270e76aae79e', '唐', '["高情度日非無事，自是高情不覺喧。","海氣暗蒸蓮葉沼，山光晴逗葦花村。","吟時勝概題詩板，靜處繁華付酒尊。","閑伴白雲收桂子，每尋流水斸桐孫。","猶憑律呂傳心曲，豈慮星霜到鬢根。","多少清風歸此地，十年虛打五侯門。"]', '["高情度日非無事，自是高情不覺喧。","海氣暗蒸蓮葉沼，山光晴逗葦花村。","吟时勝概題诗板，静处繁华付酒尊。","闲伴白云收桂子，每尋流水斸桐孫。","猶憑律呂傳心曲，豈慮星霜到鬢根。","多少清风归此地，十年虛打五侯门。"]', '诗', 'shi', '', NULL, '和方干題李頻莊 翁洮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6adad82-5424-4c5f-be8c-b633dc7e97d5', '葦藂', '葦藂', 'ae4efaf8-d8bb-4185-9a72-270e76aae79e', '唐', '["得地自成藂，那因種植功。","有花皆吐雪，無韻不含風。","倒影翹沙鳥，幽根立水蟲。","蕭蕭寒雨夜，江漢思無窮。"]', '["得地自成藂，那因種植功。","有花皆吐雪，無韻不含风。","倒影翹沙鸟，幽根立水蟲。","蕭蕭寒雨夜，江漢思無窮。"]', '诗', 'shi', '', NULL, '葦藂 翁洮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed8d28d3-de97-4fce-a400-ec9e614e439f', '春', '春', 'ae4efaf8-d8bb-4185-9a72-270e76aae79e', '唐', '["漠漠煙花處處通，游人南北思無窮。","林間鳥奏笙簧月，野外花含錦繡風。","鸑抱雲霞朝鳳闕，魚翻波浪化龍宮。","此時誰羨神仙客，車馬悠揚九陌中。"]', '["漠漠煙花处处通，游人南北思無窮。","林间鸟奏笙簧月，野外花含錦繡风。","鸑抱云霞朝鳳闕，鱼翻波浪化龙宮。","此时誰羨神仙客，车马悠揚九陌中。"]', '诗', 'shi', '', NULL, '春 翁洮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ce6a1a5-02fe-466a-ac43-a51527287265', '夏', '夏', 'ae4efaf8-d8bb-4185-9a72-270e76aae79e', '唐', '["觸目皆因長養功，浮生何處問窮通？","柳長北闕絲千縷，雲簇南山火萬籠。","大野煙塵飄赫日，高樓簾幕逗薰風。","身心已在喧闐處，惟羨滄浪把釣翁。"]', '["觸目皆因长養功，浮生何处问窮通？","柳长北闕絲千縷，云簇南山火万籠。","大野煙塵飄赫日，高楼簾幕逗薰风。","身心已在喧闐处，惟羨滄浪把釣翁。"]', '诗', 'shi', '', NULL, '夏 翁洮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d188839-d47a-4360-abe1-d55bca5d58ce', '秋', '秋', 'ae4efaf8-d8bb-4185-9a72-270e76aae79e', '唐', '["宋玉高吟思萬重，澄澄寰宇振金風。","雲閑日月浮虛白，木落山川疊碎紅。","寥泬鴈多宮漏永，河渠煙歛塞天空。","侯門處處槐花□，獻賦何時遇至公。"]', '["宋玉高吟思万重，澄澄寰宇振金风。","云闲日月浮虛白，木落山川叠碎紅。","寥泬鴈多宮漏永，河渠煙歛塞天空。","侯门处处槐花□，獻賦何时遇至公。"]', '诗', 'shi', '', NULL, '秋 翁洮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2ff1d77-9e5f-43de-8784-aa75a6593df9', '冬', '冬', 'ae4efaf8-d8bb-4185-9a72-270e76aae79e', '唐', '["寂寂棲心向杳冥，苦吟寒律句偏清。","雲凝止水魚龍蟄，雪點遙峰草木榮。","迥夜爐飜埃燼色，天河冰輾轆轤聲。","歸飛未得東風力，魂斷三山九萬程。"]', '["寂寂棲心向杳冥，苦吟寒律句偏清。","云凝止水鱼龙蟄，雪点遙峰草木榮。","迥夜爐飜埃燼色，天河冰輾轆轤声。","归飞未得东风力，魂斷三山九万程。"]', '诗', 'shi', '', NULL, '冬 翁洮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c1728cc-0e6c-4d66-a1e2-883b1d75033f', '過洞庭', '過洞庭', 'c86a79e0-4b76-4f1a-a2b4-8d0d8c0e2f97', '唐', '["浩渺注橫流，千潭合萬湫。","半洪侵楚翼，一汊屬吳頭。","動軸當新霽，漫空正仲秋。","勢翻荆口迮，聲擁岳陽浮。","遠脈滋衡岳，微涼散橘州。","星辰連影動，嵐翠逐隅收。","漸落分行鴈，旋添趁伴舟。","昇騰人莫測，安穩路何憂。","氣與塵中別，言堪象外搜。","此身如麤了，來把一竿休。"]', '["浩渺注橫流，千潭合万湫。","半洪侵楚翼，一汊屬吳头。","动軸當新霽，漫空正仲秋。","勢翻荆口迮，声擁岳陽浮。","远脈滋衡岳，微涼散橘州。","星辰連影动，嵐翠逐隅收。","漸落分行鴈，旋添趁伴舟。","昇腾人莫測，安穩路何憂。","氣與塵中別，言堪象外搜。","此身如麤了，来把一竿休。"]', '诗', 'shi', '', NULL, '過洞庭 李嶼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c9a41be-b656-4039-9c12-ce4831a89af2', '嚴塘經亂書事 一', '嚴塘經亂书事 一', 'cdec67ae-9862-4672-ac34-afbcbdf7b595', '唐', '["塵生宮闕霧濛濛，萬騎龍飛幸蜀中。","在野傅巖君不夢，乘軒衛懿鶴何功。","雖知四海同盟久，未合中原武備空。","星落夜原妖氣滿，漢家麟閣待英雄。"]', '["塵生宮闕霧濛濛，万騎龙飞幸蜀中。","在野傅巖君不梦，乘軒衛懿鹤何功。","雖知四海同盟久，未合中原武備空。","星落夜原妖氣满，漢家麟閣待英雄。"]', '诗', 'shi', '', NULL, '嚴塘經亂書事 一 鄭啓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71a1b07a-9d7b-4836-827b-c8bca9b632fa', '嚴塘經亂書事 二', '嚴塘經亂书事 二', 'cdec67ae-9862-4672-ac34-afbcbdf7b595', '唐', '["梁園皓色月如珪，清景傷時一慘悽。","未見山前歸牧馬，猶聞江上帶征鞞。","鯤爲魚隊潛鱗困，鶴處雞羣病翅低。","正是四郊多壘日，波濤早晚靜鯨鯢。"]', '["梁园皓色月如珪，清景傷时一慘悽。","未见山前归牧马，猶闻江上带征鞞。","鯤爲鱼隊潛鱗困，鹤处雞羣病翅低。","正是四郊多壘日，波濤早晚静鯨鯢。"]', '诗', 'shi', '', NULL, '嚴塘經亂書事 二 鄭啓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89b95f3e-8e85-4fda-adbd-d1117b6965cb', '鄧表山', '鄧表山', 'cdec67ae-9862-4672-ac34-afbcbdf7b595', '唐', '["白日三清此上時，觀開山下彩雲飛。","仙壇丹竈靈猶在，鶴駕清朝去不歸。","晉末幾遷陵谷改，塵中空換子孫非。","松花落盡無消息，半夜疎鐘徹翠微。"]', '["白日三清此上时，观开山下彩云飞。","仙壇丹竈靈猶在，鹤駕清朝去不归。","晉末幾遷陵谷改，塵中空換子孫非。","松花落尽無消息，半夜疎鐘徹翠微。"]', '诗', 'shi', '', NULL, '鄧表山 鄭啓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22894c84-391f-4669-b30f-e217992ae08e', '記知聞近過關試', '記知闻近過关試', 'ba6aeb26-7d45-4884-855a-03671cafeadc', '唐', '["短行軸了付三銓，休把新銜惱必先。","今日便稱前進士，好留春色與明年。"]', '["短行軸了付三銓，休把新銜惱必先。","今日便稱前進士，好留春色與明年。"]', '诗', 'shi', '', NULL, '記知聞近過關試 韓儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a4441fd-6d97-4b68-adc6-44629320aba9', '郊居', '郊居', '13e10ef4-6baa-4696-abb6-da00612a9d91', '唐', '["村前村後樹，寓賞有餘情。","青麥路初斷，紫花田未耕。","雉聲聞不到，山勢望猶橫。","寂寞春風裏，吟酣信馬行。"]', '["村前村後樹，寓賞有餘情。","青麦路初斷，紫花田未耕。","雉声闻不到，山勢望猶橫。","寂寞春风裏，吟酣信马行。"]', '诗', 'shi', '', NULL, '郊居 溫憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae1dfd31-369e-4515-91bd-4d626927e249', '杏花', '杏花', '13e10ef4-6baa-4696-abb6-da00612a9d91', '唐', '["團雪上晴梢，紅明映碧寥。","店香風起夜，村白雨休朝。","靜落猶和蒂，繁開正蔽條。","澹然閑賞久，無以破妖嬈。"]', '["團雪上晴梢，紅明映碧寥。","店香风起夜，村白雨休朝。","静落猶和蒂，繁开正蔽條。","澹然闲賞久，無以破妖嬈。"]', '诗', 'shi', '', NULL, '杏花 溫憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5dd2d18-290a-4d3d-8d07-9f098010265c', '春鳩', '春鳩', '13e10ef4-6baa-4696-abb6-da00612a9d91', '唐', '["村南微雨新，平綠淨無塵。","散睡桑條暖，閑鳴屋脊春。","遠聞和曉夢，相應在諸鄰。","行樂花時節，追飛見亦頻。"]', '["村南微雨新，平綠淨無塵。","散睡桑條暖，闲鳴屋脊春。","远闻和晓梦，相應在諸鄰。","行乐花时節，追飞见亦頻。"]', '诗', 'shi', '', NULL, '春鳩 溫憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0acff8f-d317-481f-9171-0e5af78fb0eb', '題崇[慶]寺壁', '題崇[慶]寺壁', '13e10ef4-6baa-4696-abb6-da00612a9d91', '唐', '["十口溝隍待一身，半年千里絕音塵。","鬢毛如雪心如死，猶作長安下第人。"]', '["十口溝隍待一身，半年千里絕音塵。","鬢毛如雪心如死，猶作长安下第人。"]', '诗', 'shi', '', NULL, '題崇[慶]寺壁 溫憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07fdd1ab-cc77-4f53-9a17-72227553dd4b', '報顏標', '報顏標', 'f710a73d-6e28-443b-b749-41f166f8151f', '唐', '["爲報顏公識我麽，我心唯只與天和。","眼前俗物關情少，醉後青山入意多。","田子莫嫌彈鋏恨，甯生休唱飯牛歌。","聖朝若爲蒼生計，也合公車到薜蘿。"]', '["爲報顏公識我麽，我心唯只與天和。","眼前俗物关情少，醉後青山入意多。","田子莫嫌彈鋏恨，甯生休唱飯牛歌。","聖朝若爲蒼生計，也合公车到薜蘿。"]', '诗', 'shi', '', NULL, '報顏標 姚巖傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bca184d-6c69-4b97-9a35-0f623fd24c7f', '途中除夜', '途中除夜', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["南北浮萍跡，年華又暗催。","殘燈和臘盡，曉角帶春來。","鬢欲漸侵雪，心仍未肯灰。","金門舊知己，誰爲脫塵埃。"]', '["南北浮萍跡，年华又暗催。","殘灯和臘尽，晓角带春来。","鬢欲漸侵雪，心仍未肯灰。","金门旧知己，誰爲脫塵埃。"]', '诗', 'shi', '', NULL, '途中除夜 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d44d502a-a382-4cef-a1e6-f5b33cac5b96', '長門怨', '长门怨', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["天上何勞萬古春，君前誰是百年人。","魂銷尚媿金爐燼，思起猶慚玉輦塵。","煙翠薄情攀不得，星茫浮豔採無因。","可憐明鏡來相向，何似恩光朝夕新。"]', '["天上何勞万古春，君前誰是百年人。","魂銷尚媿金爐燼，思起猶慚玉輦塵。","煙翠薄情攀不得，星茫浮豔採無因。","可怜明镜来相向，何似恩光朝夕新。"]', '诗', 'shi', '', NULL, '長門怨 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2197d236-c16e-4a75-a660-2c7780cb300f', '秋日寄華陽山人', '秋日寄华陽山人', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["雲木送秋何草草，風波凝冷太星星。","銀鞍公子魂俱斷，玉弩將軍涕自零。","茅洞白龍和雨看，荆溪黃鵠帶霜聽。","人間不見清涼事，猶向溪翁乞畫屏。"]', '["云木送秋何草草，风波凝冷太星星。","銀鞍公子魂俱斷，玉弩將軍涕自零。","茅洞白龙和雨看，荆溪黄鵠带霜听。","人间不见清涼事，猶向溪翁乞畫屏。"]', '诗', 'shi', '', NULL, '秋日寄華陽山人 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92c0dd73-f97e-4f43-891e-a967999ad165', '感事', '感事', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["濁河從北下，清洛向東流。","清濁皆如此，何人不白頭。"]', '["濁河從北下，清洛向东流。","清濁皆如此，何人不白头。"]', '诗', 'shi', '', NULL, '感事 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2e5aab3-bbc2-4798-b0ba-b5216b876b8e', '楚思', '楚思', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["疊浪與雲急，翠蘭和意香。","風流化爲雨，日暮下巫陽。"]', '["叠浪與云急，翠蘭和意香。","风流化爲雨，日暮下巫陽。"]', '诗', 'shi', '', NULL, '楚思 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aab241c1-d2c1-4b41-93de-2d0cb836ddca', '雪中', '雪中', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["金閣倚雲開，朱軒犯雪來。","三冬辛苦樣，天意似難栽。"]', '["金閣倚云开，朱軒犯雪来。","三冬辛苦樣，天意似难栽。"]', '诗', 'shi', '', NULL, '雪中 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70fe0f04-4d35-45a7-a073-867a9e9637d0', '道中有感', '道中有感', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["一醉六十日，一裘三十年。","年華經幾日，日日掉征鞭。"]', '["一醉六十日，一裘三十年。","年华經幾日，日日掉征鞭。"]', '诗', 'shi', '', NULL, '道中有感 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14fa23f3-b153-4fe8-a81c-9b2d9c03aed3', '宋汴道中', '宋汴道中', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["平野有千里，居人無一家。","甲兵年正少，日久戍天涯。"]', '["平野有千里，居人無一家。","甲兵年正少，日久戍天涯。"]', '诗', 'shi', '', NULL, '宋汴道中 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87d581ed-c9d5-45ff-952e-7b4caf58467e', '秋思', '秋思', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["天地太蕭索，山川何渺茫。","不堪星斗柄，猶把歲寒量。"]', '["天地太蕭索，山川何渺茫。","不堪星斗柄，猶把歲寒量。"]', '诗', 'shi', '', NULL, '秋思 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('953e28d5-8c81-432f-89df-8d7cc5d8551a', '即事', '即事', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["三年離水石，一旦隱樵漁。","爲問青雲上，何人識卷舒。"]', '["三年離水石，一旦隐樵漁。","爲问青云上，何人識卷舒。"]', '诗', 'shi', '', NULL, '即事 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85db3f0f-f024-4c24-8b23-53933b7ad63c', '漁家', '漁家', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["野水千年在，閑花一夕空。","近來浮世狹，何似釣船中。"]', '["野水千年在，闲花一夕空。","近来浮世狹，何似釣船中。"]', '诗', 'shi', '', NULL, '漁家 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62640e8b-b6ad-4a1d-96b4-2068dbf4d54a', '關中', '关中', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["風雨去愁晚，關河歸思涼。","西遊無紫氣，一夕九回腸。"]', '["风雨去愁晚，关河归思涼。","西游無紫氣，一夕九回腸。"]', '诗', 'shi', '', NULL, '關中 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52b24c41-55a3-48f7-8141-ea4dd4d543fb', '歸思', '归思', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["紫府歸期斷，芳洲別思迢。","黃金作人世，只被歲寒消。"]', '["紫府归期斷，芳洲別思迢。","黄金作人世，只被歲寒消。"]', '诗', 'shi', '', NULL, '歸思 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8a7617b-77d6-464c-a1f4-5f5e54a9871e', '下第出春明門', '下第出春明门', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["曾和秋雨驅愁入，却向春風領恨回。","深謝灞陵隄畔柳，與人頭上拂塵埃。"]', '["曾和秋雨驱愁入，却向春风領恨回。","深謝灞陵隄畔柳，與人头上拂塵埃。"]', '诗', 'shi', '', NULL, '下第出春明門 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddda623c-47eb-48b7-994e-0c41299c9d6c', '華清宮', '华清宮', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["何事金輿不再遊，翠鬟丹臉豈勝愁。","重門深鎖禁鐘後，月滿驪山宮樹秋。"]', '["何事金輿不再游，翠鬟丹臉豈勝愁。","重门深鎖禁鐘後，月满驪山宮樹秋。"]', '诗', 'shi', '', NULL, '華清宮 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dace744-e384-4b9d-872d-74d44b45d591', '秋日北固晚望二首 一', '秋日北固晚望二首 一', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["風含遠思翛翛晚，日照高情的的秋。","何事滿江惆悵水，年年無語向東流。"]', '["风含远思翛翛晚，日照高情的的秋。","何事满江惆悵水，年年無語向东流。"]', '诗', 'shi', '', NULL, '秋日北固晚望二首 一 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c5f16e6-5ea1-4164-9d4b-be4db54852dc', '秋日北固晚望二首 二', '秋日北固晚望二首 二', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["澤國路岐當面苦，江城砧杵入心寒。","不知白髮誰醫得，爲問無情歲月看。"]', '["澤国路岐當面苦，江城砧杵入心寒。","不知白髮誰醫得，爲问無情歲月看。"]', '诗', 'shi', '', NULL, '秋日北固晚望二首 二 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a3ef417-d4a1-4e4b-bfb9-d30f22e6ba18', '送張道士', '送張道士', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["因將歲月離三島，閑貯風煙在一壺。","爲問金烏頭白後，人間流水却回無。"]', '["因將歲月離三島，闲貯风煙在一壺。","爲问金烏头白後，人间流水却回無。"]', '诗', 'shi', '', NULL, '送張道士 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('697b0901-9b9c-4606-8f26-37f55fa4e4c7', '吳門春雨', '吳门春雨', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["吳甸落花春漫漫，吳宮芳樹晚沈沈。","王孫不耐如絲雨，罥斷春風一寸心。"]', '["吳甸落花春漫漫，吳宮芳樹晚沈沈。","王孫不耐如絲雨，罥斷春风一寸心。"]', '诗', 'shi', '', NULL, '吳門春雨 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67493499-0c20-4c09-becd-a0f193ff0955', '旅夕', '旅夕', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["風散古陂驚宿鴈，月臨荒戍起啼鴉。","不堪吟斷無人見，時復寒燈落一花。"]', '["风散古陂驚宿鴈，月臨荒戍起啼鴉。","不堪吟斷無人见，时复寒灯落一花。"]', '诗', 'shi', '', NULL, '旅夕 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a8e0c02-9b0d-40c8-86ff-5e0c2b71e631', '瓜洲夜泊', '瓜洲夜泊', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["偶爲芳草無情客，況是青山有事身。","一夕瓜洲渡頭宿，天風吹盡廣陵塵。"]', '["偶爲芳草無情客，況是青山有事身。","一夕瓜洲渡头宿，天风吹尽廣陵塵。"]', '诗', 'shi', '', NULL, '瓜洲夜泊 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93e0a959-e0f9-4874-9f24-a9c46f03f772', '金陵晚望', '金陵晚望', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["曾伴浮雲歸晚翠，猶陪落日汎秋聲。","世間無限丹青手，一片傷心畫不成。"]', '["曾伴浮云归晚翠，猶陪落日汎秋声。","世间無限丹青手，一片傷心畫不成。"]', '诗', 'shi', '', NULL, '金陵晚望 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f0d97a2-4c4a-42f4-b408-730d2712dceb', '晚思', '晚思', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["虞泉冬恨由來短，楊葉春期分外長。","惆悵浮生不知處，明朝依舊出滄浪。"]', '["虞泉冬恨由来短，楊葉春期分外长。","惆悵浮生不知处，明朝依旧出滄浪。"]', '诗', 'shi', '', NULL, '晚思 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba9a8eff-23ed-4efe-9d76-ba036eae056e', '長信宮二首 一', '长信宮二首 一', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["天上夢魂何杳杳，日宮消息太沈沈。","君恩不似黃金井，一處團圓萬丈深。"]', '["天上梦魂何杳杳，日宮消息太沈沈。","君恩不似黄金井，一处團圓万丈深。"]', '诗', 'shi', '', NULL, '長信宮二首 一 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d19a705e-a164-4299-bbda-3a14be0d0a87', '長信宮二首 二', '长信宮二首 二', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["天上鳳皇休寄夢，人間鸚鵡舊堪悲。","平生心緒無人識，一隻金梭萬丈絲。"]', '["天上鳳皇休寄梦，人间鸚鵡旧堪悲。","平生心緒無人識，一隻金梭万丈絲。"]', '诗', 'shi', '', NULL, '長信宮二首 二 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4769ee06-0656-41e3-a88b-96706762678c', '長安旅懷', '长安旅懷', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["馬嘶九陌年年苦，人語千門日日新。","唯有終南寂無事，寒光不入帝鄉塵。"]', '["马嘶九陌年年苦，人語千门日日新。","唯有終南寂無事，寒光不入帝乡塵。"]', '诗', 'shi', '', NULL, '長安旅懷 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3e41f72-a6b4-43d7-aa75-cc911f6e8469', '春 一', '春 一', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["天柱幾條搘白日，天門幾扇鎖明時。","陽春發處無根蔕，憑仗東風分外吹。"]', '["天柱幾條搘白日，天门幾扇鎖明时。","陽春發处無根蔕，憑仗东风分外吹。"]', '诗', 'shi', '', NULL, '春 一 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb5967b0-b011-4581-86dc-d026c6816d69', '春 二', '春 二', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["明月斷魂清靄靄，平蕪歸思綠迢迢。","人生莫遣頭如雪，縱得春風亦不消。"]', '["明月斷魂清靄靄，平蕪归思綠迢迢。","人生莫遣头如雪，縱得春风亦不消。"]', '诗', 'shi', '', NULL, '春 二 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d97e166e-8466-4858-9338-26368b63bbe4', '秋', '秋', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["陽羨溪聲冷駭人，洞庭山翠晚凝神。","天將金玉爲風露，曾爲高秋幾度貧。"]', '["陽羨溪声冷駭人，洞庭山翠晚凝神。","天將金玉爲风露，曾爲高秋幾度貧。"]', '诗', 'shi', '', NULL, '秋 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b51f54-f8b4-4e39-9a2b-18f04ea8f3a8', '灞陵亭', '灞陵亭', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["一條歸夢朱弦直，一片離心白羽輕。","明日灞陵新霽後，馬頭煙樹綠相迎。"]', '["一條归梦朱弦直，一片離心白羽轻。","明日灞陵新霽後，马头煙樹綠相迎。"]', '诗', 'shi', '', NULL, '灞陵亭 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a047fbbc-1826-4d75-96fa-fa428a7c4c18', '偶作二首 一', '偶作二首 一', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["丁當玉佩三更雨，平帖金閨一覺雲。","明日薄情何處去，風流春水不知君。"]', '["丁當玉佩三更雨，平帖金閨一覺云。","明日薄情何处去，风流春水不知君。"]', '诗', 'shi', '', NULL, '偶作二首 一 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8138abe-d50a-4864-ab27-3f12c79f9233', '偶作二首 二', '偶作二首 二', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["霞衣重疊紅蟬暖，雲髻葱籠紫鳳寒。","天上少年分散後，一條煙水若爲看。"]', '["霞衣重叠紅蟬暖，云髻葱籠紫鳳寒。","天上少年分散後，一條煙水若爲看。"]', '诗', 'shi', '', NULL, '偶作二首 二 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bc457ab-c395-419e-9534-e022a1e5d11d', '永夕', '永夕', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["雲鴻宿處江村冷，獨狖啼時海國陰。","不會殘燈無一事，覺來猶有向隅心。"]', '["云鴻宿处江村冷，独狖啼时海国陰。","不會殘灯無一事，覺来猶有向隅心。"]', '诗', 'shi', '', NULL, '永夕 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f72c929-cccc-4271-b8a7-6ed1cb6d5885', '落花', '落花', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["一葉落時空下淚，三春歸盡復何情。","無人共得東風語，半日尊前計不成。"]', '["一葉落时空下泪，三春归尽复何情。","無人共得东风語，半日尊前計不成。"]', '诗', 'shi', '', NULL, '落花 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('833b593c-1915-4bd9-b42b-d08a75fcbcce', '下第後上永崇高侍郎', '下第後上永崇高侍郎', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["天上碧桃和露種，日邊紅杏倚雲栽。","芙蓉生在秋江上，不向東風怨未開。"]', '["天上碧桃和露種，日邊紅杏倚云栽。","芙蓉生在秋江上，不向东风怨未开。"]', '诗', 'shi', '', NULL, '下第後上永崇高侍郎 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ce1d0ff-7973-4912-99bd-ccdfa23c3c42', '句', '句', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["君恩秋後葉，日日向人疎。"]', '["君恩秋後葉，日日向人疎。"]', '诗', 'shi', '', NULL, '句 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fca65d81-55d7-417a-832c-0a023d3319fa', '城南偶題', '城南偶題', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["誰家朱閣道邊開，竹拂欄干滿壁苔。","野水不知何處去，遊人却是等閑來。","南山氣聳分紅樹，北闕風高隔紫苔。","可惜登臨好光景，五門須聽鼓聲迴。"]', '["誰家朱閣道邊开，竹拂欄干满壁苔。","野水不知何处去，游人却是等闲来。","南山氣聳分紅樹，北闕风高隔紫苔。","可惜登臨好光景，五门須听鼓声迴。"]', '诗', 'shi', '', NULL, '城南偶題 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86442d00-c11b-49c0-bb2d-d944c3b06598', '贈邊將', '贈邊將', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["千千鐵騎擁塵紅，去去平吞萬里空。","宛轉龍蟠金劍雪，連錢豹躩繡旗風。","行收部落歸天闕，旋進封疆入帝聰。","只有河源與遼海，如今全屬指麾中。"]', '["千千鐵騎擁塵紅，去去平吞万里空。","宛轉龙蟠金劍雪，連錢豹躩繡旗风。","行收部落归天闕，旋進封疆入帝聰。","只有河源與遼海，如今全屬指麾中。"]', '诗', 'shi', '', NULL, '贈邊將 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8322f9e9-2b20-46e9-b197-f7abc6b5b2fa', '桃源', '桃源', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["絕壁相欹是洞門，昔人從此入仙源。","數株花下逢珠翠，半曲歌中老子孫。","別後自疑園吏夢，歸來誰信釣翁言。","山前空有無情水，猶遶當時碧樹村。"]', '["絕壁相欹是洞门，昔人從此入仙源。","數株花下逢珠翠，半曲歌中老子孫。","別後自疑园吏梦，归来誰信釣翁言。","山前空有無情水，猶遶當时碧樹村。"]', '诗', 'shi', '', NULL, '桃源 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6ca028f-bedd-4e92-97a2-70dda5d54eb0', '曲江', '曲江', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["日照香塵逐馬蹄，風吹浪濺幾回隄。","無窮羅綺填花徑，大半笙歌占麥畦。","落絮却籠他樹白，嬌鶯更學別禽啼。","秪緣頻燕蓬洲客，引得遊人去似迷。"]', '["日照香塵逐马蹄，风吹浪濺幾回隄。","無窮羅綺填花徑，大半笙歌占麦畦。","落絮却籠他樹白，嬌鶯更学別禽啼。","秪緣頻燕蓬洲客，引得游人去似迷。"]', '诗', 'shi', '', NULL, '曲江 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e611b2b-07c7-44b4-b332-f22b3d289f7b', '送韋岫郎中典泗州', '送韋岫郎中典泗州', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["玉皇恩詔別星班，去壓徐方分野間。","有鳥盡巢垂汴柳，無樓不到隔淮山。","旌旗漸向行時擁，案牘應從到日閑。","想憶朝天獨吟坐，旋飛新作過秦關。"]', '["玉皇恩詔別星班，去壓徐方分野间。","有鸟尽巢垂汴柳，無楼不到隔淮山。","旌旗漸向行时擁，案牘應從到日闲。","想憶朝天独吟坐，旋飞新作過秦关。"]', '诗', 'shi', '', NULL, '送韋岫郎中典泗州 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('099eee4c-c77d-434a-a97a-99bb57d036c0', '贈婺州蘇員外', '贈婺州蘇員外', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["帝念瓊枝欲並芳，星分婺女寄仙郎。","鸞從闕下雖辭侶，鴈到江都却續行。","煙月一時搜古句，山川兩地植甘棠。","即看龍虎西歸去，便佐羲軒活萬方。"]', '["帝念瓊枝欲並芳，星分婺女寄仙郎。","鸾從闕下雖辞侶，鴈到江都却續行。","煙月一时搜古句，山川兩地植甘棠。","即看龙虎西归去，便佐羲軒活万方。"]', '诗', 'shi', '', NULL, '贈婺州蘇員外 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6592c58a-f40b-4728-8f71-fe4e5d6785e5', '寄友人', '寄友人', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["謝家山水屬君家，曾共持鉤擲歲華。","竹裏竹雞眠蘚石，溪頭鸂鶒踏金沙。","登樓夜坐三層月，接果春看五色花。","昨日西風動歸思，滿船涼葉在天涯。"]', '["謝家山水屬君家，曾共持鉤擲歲华。","竹裏竹雞眠蘚石，溪头鸂鶒踏金沙。","登楼夜坐三層月，接果春看五色花。","昨日西风动归思，满船涼葉在天涯。"]', '诗', 'shi', '', NULL, '寄友人 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9810cfa-5187-4892-95c5-58a456f21267', '雨', '雨', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["低着煙花漠漠輕，正堪吟坐掩柴扃。","亂沾細網垂窮巷，斜送陰雲入古廳。","鎖却暮愁終不散，添成春醉轉難醒。","霽來還有風流事，重染南山一遍青。"]', '["低着煙花漠漠轻，正堪吟坐掩柴扃。","亂沾細網垂窮巷，斜送陰云入古廳。","鎖却暮愁終不散，添成春醉轉难醒。","霽来還有风流事，重染南山一遍青。"]', '诗', 'shi', '', NULL, '雨 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('424f3ad5-df99-4932-b024-ad7fee5d1523', '觀錫宴', '观錫宴', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["傾朝朱紫正駢闐，紅杏青莎映廣筵。","不道樓臺無錦繡，只愁塵土撲神仙。","魚銜嫩草浮池面，蝶趂飛花到酒邊。","日暮驊騮相擁去，幾人沉醉失金鞭。"]', '["傾朝朱紫正駢闐，紅杏青莎映廣筵。","不道楼台無錦繡，只愁塵土撲神仙。","鱼銜嫩草浮池面，蝶趂飞花到酒邊。","日暮驊騮相擁去，幾人沉醉失金鞭。"]', '诗', 'shi', '', NULL, '觀錫宴 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc5aaf0c-06cf-4ac2-aeea-717698457384', '城東即事', '城东即事', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["閑尋香陌鳳城東，時暫開襟向遠風。","玉笛一聲芳草外，錦鴛雙起碧流中。","苑邊花竹濃如繡，渭北山川澹似空。","回首漢宮煙靄裏，天河金閣未央宮。"]', '["闲尋香陌鳳城东，时暫开襟向远风。","玉笛一声芳草外，錦鴛雙起碧流中。","苑邊花竹濃如繡，渭北山川澹似空。","回首漢宮煙靄裏，天河金閣未央宮。"]', '诗', 'shi', '', NULL, '城東即事 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a823aa8e-b302-4d26-b4e3-b104c8c28bf3', '夏日湖上即事寄晉陵蕭明府', '夏日湖上即事寄晉陵蕭明府', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["亭午羲和駐火輪，開門嘉樹庇湖濆。","行來賓客奇茶味，睡起兒童帶簟紋。","屋小有時投樹影，舟輕不覺入鷗羣。","陶家豈是無詩酒，公退堪驚日已曛。"]', '["亭午羲和駐火輪，开门嘉樹庇湖濆。","行来賓客奇茶味，睡起兒童带簟紋。","屋小有时投樹影，舟轻不覺入鷗羣。","陶家豈是無诗酒，公退堪驚日已曛。"]', '诗', 'shi', '', NULL, '夏日湖上即事寄晉陵蕭明府 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3ea6907-29ea-4932-a1d4-1c75089bf317', '對月', '对月', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["殘霞卷盡出東溟，萬古難消一片冰。","公子踏開香徑蘚，美人吹滅畫堂燈。","瓊輪正輾丹霄去，銀箭休催皓露凝。","別有洞天三十六，水晶臺殿冷層層。"]', '["殘霞卷尽出东溟，万古难消一片冰。","公子踏开香徑蘚，美人吹滅畫堂灯。","瓊輪正輾丹霄去，銀箭休催皓露凝。","別有洞天三十六，水晶台殿冷層層。"]', '诗', 'shi', '', NULL, '對月 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44214f22-ead3-4208-8c4d-3d748944ef0d', '浙西送杜晦侍御入關', '浙西送杜晦侍御入关', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["紫詔徵賢發帝聰，繡衣行處撲香風。","鶚歸秦樹幽禽散，星出吳天列舍空。","捧日思馳仙掌外，朝宗勢動海門中。","鞭鞘所拂三千里，多少諸侯合避驄。"]', '["紫詔徵賢發帝聰，繡衣行处撲香风。","鶚归秦樹幽禽散，星出吳天列舍空。","捧日思驰仙掌外，朝宗勢动海门中。","鞭鞘所拂三千里，多少諸侯合避驄。"]', '诗', 'shi', '', NULL, '浙西送杜晦侍御入關 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c7741d-8e74-4bd8-a04f-1961b251fa0c', '寄江東道友', '寄江东道友', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["野亭歌罷指西秦，避俗爭名興各新。","碧帶黃麻呈縹緲，短竿長線弄因循。","夜潮分卷三江月，曉騎齊驅九陌塵。","可惜人間好聲勢，片帆羸馬不相親。"]', '["野亭歌罷指西秦，避俗爭名兴各新。","碧带黄麻呈縹緲，短竿长線弄因循。","夜潮分卷三江月，晓騎齊驱九陌塵。","可惜人间好声勢，片帆羸马不相親。"]', '诗', 'shi', '', NULL, '寄江東道友 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcce9bf6-0f7b-4f3b-b3b0-fcbf3ba0764e', '下第有懷', '下第有懷', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["故鄉朝夕有人還，欲作家書下筆難。","滅燭何曾妨夜坐，傾壺不獨爲春寒。","遷來鶯語雖堪聽，落了楊花也怕看。","但使他年遇公道，月輪長在桂珊珊。"]', '["故乡朝夕有人還，欲作家书下笔难。","滅燭何曾妨夜坐，傾壺不独爲春寒。","遷来鶯語雖堪听，落了楊花也怕看。","但使他年遇公道，月輪长在桂珊珊。"]', '诗', 'shi', '', NULL, '下第有懷 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9544c664-85d7-4080-a2b1-c7d7b23aa41c', '春日經湖上友人別業', '春日經湖上友人別業', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["何處狂歌破積愁，攜觴共下木蘭舟。","綠泉濺石銀屏濕，黃鳥逢人玉笛休。","天借煙霞裝島嶼，春鋪錦繡作汀洲。","一年一電逡巡事，不合花前不醉遊。"]', '["何处狂歌破積愁，携觴共下木蘭舟。","綠泉濺石銀屏濕，黄鸟逢人玉笛休。","天借煙霞裝島嶼，春鋪錦繡作汀洲。","一年一電逡巡事，不合花前不醉游。"]', '诗', 'shi', '', NULL, '春日經湖上友人別業 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e13a0bb7-36cb-46e0-b319-527eaabfe3ae', '長安春日', '长安春日', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["春日皇家瑞景遲，東風無力雨微微。","六宮羅綺同時泊，九陌煙花一樣飛。","暖著柳絲金蘂重，冷開山翠雪稜稀。","輸他得路蓬洲客，紅綠山頭爛醉歸。"]', '["春日皇家瑞景遲，东风無力雨微微。","六宮羅綺同时泊，九陌煙花一樣飞。","暖著柳絲金蘂重，冷开山翠雪稜稀。","輸他得路蓬洲客，紅綠山头爛醉归。"]', '诗', 'shi', '', NULL, '長安春日 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61602e97-e557-48c1-a0ae-57c441a00f66', '陪浙西王侍郎夜宴', '陪浙西王侍郎夜宴', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["深鎖雷門宴上才，旋看歌舞旋傳杯。","黃金鸂鶒當筵睡，紅錦薔薇影燭開。","稽嶺好風吹玉佩，鏡湖殘月照樓臺。","小儒末座頻傾耳，祗怕城頭畫角催。"]', '["深鎖雷门宴上才，旋看歌舞旋傳杯。","黄金鸂鶒當筵睡，紅錦薔薇影燭开。","稽嶺好风吹玉佩，镜湖殘月照楼台。","小儒末座頻傾耳，祗怕城头畫角催。"]', '诗', 'shi', '', NULL, '陪浙西王侍郎夜宴 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70e656ff-164d-4453-a10a-17b25418f318', '春別', '春別', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["擲下籬觴指亂山，趨程不待鳳笙殘。","花邊馬嚼金銜去，樓上人垂玉筯看。","柳陌雖然風裊裊，蔥河猶自雪漫漫。","殷勤莫厭貂裘重，恐犯三邊五月寒。"]', '["擲下籬觴指亂山，趨程不待鳳笙殘。","花邊马嚼金銜去，楼上人垂玉筯看。","柳陌雖然风裊裊，蔥河猶自雪漫漫。","殷勤莫厭貂裘重，恐犯三邊五月寒。"]', '诗', 'shi', '', NULL, '春別 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b861df3-63b5-413a-a6f8-f1d3219fb1f4', '送謝進士還閩', '送謝進士還閩', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["百越風煙接巨鼇，還鄉心壯不知勞。","雷霆入地建溪險，星斗逼人梨嶺高。","却擁木綿吟麗句，便攀龍眼醉香醪。","名場聲利喧喧在，莫向林泉改鬢毛。"]', '["百越风煙接巨鼇，還乡心壯不知勞。","雷霆入地建溪險，星斗逼人梨嶺高。","却擁木綿吟丽句，便攀龙眼醉香醪。","名場声利喧喧在，莫向林泉改鬢毛。"]', '诗', 'shi', '', NULL, '送謝進士還閩 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b2f93c6-c644-46c0-b382-55565f0317c3', '焚書坑', '焚书坑', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["竹帛煙消帝業虛，關河空鎖祖龍居。","坑灰未冷山東亂，劉項元來不讀書。"]', '["竹帛煙消帝業虛，关河空鎖祖龙居。","坑灰未冷山东亂，劉項元来不读书。"]', '诗', 'shi', '', NULL, '焚書坑 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f033f158-82a2-418c-b925-51ae54958838', '東都望幸', '东都望幸', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["懶脩珠翠上高臺，眉月連娟恨不開。","縱使東巡也無益，君王自領美人來。"]', '["懶脩珠翠上高台，眉月連娟恨不开。","縱使东巡也無益，君王自領美人来。"]', '诗', 'shi', '', NULL, '東都望幸 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f684fc9-e128-4e17-afb0-3d2ddafcfda3', '旅舍早起', '旅舍早起', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["跡暗心多感，神疲夢不遊。","驚舟同厭夜，獨樹對悲秋。","晚角和人戰，殘星入漢流。","門前早行子，敲鐙唱離憂。"]', '["跡暗心多感，神疲梦不游。","驚舟同厭夜，独樹对悲秋。","晚角和人戰，殘星入漢流。","门前早行子，敲鐙唱離憂。"]', '诗', 'shi', '', NULL, '旅舍早起 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e23781b6-f3a5-49cb-a78a-e1f8db50bf5e', '癸卯歲毘陵登高會中貽同志', '癸卯歲毘陵登高會中貽同志', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["流落常嗟勝會稀，故人相遇菊花時。","鳳笙龍笛數巡酒，紅樹碧山無限詩。","塵土十分歸舉子，乾坤大半屬偷兒。","長楊羽獵須留本，開濟重爲闕下期。"]', '["流落常嗟勝會稀，故人相遇菊花时。","鳳笙龙笛數巡酒，紅樹碧山無限诗。","塵土十分归舉子，乾坤大半屬偷兒。","长楊羽獵須留本，开濟重爲闕下期。"]', '诗', 'shi', '', NULL, '癸卯歲毘陵登高會中貽同志 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d79f8aa0-7d00-41c2-9a0b-237383fda160', '上元夜建元寺觀燈呈智通上人', '上元夜建元寺观灯呈智通上人', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["建元看別上元燈，處處迴廊鬬火層。","珠玉亂拋高殿佛，綺羅深拜遠山僧。","臨風走筆思呈惠，到曉行禪合伴能。","無限喧闐留不得，月華西下露華凝。"]', '["建元看別上元灯，处处迴廊鬬火層。","珠玉亂拋高殿佛，綺羅深拜远山僧。","臨风走笔思呈惠，到晓行禪合伴能。","無限喧闐留不得，月华西下露华凝。"]', '诗', 'shi', '', NULL, '上元夜建元寺觀燈呈智通上人 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e10fe79e-2f8f-457b-801e-8008a6078058', '變體詩', '变體诗', 'afcd951e-874b-4217-82b9-e8ff9eedfe9a', '唐', '["東南路盡吳江畔，正是窮愁暮雨天。","鷗鷺不嫌斜兩岸，波濤欺得逆風船。","偶逢島寺停帆看，深羨漁翁下釣眠。","今古若論英達筭，鴟夷高興固無邊。"]', '["东南路尽吳江畔，正是窮愁暮雨天。","鷗鷺不嫌斜兩岸，波濤欺得逆风船。","偶逢島寺停帆看，深羨漁翁下釣眠。","今古若論英達筭，鴟夷高兴固無邊。"]', '诗', 'shi', '', NULL, '變體詩 章謁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a7e551b-84ff-4d6e-ab91-36756da44fb9', '長安書懷', '长安书懷', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["涼風吹雨滴寒更，鄉思欺人撥不平。","長有歸心懸馬首，可堪無寐枕蛩聲。","嵐收楚岫和空碧，秋染湘江到底清。","早晚身閑著蓑去，橘香深處釣船橫。"]', '["涼风吹雨滴寒更，乡思欺人撥不平。","长有归心懸马首，可堪無寐枕蛩声。","嵐收楚岫和空碧，秋染湘江到底清。","早晚身闲著蓑去，橘香深处釣船橫。"]', '诗', 'shi', '', NULL, '長安書懷 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed3b9f46-1571-47f0-b8aa-20a735fe94ba', '檜樹', '檜樹', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["翠雲交幹瘦輪囷，嘯雨吟風幾百春。","深蓋屈盤青麈尾，老皮張展黑龍鱗。","唯堆寒色資琴興，不放秋聲染俗塵。","歲月如波事如夢，竟留蒼翠待何人。"]', '["翠云交幹瘦輪囷，嘯雨吟风幾百春。","深蓋屈盤青麈尾，老皮張展黑龙鱗。","唯堆寒色資琴兴，不放秋声染俗塵。","歲月如波事如梦，竟留蒼翠待何人。"]', '诗', 'shi', '', NULL, '檜樹 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f463cf98-abc0-491d-aee3-52e745b3e574', '讀五侯傳', '读五侯傳', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["漢亡金鏡道將衰，便有姦臣競佐時。","專國祗誇兄弟貴，舉家誰念子孫危。","後宮得寵人爭附，前殿陳誠帝不疑。","朱紫盈門自稱貴，可嗟區宇盡瘡痍。"]', '["漢亡金镜道將衰，便有姦臣競佐时。","專国祗誇兄弟貴，舉家誰念子孫危。","後宮得寵人爭附，前殿陳誠帝不疑。","朱紫盈门自稱貴，可嗟區宇尽瘡痍。"]', '诗', 'shi', '', NULL, '讀五侯傳 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24d1c6b5-381e-4397-a05f-74d0b837684d', '春雪', '春雪', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["雲重寒空思寂寥，玉塵如糝滿春[朝]。","片纔著地輕輕陷，力不禁風旋旋銷。","惹砌任他香粉妒，縈叢自學小梅嬌。","誰家醉卷珠簾看，弦管堂深暖易調。"]', '["云重寒空思寂寥，玉塵如糝满春[朝]。","片纔著地轻轻陷，力不禁风旋旋銷。","惹砌任他香粉妒，縈叢自学小梅嬌。","誰家醉卷珠簾看，弦管堂深暖易調。"]', '诗', 'shi', '', NULL, '春雪 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16ddf43c-ac3a-47bc-95a5-36a49bceb30b', '貧女', '貧女', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["蓬門未識綺羅香，擬託良媒益自傷。","誰愛風流高格調，共憐時世儉梳妝。","敢將十指誇偏巧，不把雙眉鬬畫長。","苦恨年年壓金線，爲他人作嫁衣裳。"]', '["蓬门未識綺羅香，擬託良媒益自傷。","誰愛风流高格調，共怜时世儉梳妝。","敢將十指誇偏巧，不把雙眉鬬畫长。","苦恨年年壓金線，爲他人作嫁衣裳。"]', '诗', 'shi', '', NULL, '貧女 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33aa941b-d87d-458b-abf4-f4b08dc42353', '題竹', '題竹', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["削玉森森幽思清，院家高興尚分明。","捲簾陰薄漏山色，欹枕韻寒宜雨聲。","斜對酒缸偏覺好，靜籠碁局最多情。","却驚九陌輪蹄外，獨有溪煙數十莖。"]', '["削玉森森幽思清，院家高兴尚分明。","捲簾陰薄漏山色，欹枕韻寒宜雨声。","斜对酒缸偏覺好，静籠碁局最多情。","却驚九陌輪蹄外，独有溪煙數十莖。"]', '诗', 'shi', '', NULL, '題竹 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d585f174-6f74-4fa9-a47a-57298f8bad32', '鸚鵡', '鸚鵡', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["每聞別雁競悲鳴，却歎金籠寄此生。","早是翠襟爭愛惜，可堪丹觜彊分明。","雲漫隴樹魂應斷，歌接秦樓夢不成。","幸自禰衡人未識，賺他作賦被時輕。"]', '["每闻別雁競悲鳴，却歎金籠寄此生。","早是翠襟爭愛惜，可堪丹觜彊分明。","云漫隴樹魂應斷，歌接秦楼梦不成。","幸自禰衡人未識，賺他作賦被时轻。"]', '诗', 'shi', '', NULL, '鸚鵡 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('829f02b4-f589-478d-afbc-540876fe98af', '寄李處士', '寄李处士', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["呂望甘羅道已彰，只憑時數爲門張。","世塗必竟皆應定，人事都來不在忙。","要路強干情本薄，舊山歸去意偏長。","因君指似封侯骨，漸擬回頭別醉鄉。"]', '["呂望甘羅道已彰，只憑时數爲门張。","世塗必竟皆應定，人事都来不在忙。","要路強干情本薄，旧山归去意偏长。","因君指似封侯骨，漸擬回头別醉乡。"]', '诗', 'shi', '', NULL, '寄李處士 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b355f489-5b12-469b-a94a-38f46fa8e776', '對花', '对花', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["長與韶光暗有期，可憐蜂蝶却先知。","誰家促席臨低樹，何處橫釵戴小枝？","麗日多情疑曲照，和風得路合偏吹。","向人雖道渾無語，笑勸王孫到醉時。"]', '["长與韶光暗有期，可怜蜂蝶却先知。","誰家促席臨低樹，何处橫釵戴小枝？","丽日多情疑曲照，和风得路合偏吹。","向人雖道渾無語，笑勸王孫到醉时。"]', '诗', 'shi', '', NULL, '對花 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e6ce13d-0228-4363-b15f-5c0c5ad46e38', '寄懷', '寄懷', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["總藏心劒事儒風，大道如今已渾同。","會致名津搜儁彥，是張愁網絆英雄。","蘇公有國皆懸印，楚將無官可賞功。","若使重生太平日，也應回首哭塗窮。"]', '["總藏心劒事儒风，大道如今已渾同。","會致名津搜儁彥，是張愁網絆英雄。","蘇公有国皆懸印，楚將無官可賞功。","若使重生太平日，也應回首哭塗窮。"]', '诗', 'shi', '', NULL, '寄懷 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deba8a09-39c7-47b3-a718-73007cd0bbe5', '題刑部李郎中山亭', '題刑部李郎中山亭', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["儂家雲水本相知，每到高齋強展眉。","瘦竹嚲煙遮板閣，卷荷擎雨出盆池。","笑吟山色同欹枕，閑背庭陰對覆碁。","不是主人多野興，肯開青眼重漁師。"]', '["儂家云水本相知，每到高斋強展眉。","瘦竹嚲煙遮板閣，卷荷擎雨出盆池。","笑吟山色同欹枕，闲背庭陰对覆碁。","不是主人多野兴，肯开青眼重漁師。"]', '诗', 'shi', '', NULL, '題刑部李郎中山亭 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce3f553c-065f-4e14-bbc8-06cfd789925a', '八月十五日夜同衛諫議看月', '八月十五日夜同衛諫議看月', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["常時月好賴新晴，不似年年此夜生。","初出海濤疑尚濕，漸來雲路覺偏清。","寒光入水蛟龍起，靜色當天鬼魅驚。","豈獨座中堪仰望，孤高應到鳳凰城。"]', '["常时月好賴新晴，不似年年此夜生。","初出海濤疑尚濕，漸来云路覺偏清。","寒光入水蛟龙起，静色當天鬼魅驚。","豈独座中堪仰望，孤高應到鳳凰城。"]', '诗', 'shi', '', NULL, '八月十五日夜同衛諫議看月 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('953ed3f1-b18e-40d2-8da6-747622ba8a5a', '亭臺', '亭台', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["雕楹累棟架崔嵬，院宇生煙次第開。","爲向西窗添月色，豈辭南海取花栽。","意將畫地成幽沼，勢擬驅山近小臺。","清境漸深官轉重，春時長是別人來。"]', '["雕楹累棟架崔嵬，院宇生煙次第开。","爲向西窗添月色，豈辞南海取花栽。","意將畫地成幽沼，勢擬驱山近小台。","清境漸深官轉重，春时长是別人来。"]', '诗', 'shi', '', NULL, '亭臺 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8839b049-2848-4e7f-aeff-d2fb1ec76e5f', '邊將', '邊將', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["劒光如電馬如風，百捷長輕是掌中。","無定河邊蕃將死，受降城外虜塵空。","旗縫雁翅如竿褭，箭撚雕翎逐隼雄。","自指燕山最高石，不知誰爲勒殊功。"]', '["劒光如電马如风，百捷长轻是掌中。","無定河邊蕃將死，受降城外虜塵空。","旗縫雁翅如竿褭，箭撚雕翎逐隼雄。","自指燕山最高石，不知誰爲勒殊功。"]', '诗', 'shi', '', NULL, '邊將 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ca26ad0-3d2a-4657-8f0a-9f89a92b5119', '塞下', '塞下', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["到處人皆著戰袍，麾旗風緊馬蹄勞。","黑山霜重弓添硬，青冢沙平月更高。","大野幾重開雪嶺，長河無限舊雲濤。","[鳳]林關外皆唐土，何日陳兵戍不毛。"]', '["到处人皆著戰袍，麾旗风緊马蹄勞。","黑山霜重弓添硬，青冢沙平月更高。","大野幾重开雪嶺，长河無限旧云濤。","[鳳]林关外皆唐土，何日陳兵戍不毛。"]', '诗', 'shi', '', NULL, '塞下 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1742f423-b288-46e6-a821-4e57c517bb9c', '織錦婦', '织錦婦', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["桃花日日覓新奇，有鏡何曾及畫眉。","祗恐輕梭難作匹，豈辭纖手遍生胝。","合蟬巧間雙盤帶，聯鴈斜銜小折枝。","豪貴大堆酬曲徹，可憐辛苦一絲絲。"]', '["桃花日日覓新奇，有镜何曾及畫眉。","祗恐轻梭难作匹，豈辞纖手遍生胝。","合蟬巧间雙盤带，聯鴈斜銜小折枝。","豪貴大堆酬曲徹，可怜辛苦一絲絲。"]', '诗', 'shi', '', NULL, '織錦婦 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c59290f6-1143-411d-8135-c2a514a92abc', '釣翁', '釣翁', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["一竿青竹老江隈，荷葉衣裳可自裁。","潭定靜懸絲影直，風高斜颭浪紋開。","朝攜輕棹穿雲去，暮背寒塘戴月回。","世上無窮嶮巇事，算應難入釣船來。"]', '["一竿青竹老江隈，荷葉衣裳可自裁。","潭定静懸絲影直，风高斜颭浪紋开。","朝携轻棹穿云去，暮背寒塘戴月回。","世上無窮嶮巇事，算應难入釣船来。"]', '诗', 'shi', '', NULL, '釣翁 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dcfa6d0-8eff-41c1-a67a-798ab32b2673', '曲江', '曲江', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["曲沼深塘躍錦鱗，槐煙徑裏碧波新。","此中境既無佳境，他處春應不是春。","金牓真仙開樂席，銀鞍公子醉花塵。","明年二月重來看，好共東風作主人。"]', '["曲沼深塘躍錦鱗，槐煙徑裏碧波新。","此中境既無佳境，他处春應不是春。","金牓真仙开乐席，銀鞍公子醉花塵。","明年二月重来看，好共东风作主人。"]', '诗', 'shi', '', NULL, '曲江 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a31064e4-4378-4167-b606-ee0c4f7c39e2', '隋隄', '隋隄', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["種柳開河爲勝遊，隄前常使路人愁。","陰埋野色萬條思，翠束寒聲千里秋。","西日至今悲兔苑，東[波]終不反龍舟。","遠山應見繁華事，不語青青對水流。"]', '["種柳开河爲勝游，隄前常使路人愁。","陰埋野色万條思，翠束寒声千里秋。","西日至今悲兔苑，东[波]終不反龙舟。","远山應见繁华事，不語青青对水流。"]', '诗', 'shi', '', NULL, '隋隄 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('114652a6-cfc5-4ecc-a5a6-2365d353d064', '天街', '天街', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["九衢風景盡爭新，獨占天門近紫宸。","寶馬競隨朝暮客，香車爭碾古今塵。","煙光正入南山色，氣勢遙連北闕春。","莫見繁華祗如此，暗中還換往來人。"]', '["九衢风景尽爭新，独占天门近紫宸。","寶马競隨朝暮客，香车爭碾古今塵。","煙光正入南山色，氣勢遙連北闕春。","莫见繁华祗如此，暗中還換往来人。"]', '诗', 'shi', '', NULL, '天街 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18ef97af-6315-4aa9-952d-0354dcaa8158', '紫騮馬', '紫騮马', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["渥洼奇骨本難求，況是豪家重紫騮。","臕大宜懸銀壓胯，力渾欺著玉銜頭。","生獰弄影風隨步，踥蹀衝塵汗滿溝。","若遇丈夫能控馭，任從騎取覓封侯。"]', '["渥洼奇骨本难求，況是豪家重紫騮。","臕大宜懸銀壓胯，力渾欺著玉銜头。","生獰弄影风隨步，踥蹀衝塵汗满溝。","若遇丈夫能控馭，任從騎取覓封侯。"]', '诗', 'shi', '', NULL, '紫騮馬 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76bad1b1-bd27-4aec-9bbf-c5445d71ec9d', '問古', '问古', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["大底榮枯各自行，兼疑陰隲也難明。","無門雪向頭中出，得路雲從脚下生。","深作四溟何浩渺，高爲五嶽太崢嶸。","都來總向人間看，直到皇天可是平。"]', '["大底榮枯各自行，兼疑陰隲也难明。","無门雪向头中出，得路云從脚下生。","深作四溟何浩渺，高爲五嶽太崢嶸。","都来總向人间看，直到皇天可是平。"]', '诗', 'shi', '', NULL, '問古 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3bbf32d-d296-48c8-9812-8821423bae3e', '豪家', '豪家', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["石甃通渠引御波，綠槐陰裏五侯家。","地衣鎮角香獅子，簾額侵鉤繡辟邪。","按徹清歌天未曉，飲回深院漏猶賒。","四鄰池館吞將盡，尚自堆金爲買花。"]', '["石甃通渠引御波，綠槐陰裏五侯家。","地衣鎮角香獅子，簾額侵鉤繡辟邪。","按徹清歌天未晓，饮回深院漏猶賒。","四鄰池館吞將尽，尚自堆金爲買花。"]', '诗', 'shi', '', NULL, '豪家 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07e3a998-af60-482d-b36d-d153e06eedfa', '陳宮', '陳宮', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["臨春高閣擬瀛洲，貪寵張妃作勝遊。","便把江山爲己有，豈知臺榭是身讐。","金城暗逐歌聲碎，鐵甕潛隨舞勢休。","誰識古宮堪恨處，井桐吟雨不勝秋。"]', '["臨春高閣擬瀛洲，貪寵張妃作勝游。","便把江山爲己有，豈知台榭是身讐。","金城暗逐歌声碎，鐵甕潛隨舞勢休。","誰識古宮堪恨处，井桐吟雨不勝秋。"]', '诗', 'shi', '', NULL, '陳宮 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f39da55-a75b-48e5-bd04-47c34075715e', '送友人罷舉授南陵令', '送友人罷舉授南陵令', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["共言愁是酌離杯，況值弦歌枉大才。","獻賦未爲龍化去，除書猶喜鳳銜來。","花明驛路燕脂暖，山入江亭罨畫開。","莫把新詩題別處，謝家臨水有池臺。"]', '["共言愁是酌離杯，況值弦歌枉大才。","獻賦未爲龙化去，除书猶喜鳳銜来。","花明驛路燕脂暖，山入江亭罨畫开。","莫把新诗題別处，謝家臨水有池台。"]', '诗', 'shi', '', NULL, '送友人罷舉授南陵令 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54203781-255b-4e71-9ed9-b512cb4cbcfa', '投知己', '投知己', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["爐中九轉鍊雖成，教主看時亦自驚。","羣嶽竝天先減翠，大江臨海恐無聲。","賦歸已罷吳門釣，身老仍拋楚岸耕。","唯有太平方寸血，今朝盡向隗臺傾。"]', '["爐中九轉鍊雖成，教主看时亦自驚。","羣嶽竝天先減翠，大江臨海恐無声。","賦归已罷吳门釣，身老仍拋楚岸耕。","唯有太平方寸血，今朝尽向隗台傾。"]', '诗', 'shi', '', NULL, '投知己 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1614e75f-db2f-4cba-b942-b3b1f560984f', '牡丹', '牡丹', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["折妖放豔有誰催，疑就仙中旋折來。","圖把一春皆占斷，固留三月始教開。","壓枝金蘂香如撲，逐朵檀心巧勝裁。","好是酒闌絲竹罷，倚風含笑向樓臺。"]', '["折妖放豔有誰催，疑就仙中旋折来。","圖把一春皆占斷，固留三月始教开。","壓枝金蘂香如撲，逐朵檀心巧勝裁。","好是酒闌絲竹罷，倚风含笑向楼台。"]', '诗', 'shi', '', NULL, '牡丹 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e596bac-0a8e-4a7f-a08b-fce9cf8ed051', '春遊', '春游', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["選勝逢君敘解攜，思和芳草遠煙迷。","小梅香裏黃鶯囀，垂柳陰中白馬嘶。","春引美人歌遍熟，風牽公子酒旗低。","早知有此關身事，悔不前年住越溪。"]', '["選勝逢君敘解携，思和芳草远煙迷。","小梅香裏黄鶯囀，垂柳陰中白马嘶。","春引美人歌遍熟，风牽公子酒旗低。","早知有此关身事，悔不前年住越溪。"]', '诗', 'shi', '', NULL, '春遊 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12a04b9e-2795-4392-89a5-c7289e3981ab', '仙掌', '仙掌', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["萬仞連峰積翠新，靈蹤依舊印輪巡。","何如捧日安皇道，莫把回山示世人。","已擘峻流穿太嶽，長扶王氣擁彊秦。","爲余勢負天工背，索取風雲際會身。"]', '["万仞連峰積翠新，靈蹤依旧印輪巡。","何如捧日安皇道，莫把回山示世人。","已擘峻流穿太嶽，长扶王氣擁彊秦。","爲余勢負天工背，索取风云際會身。"]', '诗', 'shi', '', NULL, '仙掌 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1107ce99-1241-4315-a6cc-715bf2a50163', '燕子', '燕子', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["不知大廈許栖無，頻已銜泥到座隅。","曾與佳人竝頭語，幾回拋却繡工夫。"]', '["不知大廈許栖無，頻已銜泥到座隅。","曾與佳人竝头語，幾回拋却繡工夫。"]', '诗', 'shi', '', NULL, '燕子 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4d7ca82-7973-41d7-9ca9-670f6d012a42', '奉和春日玩雪', '奉和春日玩雪', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["北闕同雲掩曉霞，東風春雪滿山家。","瓊章定少千人和，銀樹先開六出花。"]', '["北闕同云掩晓霞，东风春雪满山家。","瓊章定少千人和，銀樹先开六出花。"]', '诗', 'shi', '', NULL, '奉和春日玩雪 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eaf5b15-536b-41f3-9388-a724ebca48a3', '獨坐吟', '独坐吟', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["客愁不盡本如水，草色含情更無已。","又覺春愁似草生，何人種在情田裏。"]', '["客愁不尽本如水，草色含情更無已。","又覺春愁似草生，何人種在情田裏。"]', '诗', 'shi', '', NULL, '獨坐吟 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb275c33-9e5a-4a69-a7f4-b3febd48a211', '採茶歌', '採茶歌', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["天柱香芽露香發，爛研瑟瑟穿荻篾。","太守憐才寄野人，山童碾破團團月。","倚雲便酌泉聲煮，獸炭潛然蚪珠吐。","看著晴天早日明，鼎中颯颯篩風雨。","老翠香塵下纔熟，攪時繞筯天雲綠。","耽書病酒兩多情，坐對閩甌睡先足。","洗我胸中幽思清，鬼神應愁歌欲成。"]', '["天柱香芽露香發，爛研瑟瑟穿荻篾。","太守怜才寄野人，山童碾破團團月。","倚云便酌泉声煮，獸炭潛然蚪珠吐。","看著晴天早日明，鼎中颯颯篩风雨。","老翠香塵下纔熟，攪时繞筯天云綠。","耽书病酒兩多情，坐对閩甌睡先足。","洗我胸中幽思清，鬼神應愁歌欲成。"]', '诗', 'shi', '', NULL, '採茶歌 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bb9ebc2-8a9b-4b51-8f65-61acadf1a755', '貴公子行', '貴公子行', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["堦前莎毬綠不捲，銀龜噴香挽不斷。","亂花織錦柳撚線，妝點池臺畫屏展。","主人公業傳國初，六親聯絡馳朝車。","鬬雞走狗家世事，抱來皆佩黃金魚。","却笑儒生把書卷，學得顏回忍飢面。"]', '["堦前莎毬綠不捲，銀龟噴香挽不斷。","亂花织錦柳撚線，妝点池台畫屏展。","主人公業傳国初，六親聯絡驰朝车。","鬬雞走狗家世事，抱来皆佩黄金鱼。","却笑儒生把书卷，学得顏回忍飢面。"]', '诗', 'shi', '', NULL, '貴公子行 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef387db3-a26a-4cee-ab3d-a0ea909e7ee3', '吹笙歌', '吹笙歌', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["信陵名重憐高才，見我長吹青眼開。","便出燕姬再傾醑，此時花下逢仙侶。","彎彎狂月壓秋波，兩條黃金𨴋黃霧。","逸豔初因醉態見，濃春可是韶光與。","纖纖軟玉捧暖笙，深思香風吹不去。","檀脣呼吸宮商改，怨情漸逐清新舉。","岐山取得嬌鳳雛，管中藏著輕輕語。","好笑襄王大迂闊，曾臥巫雲見神女。","銀鎖金簧不得聽，空勞翠輦衝泥雨。"]', '["信陵名重怜高才，见我长吹青眼开。","便出燕姬再傾醑，此时花下逢仙侶。","彎彎狂月壓秋波，兩條黄金𨴋黄霧。","逸豔初因醉態见，濃春可是韶光與。","纖纖軟玉捧暖笙，深思香风吹不去。","檀脣呼吸宮商改，怨情漸逐清新舉。","岐山取得嬌鳳雛，管中藏著轻轻語。","好笑襄王大迂闊，曾臥巫云见神女。","銀鎖金簧不得听，空勞翠輦衝泥雨。"]', '诗', 'shi', '', NULL, '吹笙歌 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95378a96-d39f-4f94-bbe4-c4eac45e505f', '咏手', '咏手', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["一雙十指玉纖纖，不是風流物不拈。","鸞鏡巧梳勻翠黛，畫樓閑望擘珠簾。","金杯有喜輕輕點，銀鴨無香旋旋添。","因把翦刀嫌道冷，泥人呵了弄人髯。"]', '["一雙十指玉纖纖，不是风流物不拈。","鸾镜巧梳勻翠黛，畫楼闲望擘珠簾。","金杯有喜轻轻点，銀鴨無香旋旋添。","因把翦刀嫌道冷，泥人呵了弄人髯。"]', '诗', 'shi', '', NULL, '咏手 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10596b7b-416e-4bec-8bcf-fc413e424f7e', '句', '句', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["女媧羅裙長百尺，搭在湘江作山色。"]', '["女媧羅裙长百尺，搭在湘江作山色。"]', '诗', 'shi', '', NULL, '句 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64989685-e334-4ab5-80d1-c48e0cdb2523', '逢韓喜', '逢韓喜', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["相逢渾不覺，祗似茂陵貧。","褭褭花驕客，瀟瀟雨淨春。","借書消茗困，索句寫梅真。","此去青雲上，知君有幾人。"]', '["相逢渾不覺，祗似茂陵貧。","褭褭花驕客，瀟瀟雨淨春。","借书消茗困，索句寫梅真。","此去青云上，知君有幾人。"]', '诗', 'shi', '', NULL, '逢韓喜 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cae8789-f6f3-4a4c-a097-ca085f612652', '夜坐示友', '夜坐示友', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["夜久燭花落，淒聲生遠林。","有懷嫌會淺，無事又秋深。","黃葉歸田夢，白頭行路吟。","山中亦可樂，不似此同襟。"]', '["夜久燭花落，淒声生远林。","有懷嫌會淺，無事又秋深。","黄葉归田梦，白头行路吟。","山中亦可乐，不似此同襟。"]', '诗', 'shi', '', NULL, '夜坐示友 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7105e66-cc76-4aea-9dc5-1ae66d084ae0', '梅亭', '梅亭', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["東海窮詩客，西風古驛亭。","髮從殘歲白，山入故鄉青。","世事徒三窟，兒曹且一經。","丁寧速賒酒，煮栗試砂瓶。"]', '["东海窮诗客，西风古驛亭。","髮從殘歲白，山入故乡青。","世事徒三窟，兒曹且一經。","丁寧速賒酒，煮栗試砂瓶。"]', '诗', 'shi', '', NULL, '梅亭 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b5fa24-1a62-4561-b55e-f5fb4bd12cf8', '歲除', '歲除', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["索索風搜客，沈沈雨洗年。","殘林生獵跡，歸鳥避窰煙。","節物杯漿外，溪山鬢影前。","行藏都未定，筆硯或能捐。"]', '["索索风搜客，沈沈雨洗年。","殘林生獵跡，归鸟避窰煙。","節物杯漿外，溪山鬢影前。","行藏都未定，笔硯或能捐。"]', '诗', 'shi', '', NULL, '歲除 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccf966f4-c584-4986-9986-b9a75d4ed807', '詠月', '詠月', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["陰盛此宵中，多爲雨與風。","坐無風雨至，看與雪霜同。","抱濕離遙海，傾寒向遠空。","年年不相值，還似道難通。"]', '["陰盛此宵中，多爲雨與风。","坐無风雨至，看與雪霜同。","抱濕離遙海，傾寒向远空。","年年不相值，還似道难通。"]', '诗', 'shi', '', NULL, '詠月 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0331b114-aae8-4961-954e-94b82c41c46a', '聞應德茂先離棠溪', '闻應德茂先離棠溪', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["落日蘆花雨，行人穀樹村。","青山時問路，紅葉自知門。","苜蓿窮詩味，芭蕉醉墨痕。","端知棄城市，經席許頻溫。"]', '["落日蘆花雨，行人穀樹村。","青山时问路，紅葉自知门。","苜蓿窮诗味，芭蕉醉墨痕。","端知棄城市，經席許頻溫。"]', '诗', 'shi', '', NULL, '聞應德茂先離棠溪 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e39c50ce-b9cf-4303-9171-e06e9b350187', '松', '松', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["託根蟠泰華，倚幹蝕莓苔。","誰云山澤間，而無梁棟材。"]', '["託根蟠泰华，倚幹蝕莓苔。","誰云山澤间，而無梁棟材。"]', '诗', 'shi', '', NULL, '松 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dd04aff-5565-475f-a1db-29542024857c', '梅', '梅', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["玉人下瑤臺，香風動輕素。","畫角弄江城，鳴璫月中墮。"]', '["玉人下瑤台，香风动轻素。","畫角弄江城，鳴璫月中墮。"]', '诗', 'shi', '', NULL, '梅 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06e27167-42e1-4f14-80c4-39ecd14e5e50', '蘭二首 一', '蘭二首 一', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["清風搖翠環，涼露滴蒼玉。","美人胡不紉，幽香藹空谷。"]', '["清风搖翠环，涼露滴蒼玉。","美人胡不紉，幽香藹空谷。"]', '诗', 'shi', '', NULL, '蘭二首 一 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc550f77-d512-4704-8f8a-27c63e8fc6e2', '蘭二首 二', '蘭二首 二', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["謝庭漫芳草，楚畹多綠莎。","于焉忽相見，歲晏將如何。"]', '["謝庭漫芳草，楚畹多綠莎。","于焉忽相见，歲晏將如何。"]', '诗', 'shi', '', NULL, '蘭二首 二 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('081f7f9a-8ad8-44c6-8168-99ce1f59429f', '葡萄', '葡萄', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["金谷風露涼，綠珠醉初醒。","珠帳夜不收，月明墮清影。"]', '["金谷风露涼，綠珠醉初醒。","珠帳夜不收，月明墮清影。"]', '诗', 'shi', '', NULL, '葡萄 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03385f5d-ddf3-4c0b-a458-acac97af8266', '春草', '春草', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["隨夢入池塘，無心在金谷。","春風自年年，吹遍天涯綠。"]', '["隨梦入池塘，無心在金谷。","春风自年年，吹遍天涯綠。"]', '诗', 'shi', '', NULL, '春草 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94e6b597-a9a6-44c6-8969-3b312dc5f96a', '漁', '漁', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["相聚即爲鄰，煙火自成簇。","約伴過前溪，撐破蘼蕪綠。"]', '["相聚即爲鄰，煙火自成簇。","約伴過前溪，撐破蘼蕪綠。"]', '诗', 'shi', '', NULL, '漁 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d5b4d3e-ba31-4d96-8822-39a7bf42a43d', '留別四首 一', '留別四首 一', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["鵬程三萬里，別酒一千鍾。","好景當三月，春光上國濃。"]', '["鵬程三万里，別酒一千鍾。","好景當三月，春光上国濃。"]', '诗', 'shi', '', NULL, '留別四首 一 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6082fff3-b346-4008-a300-e8de923ded57', '留別四首 二', '留別四首 二', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["野花紅滴滴，江燕語喃喃。","鼓吹翻新調，都亭酒正酣。"]', '["野花紅滴滴，江燕語喃喃。","鼓吹翻新調，都亭酒正酣。"]', '诗', 'shi', '', NULL, '留別四首 二 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9cfa0c8-7420-45d9-9e0e-e1eee2f7e59d', '留別四首 三', '留別四首 三', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["登庸趨俊乂，廁用野無遺。","起喜賡歌日，明良際會時。"]', '["登庸趨俊乂，廁用野無遺。","起喜賡歌日，明良際會时。"]', '诗', 'shi', '', NULL, '留別四首 三 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2f17f65-ee52-4be0-9ada-98d1202ee9f3', '留別四首 四', '留別四首 四', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["鹽車淹素志，長坂入青雲。","老驥春風裏，奔騰獨異羣。"]', '["鹽车淹素志，长坂入青云。","老驥春风裏，奔腾独異羣。"]', '诗', 'shi', '', NULL, '留別四首 四 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58c8c04c-422c-45c2-beab-04e0822d6087', '秋葵', '秋葵', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["月瓣團欒翦赭羅，長條排蘂綴鳴珂。","傾陽一點丹心在，承得中天雨露多。"]', '["月瓣團欒翦赭羅，长條排蘂綴鳴珂。","傾陽一点丹心在，承得中天雨露多。"]', '诗', 'shi', '', NULL, '秋葵 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdd71b12-08d6-4008-baee-fe995c85a334', '春草', '春草', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["天北天南遶路邊，托根無處不延綿。","萋萋總是無情物，吹綠東風又一年。"]', '["天北天南遶路邊，托根無处不延綿。","萋萋總是無情物，吹綠东风又一年。"]', '诗', 'shi', '', NULL, '春草 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ec6eead-7c35-431b-9a5e-f3a716462403', '春日偶成', '春日偶成', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["𥱧箏簫管和琵琶，興滿金尊酒量賒。","歌舞留春春似海，美人顏色正如花。"]', '["𥱧箏簫管和琵琶，兴满金尊酒量賒。","歌舞留春春似海，美人顏色正如花。"]', '诗', 'shi', '', NULL, '春日偶成 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('255f05f4-5acf-4e61-af70-70e84435567f', '秋日感懷', '秋日感懷', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["溪上芙蓉映醉顏，悲秋宋玉鬢毛斑。","無情最恨東流水，暗逐芳年去不還。"]', '["溪上芙蓉映醉顏，悲秋宋玉鬢毛斑。","無情最恨东流水，暗逐芳年去不還。"]', '诗', 'shi', '', NULL, '秋日感懷 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb89362f-3e60-4230-a1b9-0a7407359e20', '七夕', '七夕', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["會合無由歎久違，一年一度是緣非。","而予願乞天孫巧，五色紉針補袞衣。"]', '["會合無由歎久違，一年一度是緣非。","而予願乞天孫巧，五色紉針補袞衣。"]', '诗', 'shi', '', NULL, '七夕 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa4ecca-3fd6-409d-a15c-25ba0da853a2', '懷友', '懷友', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["金井涼生梧葉秋，閑看新月上簾鉤。","冰壺總憶人如玉，目斷重雲十二樓。"]', '["金井涼生梧葉秋，闲看新月上簾鉤。","冰壺總憶人如玉，目斷重云十二楼。"]', '诗', 'shi', '', NULL, '懷友 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b51c869d-347b-44c0-95d7-32bdf0a9627b', '翡翠', '翡翠', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["莎草江汀漫晚潮，翠華香撲水光遙。","玉樓春暖笙歌夜，妝點花鈿上舞翹。"]', '["莎草江汀漫晚潮，翠华香撲水光遙。","玉楼春暖笙歌夜，妝点花鈿上舞翹。"]', '诗', 'shi', '', NULL, '翡翠 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2d32099-1937-4a49-b38b-4ec046e582c5', '詠馬二首 一', '詠马二首 一', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["紫雲團影電飛瞳，駿骨龍媒自不同。","騎過玉樓金轡響，一聲嘶斷落花風。"]', '["紫云團影電飞瞳，駿骨龙媒自不同。","騎過玉楼金轡响，一声嘶斷落花风。"]', '诗', 'shi', '', NULL, '詠馬二首 一 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0758d6d7-cc68-496e-be72-6cbb9d38e9e1', '詠馬二首 二', '詠马二首 二', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["崚嶒高聳骨如山，遠放春郊苜蓿間。","百戰沙場汗流血，夢魂猶在玉門關。"]', '["崚嶒高聳骨如山，远放春郊苜蓿间。","百戰沙場汗流血，梦魂猶在玉门关。"]', '诗', 'shi', '', NULL, '詠馬二首 二 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af3b2080-4db2-4b03-9751-2f8abdc7cae0', '留別', '留別', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["丹湖湖上送行舟，白鴈啼殘蘆葉秋。","采石江頭舊時路，題詩還憶水邊樓。"]', '["丹湖湖上送行舟，白鴈啼殘蘆葉秋。","采石江头旧时路，題诗還憶水邊楼。"]', '诗', 'shi', '', NULL, '留別 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80c82b2d-c213-458e-af89-6ca8f199edbb', '詠竹', '詠竹', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["醉臥涼陰沁骨清，石牀冰簟夢難成。","月明午夜生虛籟，悞聽風聲是雨聲。"]', '["醉臥涼陰沁骨清，石牀冰簟梦难成。","月明午夜生虛籟，悞听风声是雨声。"]', '诗', 'shi', '', NULL, '詠竹 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f76f186-826c-4835-afc8-cb9577864a99', '憶孟浩然', '憶孟浩然', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["郊外淩兢西復東，雪晴驢背興無窮。","句搜明月梨花內，趣入春風柳絮中。"]', '["郊外淩兢西复东，雪晴驢背兴無窮。","句搜明月梨花內，趣入春风柳絮中。"]', '诗', 'shi', '', NULL, '憶孟浩然 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e71a16f4-65b3-479d-b5fb-01289680d5a3', '寄友三首 一', '寄友三首 一', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["新酒秦淮縮項鯿，凌霄花下共流連。","別來客邸空翹首，細雨春風憶往年。"]', '["新酒秦淮縮項鯿，凌霄花下共流連。","別来客邸空翹首，細雨春风憶往年。"]', '诗', 'shi', '', NULL, '寄友三首 一 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09ef6214-c590-4634-afee-862ccf68694f', '寄友三首 二', '寄友三首 二', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["寒燈孤對擁青氈，牢落何如似客邊。","却憶花前酣後飲，醉呼明月上遙天。"]', '["寒灯孤对擁青氈，牢落何如似客邊。","却憶花前酣後饮，醉呼明月上遙天。"]', '诗', 'shi', '', NULL, '寄友三首 二 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fb87172-2ffd-49e4-bfe8-a15a09d56fd8', '寄友三首 三', '寄友三首 三', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["客裏逢春一惘然，梅花落盡柳如煙。","無情最恨東來鴈，底事音書不肯傳。"]', '["客裏逢春一惘然，梅花落尽柳如煙。","無情最恨东来鴈，底事音书不肯傳。"]', '诗', 'shi', '', NULL, '寄友三首 三 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b26f3bf0-fdc9-4fc8-b2ac-554f9488943c', '無題十首 一', '無題十首 一', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["細草鋪茵綠滿堤，燕飛晴日正遲遲。","尋芳陌上花如錦，折得東風第一枝。"]', '["細草鋪茵綠满堤，燕飞晴日正遲遲。","尋芳陌上花如錦，折得东风第一枝。"]', '诗', 'shi', '', NULL, '無題十首 一 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d41ca77-a262-4cbf-bf12-aecb342c4620', '無題十首 二', '無題十首 二', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["錦箏銀甲響鵾弦，勾引春聲上綺筵。","醉倚闌干花下月，犀梳斜嚲鬢雲邊。"]', '["錦箏銀甲响鵾弦，勾引春声上綺筵。","醉倚闌干花下月，犀梳斜嚲鬢云邊。"]', '诗', 'shi', '', NULL, '無題十首 二 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b533958-2123-42f8-9e45-468fd58be793', '無題十首 三', '無題十首 三', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["楚雲湘雨會陽臺，錦帳芙蓉向夜開。","吹罷玉簫春似海，一雙綵鳳忽飛來。"]', '["楚云湘雨會陽台，錦帳芙蓉向夜开。","吹罷玉簫春似海，一雙綵鳳忽飞来。"]', '诗', 'shi', '', NULL, '無題十首 三 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbe19bc5-e35a-4153-8b68-662cec25fb52', '無題十首 四', '無題十首 四', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["春江新水促歸航，惜別花前酒漫觴。","倒盡銀瓶渾不醉，却憐和淚入愁腸。"]', '["春江新水促归航，惜別花前酒漫觴。","倒尽銀瓶渾不醉，却怜和泪入愁腸。"]', '诗', 'shi', '', NULL, '無題十首 四 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d12006-4098-4b8c-b4b2-7c2b1e3fa900', '無題十首 五', '無題十首 五', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["誰知別易會應難，目斷青鸞信渺漫。","情似藍橋橋下水，年來流恨幾時乾。"]', '["誰知別易會應难，目斷青鸾信渺漫。","情似藍橋橋下水，年来流恨幾时乾。"]', '诗', 'shi', '', NULL, '無題十首 五 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b1ae6db-d26b-413c-8c6b-12c90aaf36e1', '無題十首 六', '無題十首 六', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["漏滴銅龍夜已深，柳梢斜月弄疎陰。","滿園芳草年年恨，剔盡燈花夜夜心。"]', '["漏滴銅龙夜已深，柳梢斜月弄疎陰。","满园芳草年年恨，剔尽灯花夜夜心。"]', '诗', 'shi', '', NULL, '無題十首 六 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4790f2df-1115-4fd4-ab9a-6c3685c2fd62', '無題十首 七', '無題十首 七', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["夜合庭前花正開，輕羅小扇爲誰裁。","多情驚起雙蝴蝶，飛入巫山夢裏來。"]', '["夜合庭前花正开，轻羅小扇爲誰裁。","多情驚起雙蝴蝶，飞入巫山梦裏来。"]', '诗', 'shi', '', NULL, '無題十首 七 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2a7b41b-5511-42c0-afe5-40e35eee61ef', '無題十首 八', '無題十首 八', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["憶別悠悠歲月長，酒兵無計敵愁腸。","柔絲漫折長亭柳，綰得同心欲寄將。"]', '["憶別悠悠歲月长，酒兵無計敵愁腸。","柔絲漫折长亭柳，綰得同心欲寄將。"]', '诗', 'shi', '', NULL, '無題十首 八 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c3589a0-f4e8-4f0d-b317-a3baa9777b1d', '無題十首 九', '無題十首 九', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["楊柳青青映畫樓，翠眉終日鎖離愁。","杜鵑啼落枝頭月，多爲傷春恨不休。"]', '["楊柳青青映畫楼，翠眉終日鎖離愁。","杜鵑啼落枝头月，多爲傷春恨不休。"]', '诗', 'shi', '', NULL, '無題十首 九 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57a26987-fab4-4906-8cab-a353d6d1d42d', '無題十首 十', '無題十首 十', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["雲色鮫[綃]拭淚顏，一簾春雨杏花寒。","幾時重會鴛鴦侶，月下吹笙和綵鸞。"]', '["云色鮫[綃]拭泪顏，一簾春雨杏花寒。","幾时重會鴛鴦侶，月下吹笙和綵鸾。"]', '诗', 'shi', '', NULL, '無題十首 十 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a6a3775-1061-4ddf-bb4b-32d6c18aa3d7', '寄同上人', '寄同上人', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["高高山頂寺，更有最高人。","定起松鳴屋，吟圓月上身。","雲藏三伏熱，水散百溪津。","曾乞蘭花供，無書又過春。"]', '["高高山頂寺，更有最高人。","定起松鳴屋，吟圓月上身。","云藏三伏熱，水散百溪津。","曾乞蘭花供，無书又過春。"]', '诗', 'shi', '', NULL, '寄同上人 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('528912ae-4ed4-419b-b55d-17e47a939d79', '夜坐', '夜坐', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["愁鬢丁年白，寒燈丙夜青。","不眠驚戍鼓，久客厭郵鈴。","洶洶城噴海，疎疎屋漏星。","十年窮父子，相守慰飄零。"]', '["愁鬢丁年白，寒灯丙夜青。","不眠驚戍鼓，久客厭郵鈴。","洶洶城噴海，疎疎屋漏星。","十年窮父子，相守慰飄零。"]', '诗', 'shi', '', NULL, '夜坐 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a03dd94f-28f4-41d4-81da-82b05679a8d1', '弔方干處士二首 一', '弔方干处士二首 一', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["不謂高名下，終全玉雪身。","交猶及前輩，語不似今人。","別號行鳴鴈，遺編感獲麟。","歛衣應自定，只著古衣巾。"]', '["不謂高名下，終全玉雪身。","交猶及前輩，語不似今人。","別號行鳴鴈，遺編感獲麟。","歛衣應自定，只著古衣巾。"]', '诗', 'shi', '', NULL, '弔方干處士二首 一 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e50c676-a91f-4b8d-b82f-e279e3281297', '弔方干處士二首 二', '弔方干处士二首 二', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["不比他人死，何詩可挽君。","淵明元嬾仕，東野別攻文。","滄海諸公淚，青山處士墳。","相看莫浪哭，私諡有前聞。"]', '["不比他人死，何诗可挽君。","淵明元嬾仕，东野別攻文。","滄海諸公泪，青山处士墳。","相看莫浪哭，私諡有前闻。"]', '诗', 'shi', '', NULL, '弔方干處士二首 二 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6935344b-2703-4a3b-b0a1-30f417a06777', '題證道寺', '題證道寺', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["彎環青徑斜，自是野僧家。","滿澗洗巖液，插天排石牙。","爐寒餘栢子，架靜落藤花。","記得逃兵日，門多貴客車。"]', '["彎环青徑斜，自是野僧家。","满澗洗巖液，插天排石牙。","爐寒餘栢子，架静落藤花。","記得逃兵日，门多貴客车。"]', '诗', 'shi', '', NULL, '題證道寺 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6aa7994-73ee-485b-b541-2ac75212380e', '宿趙𡸯別業', '宿趙𡸯別業', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["溪山兵後縣，風雪旅中人。","迫夜愁嚴鼓，衝寒託軟巾。","摧藏名字在，疏率饌殽真。","今代徐元直，高風自可親。"]', '["溪山兵後縣，风雪旅中人。","迫夜愁嚴鼓，衝寒託軟巾。","摧藏名字在，疏率饌殽真。","今代徐元直，高风自可親。"]', '诗', 'shi', '', NULL, '宿趙𡸯別業 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('603b4e13-9225-4e08-89f0-9a6a954a578c', '原上', '原上', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["危橋橫古渡，村野帶平林。","野騖寒塘靜，山禽曉樹深。","雨微風矗□，雲暗雪侵尋。","安道門前水，清遊豈獨吟。"]', '["危橋橫古渡，村野带平林。","野騖寒塘静，山禽晓樹深。","雨微风矗□，云暗雪侵尋。","安道门前水，清游豈独吟。"]', '诗', 'shi', '', NULL, '原上 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1885721d-a4b7-4483-b02b-64c932d424a2', '寄臺省知己', '寄台省知己', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["久懷聲籍甚，千里致雙魚。","宦路終推轂，親幃且著書。","才名賈太傅，文學馬相如。"]', '["久懷声籍甚，千里致雙鱼。","宦路終推轂，親幃且著书。","才名賈太傅，文学马相如。"]', '诗', 'shi', '', NULL, '寄臺省知己 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67f2e8f5-4248-4eb0-a296-669d885d11c4', '自詠', '自詠', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["白髮三千丈，青春四十年。","兩牙搖欲落，雙膝痺如攣。","強仕非時彥，無聞惜昔賢。","自期終見惡，未忍捨遺編。"]', '["白髮三千丈，青春四十年。","兩牙搖欲落，雙膝痺如攣。","強仕非时彥，無闻惜昔賢。","自期終见惡，未忍捨遺編。"]', '诗', 'shi', '', NULL, '自詠 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31fdc747-b9b7-4355-b12c-541439bf6865', '遊陽明洞呈王理得諸君', '游陽明洞呈王理得諸君', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["禹穴蒼茫不可探，人傳靈笈鎖煙嵐。","初晴鶴點青邊嶂，欲雨龍移黑處潭。","北斗齋壇天寂寂，東風仙洞草毿毿。","堪憐尹叟非關吏，猶向江南逐老聃。"]', '["禹穴蒼茫不可探，人傳靈笈鎖煙嵐。","初晴鹤点青邊嶂，欲雨龙移黑处潭。","北斗斋壇天寂寂，东风仙洞草毿毿。","堪怜尹叟非关吏，猶向江南逐老聃。"]', '诗', 'shi', '', NULL, '遊陽明洞呈王理得諸君 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('577c2dbf-e1a8-4490-9705-6710141ed242', '新豐', '新豐', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["沛中歌舞百餘人，帝業功成里巷新。","半夜素靈先哭楚，一星遺火下燒秦。","貔貅掃盡無三戶，雞犬歸來識四鄰。","惆悵故園前事遠，曉風長路起埃塵。"]', '["沛中歌舞百餘人，帝業功成里巷新。","半夜素靈先哭楚，一星遺火下燒秦。","貔貅掃尽無三戶，雞犬归来識四鄰。","惆悵故园前事远，晓风长路起埃塵。"]', '诗', 'shi', '', NULL, '新豐 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b483d7dd-99c5-4918-8c51-a51e80c2271a', '拜越公墓因遊定水寺有懷源老', '拜越公墓因游定水寺有懷源老', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["越公已作飛仙去，猶得潭潭好墓田。","老樹背風深拓地，野雲依海細分天。","青峰曉接鳴鐘寺，玉井秋澄試茗泉。","我與源公舊相識，遺言瀟灑有人傳。"]', '["越公已作飞仙去，猶得潭潭好墓田。","老樹背风深拓地，野云依海細分天。","青峰晓接鳴鐘寺，玉井秋澄試茗泉。","我與源公旧相識，遺言瀟灑有人傳。"]', '诗', 'shi', '', NULL, '拜越公墓因遊定水寺有懷源老 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34663093-23f6-4458-85f1-db5fbf73a002', '任潛謀隱之作', '任潛謀隐之作', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["江邊秋日逢任子，大理索詩吾欲忘。","爲問山資何次第，祗餘丹訣轉淒涼。","黃金范蠡曾辭祿，白首虞翻未信方。","千古浮雲共歸思，曉風城郭水花香。"]', '["江邊秋日逢任子，大理索诗吾欲忘。","爲问山資何次第，祗餘丹訣轉淒涼。","黄金范蠡曾辞祿，白首虞翻未信方。","千古浮云共归思，晓风城郭水花香。"]', '诗', 'shi', '', NULL, '任潛謀隱之作 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('271fcb79-da38-4412-8ea6-f18ef8bd443d', '晚秋遊中溪', '晚秋游中溪', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["淡竹岡前沙鴈飛，小花尖下柘丸肥。","山雲不卷雨自薄，天氣欲寒人正歸。","招伴祗須新稻酒，臨風猶有舊苔磯。","故人舊業依稀在，怪石老松今是非。"]', '["淡竹岡前沙鴈飞，小花尖下柘丸肥。","山云不卷雨自薄，天氣欲寒人正归。","招伴祗須新稻酒，臨风猶有旧苔磯。","故人旧業依稀在，怪石老松今是非。"]', '诗', 'shi', '', NULL, '晚秋遊中溪 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('338b5d41-fd23-4a41-8fb1-b322407a4085', '寄陳少府兼簡叔高', '寄陳少府兼簡叔高', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["懷人路絕雲歸海，避俗門深草蔽丘。","萬事漸消閑客夢，一年虛白少年頭。","山螿啼緩從除架，淮鴈來多莫上樓。","近日鄰家有新釀，每逢詩伴得淹留。"]', '["懷人路絕云归海，避俗门深草蔽丘。","万事漸消闲客梦，一年虛白少年头。","山螿啼緩從除架，淮鴈来多莫上楼。","近日鄰家有新釀，每逢诗伴得淹留。"]', '诗', 'shi', '', NULL, '寄陳少府兼簡叔高 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc317457-aed4-4b23-aab3-f2f3e4f68403', '過清涼王導墓下', '過清涼王導墓下', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["江左風流廊廟人，荒墳拋與梵宮鄰。","多年羊虎猶眠石，敗壁貂蟬祗貯塵。","萬古雲山同白骨，一庭花木自青春。","永思陵下猶淒切，廢屋寒風吹野薪。"]', '["江左风流廊廟人，荒墳拋與梵宮鄰。","多年羊虎猶眠石，敗壁貂蟬祗貯塵。","万古云山同白骨，一庭花木自青春。","永思陵下猶淒切，廢屋寒风吹野薪。"]', '诗', 'shi', '', NULL, '過清涼王導墓下 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0f8681e-77bd-4d66-a365-885d5ecb72b0', '第三溪', '第三溪', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["日晏霜濃十二月，林疎石瘦第三溪。","雲沙有徑縈寒燒，松屋無人聞晝雞。","幾聚衣冠埋作土，當年歌舞醉如泥。","早知涉世真成夢，不棄山田春雨犁。"]', '["日晏霜濃十二月，林疎石瘦第三溪。","云沙有徑縈寒燒，松屋無人闻晝雞。","幾聚衣冠埋作土，當年歌舞醉如泥。","早知涉世真成梦，不棄山田春雨犁。"]', '诗', 'shi', '', NULL, '第三溪 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a6bbc1a-c70c-4a4e-abac-9cc96c8b50c5', '蒲津河亭', '蒲津河亭', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["宿雨清秋霽景澂，廣亭高樹向晨興。","煙橫博望乘槎水，日上文王避雨陵。","孤棹夷猶期獨往，曲闌愁絕每長憑。","思鄉懷古多傷別，況此哀吟意不勝。"]', '["宿雨清秋霽景澂，廣亭高樹向晨兴。","煙橫博望乘槎水，日上文王避雨陵。","孤棹夷猶期独往，曲闌愁絕每长憑。","思乡懷古多傷別，況此哀吟意不勝。"]', '诗', 'shi', '', NULL, '蒲津河亭 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b317cc3c-a64f-419d-9f29-e321996c400b', '毘陵道中', '毘陵道中', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["百年只有百清明，狼狽今年又避兵。","煙火誰開寒食禁，簪裾那復麗人行。","禾麻地廢生邊氣，草木春寒起戰聲。","渺渺飛鴻天斷處，古來還是闔閭城。"]', '["百年只有百清明，狼狽今年又避兵。","煙火誰开寒食禁，簪裾那复丽人行。","禾麻地廢生邊氣，草木春寒起戰声。","渺渺飞鴻天斷处，古来還是闔閭城。"]', '诗', 'shi', '', NULL, '毘陵道中 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e11dca4-f120-4dae-b101-39fb53524e0b', '越城待旦', '越城待旦', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["策策虛樓竹隔明，悲來展轉向誰傾。","天寒[胡]鴈出萬里，月落越雞啼四更。","爲底朱顏成老色，看人青史上新名。","清溪白石村村有，五尺烏犍託此生。"]', '["策策虛楼竹隔明，悲来展轉向誰傾。","天寒[胡]鴈出万里，月落越雞啼四更。","爲底朱顏成老色，看人青史上新名。","清溪白石村村有，五尺烏犍託此生。"]', '诗', 'shi', '', NULL, '越城待旦 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2c7c0a9-1a38-4066-bec5-63d39e68f59f', '過浩然先生墓', '過浩然先生墓', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["人間萬卷龐眉老，眼見堂堂入草萊。","行客須當下馬過，故交誰復裹雞來。","山花不語如聽講，溪水無情自薦哀。","猶勝黃金買碑碣，百年名字已煙埃。"]', '["人间万卷龐眉老，眼见堂堂入草萊。","行客須當下马過，故交誰复裹雞来。","山花不語如听講，溪水無情自薦哀。","猶勝黄金買碑碣，百年名字已煙埃。"]', '诗', 'shi', '', NULL, '過浩然先生墓 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83f89996-3722-47a9-9612-2a4220e216cf', '贈孟德茂', '贈孟德茂', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["江海悠悠雪欲飛，抱書空出又空歸。","沙頭人滿鷗應笑，船上酒香魚正肥。","塵土竟成誰計是，山林又悔一年非。","平生萬卷應夫子，兩世功名窮布衣。"]', '["江海悠悠雪欲飞，抱书空出又空归。","沙头人满鷗應笑，船上酒香鱼正肥。","塵土竟成誰計是，山林又悔一年非。","平生万卷應夫子，兩世功名窮布衣。"]', '诗', 'shi', '', NULL, '贈孟德茂 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a662fc8d-7925-4c6c-a452-157b7a6c6817', '秋霽豐德寺與玄貞師詠月', '秋霽豐德寺與玄貞師詠月', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["露冷風輕霽魄圓，高樓更在碧山巔。","四溟水合疑無地，八月槎通好上天。","黯黯星辰環紫極，喧喧朝市匝青煙。","夜深獨與巖僧語，羣動消聲舉世眠。"]', '["露冷风轻霽魄圓，高楼更在碧山巔。","四溟水合疑無地，八月槎通好上天。","黯黯星辰环紫極，喧喧朝市匝青煙。","夜深独與巖僧語，羣动消声舉世眠。"]', '诗', 'shi', '', NULL, '秋霽豐德寺與玄貞師詠月 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5495ffe-9dbd-48f1-9ae9-15b1987dd29e', '長陵', '长陵', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["長安高闕此安劉，祔葬纍纍盡列侯。","豐上舊居無故里，沛中原廟對荒丘。","耳聞明主提三尺，眼見愚民盜一[坯]。","千載腐儒騎瘦馬，渭城斜月重回頭。"]', '["长安高闕此安劉，祔葬纍纍尽列侯。","豐上旧居無故里，沛中原廟对荒丘。","耳闻明主提三尺，眼见愚民盜一[坯]。","千載腐儒騎瘦马，渭城斜月重回头。"]', '诗', 'shi', '', NULL, '長陵 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54b97126-de66-4a88-bf04-6947ab1d0273', '留別', '留別', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["西入潼關路，何時更盍簪。","年來人事改，老去鬢毛侵。","花染離筵淚，葵傾報國心。","龍潭千尺水，不似別情深。"]', '["西入潼关路，何时更盍簪。","年来人事改，老去鬢毛侵。","花染離筵泪，葵傾報国心。","龙潭千尺水，不似別情深。"]', '诗', 'shi', '', NULL, '留別 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('881a4c8b-4bb3-4be8-909a-e8760a044840', '宿獨留', '宿独留', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["日晚宿留城，人家半掩門。","羣鴉棲老樹，一犬吠荒村。","爭買魚添價，新篘酒帶渾。","船頭對新月，誰與共清論。"]', '["日晚宿留城，人家半掩门。","羣鴉棲老樹，一犬吠荒村。","爭買鱼添價，新篘酒带渾。","船头对新月，誰與共清論。"]', '诗', 'shi', '', NULL, '宿獨留 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7101a032-e7cb-4efd-b08e-837c64c31da5', '客中感懷', '客中感懷', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["客路三千里，西風兩鬢塵。","貪名笑吳起，說國歎蘇秦。","託興非耽酒，思家豈爲蒪。","可憐今夜月，獨照異鄉人。"]', '["客路三千里，西风兩鬢塵。","貪名笑吳起，说国歎蘇秦。","託兴非耽酒，思家豈爲蒪。","可怜今夜月，独照異乡人。"]', '诗', 'shi', '', NULL, '客中感懷 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('312e4947-9f21-40c6-b08b-c6019318ab5a', '過三山寺', '過三山寺', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["三山江上寺，宮殿望岧嶤。","石徑侵高樹，沙灘半種苗。","一僧歸晚日，羣鷺宿寒潮。","遙聽風鈴語，興亡話六朝。"]', '["三山江上寺，宮殿望岧嶤。","石徑侵高樹，沙灘半種苗。","一僧归晚日，羣鷺宿寒潮。","遙听风鈴語，兴亡話六朝。"]', '诗', 'shi', '', NULL, '過三山寺 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c235dea5-874d-49d9-be13-ca805c3faeba', '望夫石', '望夫石', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["江上見危磯，人形立翠微。","妾來終日望，夫去幾時歸。","明月空懸鏡，蒼苔漫補衣。","可憐雙淚眼，千古斷斜暉。"]', '["江上见危磯，人形立翠微。","妾来終日望，夫去幾时归。","明月空懸镜，蒼苔漫補衣。","可怜雙泪眼，千古斷斜暉。"]', '诗', 'shi', '', NULL, '望夫石 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('911ab65d-b60a-4282-9a0b-8d1b655ff836', '過湖口', '過湖口', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["江湖分兩路，此地是通津。","雲淨山浮翠，風高浪潑銀。","人行俱是客，舟住即爲鄰。","俯仰煙波內，蜉蝣寄此身。"]', '["江湖分兩路，此地是通津。","云淨山浮翠，风高浪潑銀。","人行俱是客，舟住即爲鄰。","俯仰煙波內，蜉蝣寄此身。"]', '诗', 'shi', '', NULL, '過湖口 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ed1b799-3b07-497e-a2cd-532f68a7424f', '夜泊東溪有懷', '夜泊东溪有懷', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["水昏天色晚，崖下泊行舟。","獨客傷歸鴈，孤眠歎野鷗。","溪聲牽別恨，鄉夢惹離愁。","酒醒推篷坐，淒涼望女牛。"]', '["水昏天色晚，崖下泊行舟。","独客傷归鴈，孤眠歎野鷗。","溪声牽別恨，乡梦惹離愁。","酒醒推篷坐，淒涼望女牛。"]', '诗', 'shi', '', NULL, '夜泊東溪有懷 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2e1c1b3-a609-4ce6-a4c3-e7c5a76a5c41', '登廬山', '登廬山', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["五老峰巔望，天涯在目前。","湘潭浮夜雨，巴蜀暝寒煙。","泰華根同峙，嵩衡脈共聯。","憑虛有仙骨，日月看推遷。"]', '["五老峰巔望，天涯在目前。","湘潭浮夜雨，巴蜀暝寒煙。","泰华根同峙，嵩衡脈共聯。","憑虛有仙骨，日月看推遷。"]', '诗', 'shi', '', NULL, '登廬山 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('609e40a8-0cea-4802-aecf-4c938e7f1cf4', '金陵九日', '金陵九日', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["野菊西風滿路香，雨花臺上集壺觴。","九重天近瞻鍾阜，五色雲中望建章。","綠酒莫辭今日醉，黃金難買少年狂。","清歌驚起南飛鴈，散作秋聲送夕陽。"]', '["野菊西风满路香，雨花台上集壺觴。","九重天近瞻鍾阜，五色云中望建章。","綠酒莫辞今日醉，黄金难買少年狂。","清歌驚起南飞鴈，散作秋声送夕陽。"]', '诗', 'shi', '', NULL, '金陵九日 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f329a3a-7ec3-4cb4-be32-69ad781f1e6f', '遊清涼寺', '游清涼寺', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["白雲紅樹路紆縈，古殿長廊次第行。","南望水連桃葉渡，北來山枕石頭城。","一塵不到心源淨，萬有俱空眼界清。","竹院逢僧舊曾識，旋披禪衲爲相迎。"]', '["白云紅樹路紆縈，古殿长廊次第行。","南望水連桃葉渡，北来山枕石头城。","一塵不到心源淨，万有俱空眼界清。","竹院逢僧旧曾識，旋披禪衲爲相迎。"]', '诗', 'shi', '', NULL, '遊清涼寺 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bb43f46-b1c1-4e1b-b3db-ad15aa8d9bab', '高平九日', '高平九日', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["雲淨南山紫翠浮，憑陵絕頂望悠悠。","偶逢佳節牽詩興，漫把芳尊遣客愁。","霜染鴉楓迎日醉，寒衝涇水帶冰流。","烏紗頻岸西風裏，笑插黃花滿鬢秋。"]', '["云淨南山紫翠浮，憑陵絕頂望悠悠。","偶逢佳節牽诗兴，漫把芳尊遣客愁。","霜染鴉楓迎日醉，寒衝涇水带冰流。","烏紗頻岸西风裏，笑插黄花满鬢秋。"]', '诗', 'shi', '', NULL, '高平九日 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37cdfb9c-d9b4-4be0-84e5-12dae67601a0', '金陵懷古', '金陵懷古', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["碧樹涼生宿雨收，荷花荷葉滿汀洲。","登高有酒渾忘醉，慨古無言獨倚樓。","宮殿六朝遺古跡，衣冠千古漫荒丘。","太平時節殊風景，山自青青水自流。"]', '["碧樹涼生宿雨收，荷花荷葉满汀洲。","登高有酒渾忘醉，慨古無言独倚楼。","宮殿六朝遺古跡，衣冠千古漫荒丘。","太平时節殊风景，山自青青水自流。"]', '诗', 'shi', '', NULL, '金陵懷古 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3453f51a-9369-4ee1-b812-d4d092ec1d47', '道中逢故人', '道中逢故人', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["蘭陵市上忽相逢，敘別殷勤興倍濃。","良會若同雞黍約，暫時不放酒杯空。","愁牽白髮三千丈，路入青山幾萬重。","行色一鞭催去馬，畫橋嘶斷落花風。"]', '["蘭陵市上忽相逢，敘別殷勤兴倍濃。","良會若同雞黍約，暫时不放酒杯空。","愁牽白髮三千丈，路入青山幾万重。","行色一鞭催去马，畫橋嘶斷落花风。"]', '诗', 'shi', '', NULL, '道中逢故人 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c289db79-6cac-4efb-a20c-40f202ca6fa4', '早行遇雪', '早行遇雪', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["下馬天未明，風高雪何急。","須臾路欲迷，頃刻山盡白。","雞犬寂無聲，曙光射寒色。","荒村絕煙火，髯凍布袍濕。","王事不可緩，行行動悽惻。"]', '["下马天未明，风高雪何急。","須臾路欲迷，頃刻山尽白。","雞犬寂無声，曙光射寒色。","荒村絕煙火，髯凍布袍濕。","王事不可緩，行行动悽惻。"]', '诗', 'shi', '', NULL, '早行遇雪 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e3ac260-574e-4a0e-963e-060ea85b1f93', '樊登見寄四首 一', '樊登见寄四首 一', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["新辭翦秋水，洗我胸中塵。","無由愜良會，極目空懷人。","醉來拔劍歌，字字皆陽春。"]', '["新辞翦秋水，洗我胸中塵。","無由愜良會，極目空懷人。","醉来拔劍歌，字字皆陽春。"]', '诗', 'shi', '', NULL, '樊登見寄四首 一 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ae15346-d080-411b-ad5a-aea06d3ed27b', '樊登見寄四首 二', '樊登见寄四首 二', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["輕黃著柳條，新春喜更始。","感時重搔首，悵望不能已。","無由託深情，傾瀉芳尊裏。"]', '["轻黄著柳條，新春喜更始。","感时重搔首，悵望不能已。","無由託深情，傾瀉芳尊裏。"]', '诗', 'shi', '', NULL, '樊登見寄四首 二 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b62d7aaa-f661-4f70-b8d3-9040fec21030', '樊登見寄四首 三', '樊登见寄四首 三', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["明月入我室，天風吹我袍。","良夜最岑寂，旅況何蕭條。","馳情望海波，一鶴鳴九臯。"]', '["明月入我室，天风吹我袍。","良夜最岑寂，旅況何蕭條。","驰情望海波，一鹤鳴九臯。"]', '诗', 'shi', '', NULL, '樊登見寄四首 三 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd5fc5b0-1f4a-499b-b917-41ec1ac230f6', '樊登見寄四首 四', '樊登见寄四首 四', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["悠悠括城北，眄眄巖泉西。","宿草暝煙綠，苦竹含雲低。","幽懷不可託，鷓鴣空自啼。"]', '["悠悠括城北，眄眄巖泉西。","宿草暝煙綠，苦竹含云低。","幽懷不可託，鷓鴣空自啼。"]', '诗', 'shi', '', NULL, '樊登見寄四首 四 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2295674c-2940-4293-80b3-ded15d21e0b4', '春風四首 一', '春风四首 一', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["春風吹愁端，散漫不可收。","不如古溪水，祗望鄉江流。"]', '["春风吹愁端，散漫不可收。","不如古溪水，祗望乡江流。"]', '诗', 'shi', '', NULL, '春風四首 一 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e0b2b0f-3655-4942-a07d-9158a9056a48', '春風四首 二', '春风四首 二', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["新花紅爍爍，舊花滿山白。","昔日金張門，狼籍餘廢宅。"]', '["新花紅爍爍，旧花满山白。","昔日金張门，狼籍餘廢宅。"]', '诗', 'shi', '', NULL, '春風四首 二 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0bc16d7-2fa1-4e90-8b9e-cdb7b06ef0a2', '春風四首 三', '春风四首 三', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["回頭語春風，莫向新花叢。","我見朱顏人，多金亦成翁。"]', '["回头語春风，莫向新花叢。","我见朱顏人，多金亦成翁。"]', '诗', 'shi', '', NULL, '春風四首 三 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef9f6434-79a8-41e1-b2e7-6a2b2eb62ba9', '春風四首 四', '春风四首 四', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["多金不足惜，丹砂亦何益。","更種明年花，春風自相識。"]', '["多金不足惜，丹砂亦何益。","更種明年花，春风自相識。"]', '诗', 'shi', '', NULL, '春風四首 四 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc631957-b3c5-4cca-8497-0173c8d58445', '感物二首 一', '感物二首 一', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["騄驥初失羣，亦自矜趫騰。","俛仰歲時久，帖然困蚊蠅。","豪鯨逸其穴，尺水成滄溟。","豈無魚鼈交，望望爲所憎。","物理有翕張，達人同廢興。","幸無怵迫憂，聊復曲吾肱。"]', '["騄驥初失羣，亦自矜趫腾。","俛仰歲时久，帖然困蚊蠅。","豪鯨逸其穴，尺水成滄溟。","豈無鱼鼈交，望望爲所憎。","物理有翕張，達人同廢兴。","幸無怵迫憂，聊复曲吾肱。"]', '诗', 'shi', '', NULL, '感物二首 一 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('890225bb-b8ae-412d-af82-34a5c4e3dad2', '感物二首 二', '感物二首 二', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["魚目出泥沙，空村百金珍。","豫章值擁輳，細細供蒸薪。","論材何必多，適用即能神。","託交何必深，寡求永相親。","鮑叔拙羇魯，張生窮厄陳。","茫然扳援際，豈意出風塵。"]', '["鱼目出泥沙，空村百金珍。","豫章值擁輳，細細供蒸薪。","論材何必多，適用即能神。","託交何必深，寡求永相親。","鲍叔拙羇魯，張生窮厄陳。","茫然扳援際，豈意出风塵。"]', '诗', 'shi', '', NULL, '感物二首 二 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df00165c-5791-49fc-8460-bb85bcdcf2d3', '和陶淵明貧士詩七首 一', '和陶淵明貧士诗七首 一', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["貧賤如故舊，少壯即相依。","中心不敢厭，但覺少光輝。","向來乘時士，亦有能奮飛。","一朝權勢歇，欲退無所歸。","不如行其素，辛苦奈寒飢。","人生繫天運，何用發深悲。"]', '["貧賤如故旧，少壯即相依。","中心不敢厭，但覺少光輝。","向来乘时士，亦有能奮飞。","一朝權勢歇，欲退無所归。","不如行其素，辛苦奈寒飢。","人生繫天運，何用發深悲。"]', '诗', 'shi', '', NULL, '和陶淵明貧士詩七首 一 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0d2914b-1f0b-4c3f-9d2a-6b5e0eff49cb', '和陶淵明貧士詩七首 二', '和陶淵明貧士诗七首 二', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["我居在窮巷，來往無華軒。","辛勤衣食物，出此二畝園。","薤菘鬱朝露，桑柘浮春煙。","以茲亂心曲，智計無他奸。","擇勝不在奢，興至發清言。","相逢樵牧徒，混混誰愚賢。"]', '["我居在窮巷，来往無华軒。","辛勤衣食物，出此二畝园。","薤菘鬱朝露，桑柘浮春煙。","以茲亂心曲，智計無他奸。","擇勝不在奢，兴至發清言。","相逢樵牧徒，混混誰愚賢。"]', '诗', 'shi', '', NULL, '和陶淵明貧士詩七首 二 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59bc723c-5435-452c-b26a-ddac39c11033', '和陶淵明貧士詩七首 三', '和陶淵明貧士诗七首 三', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["松風四山來，清宵響瑤琴。","聽之不能寐，中有怨歎音。","旦起繞其樹，磈砢不計尋。","清陰可敷席，有酒誰與斟。","由來大度士，不受流俗侵。","浩歌相倡答，慰此霜雪心。"]', '["松风四山来，清宵响瑤琴。","听之不能寐，中有怨歎音。","旦起繞其樹，磈砢不計尋。","清陰可敷席，有酒誰與斟。","由来大度士，不受流俗侵。","浩歌相倡答，慰此霜雪心。"]', '诗', 'shi', '', NULL, '和陶淵明貧士詩七首 三 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4a9d808-4aaf-4273-9e81-645b3c8dfbc6', '和陶淵明貧士詩七首 四', '和陶淵明貧士诗七首 四', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["中年涉事熟，欲學唾面婁。","逡巡避少年，赴穢不敢詶。","旁人吁已甚，自喜計慮周。","微勞消厚疚，殘辱勝深憂。","從知爲下安，處上反無儔。","人生各有志，勇懦從所求。"]', '["中年涉事熟，欲学唾面婁。","逡巡避少年，赴穢不敢詶。","旁人吁已甚，自喜計慮周。","微勞消厚疚，殘辱勝深憂。","從知爲下安，处上反無儔。","人生各有志，勇懦從所求。"]', '诗', 'shi', '', NULL, '和陶淵明貧士詩七首 四 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e07ebdc-44cc-49e0-94be-c05ffb83976e', '和陶淵明貧士詩七首 五', '和陶淵明貧士诗七首 五', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["古人重畎畝，有祿不待干。","德成祿自至，釋耒列王官。","不仕亦不貧，本自足饔飱。","後世恥躬耕，號呼脫飢寒。","我生千𥜥後，念此愧在顏。","爲農倘可飽，何用出柴關。"]', '["古人重畎畝，有祿不待干。","德成祿自至，釋耒列王官。","不仕亦不貧，本自足饔飱。","後世恥躬耕，號呼脫飢寒。","我生千𥜥後，念此愧在顏。","爲農倘可飽，何用出柴关。"]', '诗', 'shi', '', NULL, '和陶淵明貧士詩七首 五 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbdc0235-e690-4e41-aff7-b5e96488d6e9', '和陶淵明貧士詩七首 六', '和陶淵明貧士诗七首 六', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["村郊多父老，面垢頭如蓬。","我嘗使之年，言語不待工。","古來名節士，敢望彭城龔。","有叟誚其後，更恨道不通。","鄙哉譊譊者，爲隘不爲通。","低頭拜野老，負米吾願從。"]', '["村郊多父老，面垢头如蓬。","我嘗使之年，言語不待工。","古来名節士，敢望彭城龔。","有叟誚其後，更恨道不通。","鄙哉譊譊者，爲隘不爲通。","低头拜野老，負米吾願從。"]', '诗', 'shi', '', NULL, '和陶淵明貧士詩七首 六 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c2f5d7d-fcff-47a1-aefd-dbaa120f050a', '和陶淵明貧士詩七首 七', '和陶淵明貧士诗七首 七', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["去年秋事荒，販糴仰鄰州。","健者道路間，什百成朋儔。","今年漸向熟，庶幾民不流。","書生自無田，與衆同喜憂。","作詩勞鄰曲，有倡誰與詶。","亦無采詩者，此修何可修。"]', '["去年秋事荒，販糴仰鄰州。","健者道路间，什百成朋儔。","今年漸向熟，庶幾民不流。","书生自無田，與衆同喜憂。","作诗勞鄰曲，有倡誰與詶。","亦無采诗者，此修何可修。"]', '诗', 'shi', '', NULL, '和陶淵明貧士詩七首 七 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de222d04-df95-42a1-9205-1d67d74c72a2', '舟中望紫巖', '舟中望紫巖', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["近山如畫牆，遠山如帚長。","我從雲中來，回頭白茫茫。","惜去乃爾覺，常時自相忘。","相忘豈不佳，遣此懷春傷。","飄灑從何來，衣巾濕微涼。","初疑風雨集，冉冉遊塵黃。","無歸亦自可，信美非吾鄉。","登舟望東雲，猶向帆端翔。"]', '["近山如畫牆，远山如帚长。","我從云中来，回头白茫茫。","惜去乃爾覺，常时自相忘。","相忘豈不佳，遣此懷春傷。","飄灑從何来，衣巾濕微涼。","初疑风雨集，冉冉游塵黄。","無归亦自可，信美非吾乡。","登舟望东云，猶向帆端翔。"]', '诗', 'shi', '', NULL, '舟中望紫巖 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46c76122-f22a-41f6-ac04-c509a7a566c7', '九日遊中溪', '九日游中溪', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["悠悠循澗行，磊磊據石坐。","林垂短長雲，山綴丹碧顆。","蓼花最無數，照水嬌婀娜。","何知是節序，風日自清妥。","羣童競時新，萬果間蔬蓏。","欣然爲之醉，烏帽危不墮。","此日山中懷，孟公不如我。"]', '["悠悠循澗行，磊磊據石坐。","林垂短长云，山綴丹碧顆。","蓼花最無數，照水嬌婀娜。","何知是節序，风日自清妥。","羣童競时新，万果间蔬蓏。","欣然爲之醉，烏帽危不墮。","此日山中懷，孟公不如我。"]', '诗', 'shi', '', NULL, '九日遊中溪 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaf0d290-1442-46ee-aaca-21ecd0f3da3d', '六[月]十三日上陳微博士 一', '六[月]十三日上陳微博士 一', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["驕雲飛散雨，隨風爲有無。","老農終歲心，望施在須臾。","平生官田粟，長此禮義軀。","置之且勿戚，一飽任妻孥。"]', '["驕云飞散雨，隨风爲有無。","老農終歲心，望施在須臾。","平生官田粟，长此禮義軀。","置之且勿戚，一飽任妻孥。"]', '诗', 'shi', '', NULL, '六[月]十三日上陳微博士 一 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d1bfbd3-1f80-4710-ac8c-ef9b682995b8', '六[月]十三日上陳微博士 二', '六[月]十三日上陳微博士 二', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["青青澤中蒲，九夏氣淒寒。","翾翾翠碧羽，照影蒼溪間。","巢由薄天下，俗士榮一官。","小大各有適，自全良獨難。"]', '["青青澤中蒲，九夏氣淒寒。","翾翾翠碧羽，照影蒼溪间。","巢由薄天下，俗士榮一官。","小大各有適，自全良独难。"]', '诗', 'shi', '', NULL, '六[月]十三日上陳微博士 二 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59bcf9aa-9648-402e-9cce-1f148dbaad0e', '六[月]十三日上陳微博士 三', '六[月]十三日上陳微博士 三', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["窮居無公憂，私此長夏日。","蚊蠅如俗子，正爾相妒嫉。","麾驅非吾任，遁避亦無術。","惟當俟其定，靜坐萬慮一。"]', '["窮居無公憂，私此长夏日。","蚊蠅如俗子，正爾相妒嫉。","麾驱非吾任，遁避亦無術。","惟當俟其定，静坐万慮一。"]', '诗', 'shi', '', NULL, '六[月]十三日上陳微博士 三 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36fbd78e-ae9a-4093-9ab4-0d6f7c15dfb7', '宿田家', '宿田家', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["落日下遙峰，荒村倦行履。","停車息茅店，安寢正鼾睡。","忽聞扣門急，云是下鄉隸。","公文捧花柙，鷹隼駕聲勢。","良民懼官府，聽之肝膽碎。","阿母出搪塞，老脚走顛躓。","小心事延欵，□餘糧復匱。","東鄰借種雞，西舍覓芳醑。","再飯不厭飽，一飲直呼醉。","明朝怯見官，苦苦燈前跪。","使我不成眠，爲渠滴清淚。","民膏日已瘠，民力日愈弊。","空懷伊尹心，何補堯舜治。"]', '["落日下遙峰，荒村倦行履。","停车息茅店，安寢正鼾睡。","忽闻扣门急，云是下乡隸。","公文捧花柙，鷹隼駕声勢。","良民懼官府，听之肝膽碎。","阿母出搪塞，老脚走顛躓。","小心事延欵，□餘糧复匱。","东鄰借種雞，西舍覓芳醑。","再飯不厭飽，一饮直呼醉。","明朝怯见官，苦苦灯前跪。","使我不成眠，爲渠滴清泪。","民膏日已瘠，民力日愈弊。","空懷伊尹心，何補堯舜治。"]', '诗', 'shi', '', NULL, '宿田家 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5c84dab-7f07-40b9-9abd-04f7eecacc5c', '夏日訪友', '夏日訪友', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["[堤]樹生晝涼，濃陰撲空翠。","孤舟喚野渡，村疃入幽邃。","高軒俯清流，一犬隔花吠。","童子立門牆，問我向何處？","主人聞故舊，出迎時倒屣。","驚迓敘間闊，屈指越寒暑。","殷勤爲延欵，偶爾得良會。","春盤擘紫蝦，冰鯉斫銀鱠。","荷梗白玉香，荇菜青絲脆。","臘酒擊泥封，羅列總新味。","移席臨湖濱，對此有佳趣。","流連送深杯，賓主共忘醉。","清風岸烏紗，長揖謝君去。","世事如浮雲，東西渺煙水。"]', '["[堤]樹生晝涼，濃陰撲空翠。","孤舟喚野渡，村疃入幽邃。","高軒俯清流，一犬隔花吠。","童子立门牆，问我向何处？","主人闻故旧，出迎时倒屣。","驚迓敘间闊，屈指越寒暑。","殷勤爲延欵，偶爾得良會。","春盤擘紫蝦，冰鯉斫銀鱠。","荷梗白玉香，荇菜青絲脆。","臘酒擊泥封，羅列總新味。","移席臨湖濱，对此有佳趣。","流連送深杯，賓主共忘醉。","清风岸烏紗，长揖謝君去。","世事如浮云，东西渺煙水。"]', '诗', 'shi', '', NULL, '夏日訪友 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82bbc857-aee7-4b5d-a3ea-fd294d6a51a9', '遊南明山', '游南明山', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["久聞南明山，共慕南明寺。","幾度欲登臨，日逐擾人事。","于焉偶閑暇，鳴轡忽相聚。","乘興樂遨遊，聊此托佳趣。","涉水渡溪南，迢遙翠微裏。","石磴千疊斜，峭壁半空起。","白雲鎖峰腰，紅葉暗溪嘴。","長藤絡虛巖，疎花映寒水。","金銀拱梵剎，丹青照廊宇。","石梁臥秋溟，風鈴作簷語。","深洞結苔陰，嵐氣滴晴雨。","羊腸轉咫尺，鳥道轉千里。","屈曲到禪房，上人喜延竚。","香分宿火薰，茶汲清泉煮。","投閑息萬機，三生有宿契。","行廚出盤飧，擔甕倒芳醑。","脫冠挂長松，白石籍憑倚。","宦途勞營營，暫此滌塵慮。","鬮令促傳觴，投壺更聯句。","興來較勝負，醉後忘爾汝。","忽聞吼蒲牢，落日下雲嶼。","長嘯出煙蘿，揚鞭賦歸去。"]', '["久闻南明山，共慕南明寺。","幾度欲登臨，日逐擾人事。","于焉偶闲暇，鳴轡忽相聚。","乘兴乐遨游，聊此托佳趣。","涉水渡溪南，迢遙翠微裏。","石磴千叠斜，峭壁半空起。","白云鎖峰腰，紅葉暗溪嘴。","长藤絡虛巖，疎花映寒水。","金銀拱梵剎，丹青照廊宇。","石梁臥秋溟，风鈴作簷語。","深洞結苔陰，嵐氣滴晴雨。","羊腸轉咫尺，鸟道轉千里。","屈曲到禪房，上人喜延竚。","香分宿火薰，茶汲清泉煮。","投闲息万機，三生有宿契。","行廚出盤飧，擔甕倒芳醑。","脫冠挂长松，白石籍憑倚。","宦途勞營營，暫此滌塵慮。","鬮令促傳觴，投壺更聯句。","兴来較勝負，醉後忘爾汝。","忽闻吼蒲牢，落日下云嶼。","长嘯出煙蘿，揚鞭賦归去。"]', '诗', 'shi', '', NULL, '遊南明山 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3998ea07-b8ae-4c99-bafe-56f050ab6fc2', '索蝦', '索蝦', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["姑孰多紫蝦，獨有湖陽優。","出產在四時，極美宜於秋。","雙箝鼓繁鬚，當頂抽長矛。","鞠躬見湯王，封作朱衣侯。","所以供盤餐，羅列同珍羞。","蒜友日相親，瓜朋時與儔。","既名釣詩釣，又作鉤詩鉤。","于時同相訪，數日承欵留。","厭飲多美味，獨此心相投。","別來歲云久，馳想空悠悠。","銜杯動遐思，{拶扌=口}口涎空流。","封緘託雙鯉，于焉來遠求。","慷慨胡隱君，果肯分惠否。"]', '["姑孰多紫蝦，独有湖陽優。","出產在四时，極美宜於秋。","雙箝鼓繁鬚，當頂抽长矛。","鞠躬见湯王，封作朱衣侯。","所以供盤餐，羅列同珍羞。","蒜友日相親，瓜朋时與儔。","既名釣诗釣，又作鉤诗鉤。","于时同相訪，數日承欵留。","厭饮多美味，独此心相投。","別来歲云久，驰想空悠悠。","銜杯动遐思，{拶扌=口}口涎空流。","封緘託雙鯉，于焉来远求。","慷慨胡隐君，果肯分惠否。"]', '诗', 'shi', '', NULL, '索蝦 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d29ab50-078c-4fa8-bb57-d106e5768cf1', '採桑女', '採桑女', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["春風吹蠶細如蟻，桑芽纔努青鴉嘴。","侵晨探采誰家女，手挽長條淚如雨。","去歲初眠當此時，今歲春寒葉放遲。","愁聽門外催里胥，官家二月收新絲。"]', '["春风吹蠶細如蟻，桑芽纔努青鴉嘴。","侵晨探采誰家女，手挽长條泪如雨。","去歲初眠當此时，今歲春寒葉放遲。","愁听门外催里胥，官家二月收新絲。"]', '诗', 'shi', '', NULL, '採桑女 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0808478b-7cea-4153-a2e6-a55df5fc0f7f', '送許戶曹', '送許戶曹', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["沙頭小燕鳴春和，楊柳垂絲煙倒拖。","將軍樓船發浩歌，雲檣高插天嵯峨。","白虹走香傾翠壺，勸飲花前金叵羅。","神鰲駕粟升天河，新承雨澤浮恩波。"]', '["沙头小燕鳴春和，楊柳垂絲煙倒拖。","將軍楼船發浩歌，云檣高插天嵯峨。","白虹走香傾翠壺，勸饮花前金叵羅。","神鰲駕粟升天河，新承雨澤浮恩波。"]', '诗', 'shi', '', NULL, '送許戶曹 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19510682-4733-4378-951b-9c41ca81b25d', '詠葡萄', '詠葡萄', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["西園晚霽浮嫩涼，開尊漫摘葡萄嘗。","滿架高撐紫絡索，一枝斜嚲金琅璫。","天風颼颼葉栩栩，蝴蝶聲乾作晴雨。","神蛟清夜蟄寒潭，萬片濕雲飛不起。","石家美人金谷遊，羅幃翠幕珊瑚鉤。","玉盤新薦入華屋，珠帳高懸夜不收。","勝遊記得當年景，清氣逼人毛骨冷。","笑呼明鏡上遙天，醉倚銀牀弄秋影。"]', '["西园晚霽浮嫩涼，开尊漫摘葡萄嘗。","满架高撐紫絡索，一枝斜嚲金琅璫。","天风颼颼葉栩栩，蝴蝶声乾作晴雨。","神蛟清夜蟄寒潭，万片濕云飞不起。","石家美人金谷游，羅幃翠幕珊瑚鉤。","玉盤新薦入华屋，珠帳高懸夜不收。","勝游記得當年景，清氣逼人毛骨冷。","笑呼明镜上遙天，醉倚銀牀弄秋影。"]', '诗', 'shi', '', NULL, '詠葡萄 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f93f70e-dfd1-4e3c-94d0-e9b9dbd3b047', '蟹', '蟹', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["湖田十月清霜墮，晚稻初香蟹如虎。","扳罾拖網取賽多，篾簍挑將水邊貨。","縱橫連爪一尺長，秀凝鐵色含湖光。","蟛蜞石蟹已曾食，使我一見驚非常。","買之最厭黃髯老，償價十錢尚嫌少。","漫誇丰味過蝤蛑，尖臍猶勝團臍好。","充盤煮熟堆琳琅，橙膏醬渫調堪嚐。","一斗擘開紅玉滿，雙螯{拶扌=口}出瓊酥香。","岸頭沽得泥封酒，細嚼頻斟弗停手。","西風張翰苦思鱸，如斯丰味能知否。","物之可愛尤可憎，嘗聞取刺於青蠅。","無腸公子固稱美，弗使當道禁橫行。"]', '["湖田十月清霜墮，晚稻初香蟹如虎。","扳罾拖網取賽多，篾簍挑將水邊貨。","縱橫連爪一尺长，秀凝鐵色含湖光。","蟛蜞石蟹已曾食，使我一见驚非常。","買之最厭黄髯老，償價十錢尚嫌少。","漫誇丰味過蝤蛑，尖臍猶勝團臍好。","充盤煮熟堆琳琅，橙膏醬渫調堪嚐。","一斗擘开紅玉满，雙螯{拶扌=口}出瓊酥香。","岸头沽得泥封酒，細嚼頻斟弗停手。","西风張翰苦思鱸，如斯丰味能知否。","物之可愛尤可憎，嘗闻取刺於青蠅。","無腸公子固稱美，弗使當道禁橫行。"]', '诗', 'shi', '', NULL, '蟹 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64662db3-c24b-4f67-aa1c-178bc6099bc7', '敘別', '敘別', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["譙樓夜促蓮花漏，樹陰搖月蛟螭走。","蟠拏對月吸深杯，月府清虛玉兔吼。","翠盤擘脯臙脂香，碧碗敲冰分蔗漿。","十載番思舊時事，好懷不似當年狂。","夜合花香開小院，坐愛涼風吹醉面。","酒中彈劍發清歌，白髮年來爲愁變。"]', '["譙楼夜促蓮花漏，樹陰搖月蛟螭走。","蟠拏对月吸深杯，月府清虛玉兔吼。","翠盤擘脯臙脂香，碧碗敲冰分蔗漿。","十載番思旧时事，好懷不似當年狂。","夜合花香开小院，坐愛涼风吹醉面。","酒中彈劍發清歌，白髮年来爲愁变。"]', '诗', 'shi', '', NULL, '敘別 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7f4c840-02b2-48c5-8a14-db3f5597fa9d', '緋桃', '緋桃', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["短牆荒圃四無鄰，烈火緋桃照地春。","坐久好風休掩袂，夜來微雨已霑巾。","敢同俗態期青眼，似有微詞動絳脣。","盡日更無鄉井念，此時何必見秦人。"]', '["短牆荒圃四無鄰，烈火緋桃照地春。","坐久好风休掩袂，夜来微雨已霑巾。","敢同俗態期青眼，似有微词动絳脣。","尽日更無乡井念，此时何必见秦人。"]', '诗', 'shi', '', NULL, '緋桃 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144d0d58-a575-4e99-9050-53b71f64cd16', '小院', '小院', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["小院無人夜，煙斜月轉明。","清宵易惆悵，不必有離情。"]', '["小院無人夜，煙斜月轉明。","清宵易惆悵，不必有離情。"]', '诗', 'shi', '', NULL, '小院 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff465038-6de0-465a-8d6e-7f42128e9632', '春雪初霽杏花正芳月上夜吟', '春雪初霽杏花正芳月上夜吟', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["霽景明如練，繁英杏正芳。","姮娥應有語，悔共雪爭光。"]', '["霽景明如練，繁英杏正芳。","姮娥應有語，悔共雪爭光。"]', '诗', 'shi', '', NULL, '春雪初霽杏花正芳月上夜吟 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd3e86b9-9bd2-40c4-9222-54e281c5d5e9', '文惠宮人', '文惠宮人', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["認得前家令，宮人淚滿裾。","不知梁佐命，全是沈尚書。"]', '["認得前家令，宮人泪满裾。","不知梁佐命，全是沈尚书。"]', '诗', 'shi', '', NULL, '文惠宮人 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5ec7fdd-25ff-4a63-888c-ec8d895a6d23', '贈竇尊師', '贈竇尊師', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["我愛竇高士，棄官仍在家。","爲嫌句漏令，兼不要丹砂。"]', '["我愛竇高士，棄官仍在家。","爲嫌句漏令，兼不要丹砂。"]', '诗', 'shi', '', NULL, '贈竇尊師 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('431db2b4-b9e2-4065-b63d-82e770dfe395', '穆天子傳', '穆天子傳', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["王母清歌玉琯悲，瑤臺應有再來期。","穆王不得重相見，恐爲無端哭盛姬。"]', '["王母清歌玉琯悲，瑤台應有再来期。","穆王不得重相见，恐爲無端哭盛姬。"]', '诗', 'shi', '', NULL, '穆天子傳 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('030e6ebf-6656-41fa-a9a4-ddb40c13cd9b', '楚天', '楚天', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["楚天遙望每長嚬，宋玉襄王盡作塵。","不會瑤姬朝與暮，更爲雲雨待何人。"]', '["楚天遙望每长嚬，宋玉襄王尽作塵。","不會瑤姬朝與暮，更爲云雨待何人。"]', '诗', 'shi', '', NULL, '楚天 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cd58725-7972-4c0a-82c1-1208d7179e39', '寄徐山人', '寄徐山人', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["一室清羸鶴體孤，氣和神瑩爽冰壺。","吳中高士雖求死，不那稽山有謝敷。"]', '["一室清羸鹤體孤，氣和神瑩爽冰壺。","吳中高士雖求死，不那稽山有謝敷。"]', '诗', 'shi', '', NULL, '寄徐山人 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f60e740d-c075-46d3-b516-1c57e4fc73db', '題宗人故帖', '題宗人故帖', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["所忠無處訪相如，風笈塵編跡尚餘。","惟有孝標情最厚，一編遺在茂陵書。"]', '["所忠無处訪相如，风笈塵編跡尚餘。","惟有孝標情最厚，一編遺在茂陵书。"]', '诗', 'shi', '', NULL, '題宗人故帖 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b28945d-b672-4430-8e55-3116136a9daf', '垂柳', '垂柳', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["絆惹春風別有情，世間誰敢鬬輕盈。","楚王江畔無端種，餓損纖腰學不成。"]', '["絆惹春风別有情，世间誰敢鬬轻盈。","楚王江畔無端種，餓損纖腰学不成。"]', '诗', 'shi', '', NULL, '垂柳 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f644689b-48e5-4b7f-ab7a-40c60db072c6', '登興元城觀烽火', '登兴元城观烽火', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["漢川城上角三呼，扈蹕防邊列萬夫。","[褒]姒冢前烽火起，不知泉下破顏無。"]', '["漢川城上角三呼，扈蹕防邊列万夫。","[褒]姒冢前烽火起，不知泉下破顏無。"]', '诗', 'shi', '', NULL, '登興元城觀烽火 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('855bb890-046d-4422-bc25-93866f17a472', '鄧艾廟', '鄧艾廟', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["昭烈遺黎死尚羞，揮刀斫石恨譙周。","如何千載留遺廟，血食巴山伴武侯。"]', '["昭烈遺黎死尚羞，揮刀斫石恨譙周。","如何千載留遺廟，血食巴山伴武侯。"]', '诗', 'shi', '', NULL, '鄧艾廟 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfe27dcc-74c9-41b5-9978-048df211d2ec', '曲江春望', '曲江春望', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["杏豔桃光奪晚霞，樂遊無廟有年華。","漢朝冠蓋皆陵墓，十里宜春漢苑花。"]', '["杏豔桃光奪晚霞，乐游無廟有年华。","漢朝冠蓋皆陵墓，十里宜春漢苑花。"]', '诗', 'shi', '', NULL, '曲江春望 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bb1e5d6-490e-460e-b20c-f8af71e35740', '漢殿', '漢殿', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["鳥去雲飛意不通，夜壇斜月轉松風。","君主寂慮無消息，却就閑人覓巨公。"]', '["鸟去云飞意不通，夜壇斜月轉松风。","君主寂慮無消息，却就闲人覓巨公。"]', '诗', 'shi', '', NULL, '漢殿 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98c60d7c-086d-4754-9dd9-16523bd6233d', '賀李昌時禁苑新命', '賀李昌时禁苑新命', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["振鷺翔鸞集禁闈，玉堂珠樹瑩風儀。","不知新到靈和殿，張緒何如柳一枝。"]', '["振鷺翔鸾集禁闈，玉堂珠樹瑩风儀。","不知新到靈和殿，張緒何如柳一枝。"]', '诗', 'shi', '', NULL, '賀李昌時禁苑新命 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30fcb6f0-962f-4d35-a0ea-076c1db5229f', '牡丹', '牡丹', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["顏色無因饒錦繡，馨香惟解掩蘭蓀。","那堪更被煙蒙蔽，南國西施泣斷魂。"]', '["顏色無因饒錦繡，馨香惟解掩蘭蓀。","那堪更被煙蒙蔽，南国西施泣斷魂。"]', '诗', 'shi', '', NULL, '牡丹 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91a574b5-9b5f-450e-b950-7d8cfb9d99e1', '羅江驛', '羅江驛', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["數枝高柳帶鳴鴉，一樹山榴自落花。","已是向來多淚眼，短亭回首在天涯。"]', '["數枝高柳带鳴鴉，一樹山榴自落花。","已是向来多泪眼，短亭回首在天涯。"]', '诗', 'shi', '', NULL, '羅江驛 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('602256c1-8faf-43e2-88a2-46f771e67390', '奏捷西蜀題沲江驛', '奏捷西蜀題沲江驛', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["野客乘軺非所宜，況將儒懦報戎機。","錦江不識臨邛酒，且免相如渴病歸。"]', '["野客乘軺非所宜，況將儒懦報戎機。","錦江不識臨邛酒，且免相如渴病归。"]', '诗', 'shi', '', NULL, '奏捷西蜀題沲江驛 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('455d3be6-fabb-42de-a545-f9d5913d8552', '春早落英', '春早落英', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["紛紛從此見花殘，轉覺長繩繫日難。","樓上有愁春不淺，小桃風雪凭闌干。"]', '["紛紛從此见花殘，轉覺长繩繫日难。","楼上有愁春不淺，小桃风雪凭闌干。"]', '诗', 'shi', '', NULL, '春早落英 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58694f54-5ba7-4322-96e6-cacb0f90ee9d', '仲山', '仲山', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["千載遺蹤寄薜蘿，沛中鄉里舊山河。","長陵亦是閑丘隴，異日誰知與仲多。"]', '["千載遺蹤寄薜蘿，沛中乡里旧山河。","长陵亦是闲丘隴，異日誰知與仲多。"]', '诗', 'shi', '', NULL, '仲山 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d75e25c2-9637-4ef5-9a8a-1fc725ec5073', '漢嗣', '漢嗣', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["漢嗣安危繫數君，高皇決意勢難分。","張良口辨周昌吃，同建儲宮第一勛。"]', '["漢嗣安危繫數君，高皇決意勢难分。","張良口辨周昌吃，同建儲宮第一勛。"]', '诗', 'shi', '', NULL, '漢嗣 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac29d66c-fdca-421f-bd78-3b4a3c5bc288', '四老廟', '四老廟', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["四漢儲宮定不傾，可能園綺勝良平。","舉朝公將無全策，借請閑人羽翼成。"]', '["四漢儲宮定不傾，可能园綺勝良平。","舉朝公將無全策，借請闲人羽翼成。"]', '诗', 'shi', '', NULL, '四老廟 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b5d3234-12a2-44fa-b041-2d4d14bf2e37', '南梁戲題漢高廟', '南梁戲題漢高廟', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["數載從軍似武夫，今隨戎捷氣偏粗。","漢皇若問何爲者，免道高陽舊酒徒。"]', '["數載從軍似武夫，今隨戎捷氣偏粗。","漢皇若问何爲者，免道高陽旧酒徒。"]', '诗', 'shi', '', NULL, '南梁戲題漢高廟 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ada1932-6bb4-4afd-bfc3-d725de468653', '洛神', '洛神', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["人世仙家本自殊，何須相見向中途。","驚鴻瞥過遊龍去，漫惱陳王一事無。"]', '["人世仙家本自殊，何須相见向中途。","驚鴻瞥過游龙去，漫惱陳王一事無。"]', '诗', 'shi', '', NULL, '洛神 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('232c82ad-4d7d-493f-9c7b-e831efd12de6', '初秋到慈州冬首換絳牧', '初秋到慈州冬首換絳牧', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["秋杪方攀玉樹枝，隔年無計待春暉。","自嫌暫作仙城守，不逐鶯來共燕飛。"]', '["秋杪方攀玉樹枝，隔年無計待春暉。","自嫌暫作仙城守，不逐鶯来共燕飞。"]', '诗', 'shi', '', NULL, '初秋到慈州冬首換絳牧 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9067b4b-545b-4ba0-bcf7-7610f045b151', '重經馮家舊里', '重經馮家旧里', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["馮家舊宅閉柴關，修竹猶存潏水灣。","應繫星辰天上去，不留英骨葬人間。"]', '["馮家旧宅閉柴关，修竹猶存潏水灣。","應繫星辰天上去，不留英骨葬人间。"]', '诗', 'shi', '', NULL, '重經馮家舊里 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efd3d75e-47af-415c-ac44-58496b3d6c0c', '克復後登安國寺閣', '克复後登安国寺閣', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["千門萬戶鞠蒿藜，斷燼遺垣一望迷。","惆悵建章鴛瓦盡，夜來空見玉繩低。"]', '["千门万戶鞠蒿藜，斷燼遺垣一望迷。","惆悵建章鴛瓦尽，夜来空见玉繩低。"]', '诗', 'shi', '', NULL, '克復後登安國寺閣 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ea2a84e-056d-4f2e-aa5b-8daeb551ed16', '題虔僧室', '題虔僧室', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["何緣春恨貯離憂，欲入空門萬事休。","水月定中何所謂，也嚬眉黛托腮愁。"]', '["何緣春恨貯離憂，欲入空门万事休。","水月定中何所謂，也嚬眉黛托腮愁。"]', '诗', 'shi', '', NULL, '題虔僧室 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06092d41-d9be-42ce-9cfb-4ecf721f1571', '見煬帝寶帳', '见煬帝寶帳', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["漢文窮相作前王，慳惜明珠不斗量。","翡翠鮫鮹何所直，千裨萬接上書囊。"]', '["漢文窮相作前王，慳惜明珠不斗量。","翡翠鮫鮹何所直，千裨万接上书囊。"]', '诗', 'shi', '', NULL, '見煬帝寶帳 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cccf5c24-df42-4ff0-a375-03ea498a9c6b', '樓上偶題', '楼上偶題', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["塵土無因狎隱淪，青山一望每傷神。","可能前嶺空喬木，應有懷才抱器人。"]', '["塵土無因狎隐淪，青山一望每傷神。","可能前嶺空喬木，應有懷才抱器人。"]', '诗', 'shi', '', NULL, '樓上偶題 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df48bd3a-b7d3-480c-bb79-44cc58f14dc3', '親仁里聞猨', '親仁里闻猨', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["朱雀街東半夜驚，楚魂湘夢兩徒清。","五更撩亂趨朝火，滿口塵埃亦數聲。"]', '["朱雀街东半夜驚，楚魂湘梦兩徒清。","五更撩亂趨朝火，满口塵埃亦數声。"]', '诗', 'shi', '', NULL, '親仁里聞猨 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9061c12-c4f7-4a5f-8992-10ae993bb8b9', '聞李瀆司勛下世', '闻李瀆司勛下世', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["異鄉丹旐已飄揚，一顧深知實未亡。","任被褚裒泉下笑，重將北面哭真長。"]', '["異乡丹旐已飄揚，一顧深知實未亡。","任被褚裒泉下笑，重將北面哭真长。"]', '诗', 'shi', '', NULL, '聞李瀆司勛下世 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e1cffb8-087d-411a-bd77-6e806471cf25', '試夜題省廊桂', '試夜題省廊桂', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["麻衣穿穴兩京塵，十見東堂綠桂春。","今日競飛楊葉箭，魏舒休作畫籌人。"]', '["麻衣穿穴兩京塵，十见东堂綠桂春。","今日競飞楊葉箭，魏舒休作畫籌人。"]', '诗', 'shi', '', NULL, '試夜題省廊桂 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3421523-ee8f-4bf5-b8ea-ca8b44bd1082', '竹風', '竹风', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["竹映風窗數陣斜，旅人愁坐思無涯。","夜來留得江湖夢，全爲乾聲似荻花。"]', '["竹映风窗數陣斜，旅人愁坐思無涯。","夜来留得江湖梦，全爲乾声似荻花。"]', '诗', 'shi', '', NULL, '竹風 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e69a0297-df11-47ef-873f-c6aca41da396', '長溪秋望', '长溪秋望', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["柳短莎長溪水流，雨微煙暝立溪頭。","寒鴉閃閃前山去，杜曲黃昏獨自愁。"]', '["柳短莎长溪水流，雨微煙暝立溪头。","寒鴉閃閃前山去，杜曲黄昏独自愁。"]', '诗', 'shi', '', NULL, '長溪秋望 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00870aca-493c-4b2d-9f68-1e84075a73f8', '嚴子陵', '嚴子陵', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["嚴陵情性是真狂，抵觸三公傲帝王。","不怕舊交嗔僭越，喚他侯霸作君房。"]', '["嚴陵情性是真狂，抵觸三公傲帝王。","不怕旧交嗔僭越，喚他侯霸作君房。"]', '诗', 'shi', '', NULL, '嚴子陵 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('798f18b6-31ad-4cbe-9ae4-ba0df75d7cd4', '北齊', '北齊', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["草草招提強據鞍，周師乘勝莫回看。","背城肯戰知虛實，爭奈人前忍笑難。"]', '["草草招提強據鞍，周師乘勝莫回看。","背城肯戰知虛實，爭奈人前忍笑难。"]', '诗', 'shi', '', NULL, '北齊 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f864b46c-5236-45de-b917-bc9b10c3a92e', '楚世家', '楚世家', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["偏信由來惑是非，一言邪佞脫危機。","張儀重入懷王手，駟馬安車却放歸。"]', '["偏信由来惑是非，一言邪佞脫危機。","張儀重入懷王手，駟马安车却放归。"]', '诗', 'shi', '', NULL, '楚世家 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa9f1396-f682-4145-aed4-fc19c51553f9', '驪山道中', '驪山道中', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["月殿真妃下綵煙，漁陽追虜及湯泉。","君王指點新豐樹，幾不親留七寶鞭。"]', '["月殿真妃下綵煙，漁陽追虜及湯泉。","君王指点新豐樹，幾不親留七寶鞭。"]', '诗', 'shi', '', NULL, '驪山道中 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c1187bd-a1bf-4d1b-96f5-c29c242dd98e', '韋曲', '韋曲', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["欲寫愁腸愧不才，多情練漉已低摧。","窮郊二月初離別，獨傍寒村嗅野梅。"]', '["欲寫愁腸愧不才，多情練漉已低摧。","窮郊二月初離別，独傍寒村嗅野梅。"]', '诗', 'shi', '', NULL, '韋曲 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0218ab59-76a7-47c3-b198-aea1550fe62b', '黃子陂荷花', '黄子陂荷花', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["十頃狂風撼麴塵，緣堤照水露紅新。","世間花氣皆愁絕，恰是蓮香更惱人。"]', '["十頃狂风撼麴塵，緣堤照水露紅新。","世间花氣皆愁絕，恰是蓮香更惱人。"]', '诗', 'shi', '', NULL, '黃子陂荷花 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9c958e3-e3e9-4402-a53b-163d3d70becb', '野行', '野行', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["蝶戀晚花終不去，鷗逢春水固難飛。","野人心地都無著，伴蝶隨鷗亦不歸。"]', '["蝶戀晚花終不去，鷗逢春水固难飞。","野人心地都無著，伴蝶隨鷗亦不归。"]', '诗', 'shi', '', NULL, '野行 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9565761b-37c5-4462-8037-d7ac632cd3b5', '興元沈氏莊', '兴元沈氏莊', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["清淺縈紆一水間，竹岡藤樹小躋攀。","露沾荒草行人過，月上高林宿鳥還。","江遶武侯籌筆地，雨昏張載勒銘山。","異鄉一笑因酣醉，忘却愁來鬢髮斑。"]', '["清淺縈紆一水间，竹岡藤樹小躋攀。","露沾荒草行人過，月上高林宿鸟還。","江遶武侯籌笔地，雨昏張載勒銘山。","異乡一笑因酣醉，忘却愁来鬢髮斑。"]', '诗', 'shi', '', NULL, '興元沈氏莊 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3302cfb7-a9f9-400d-a9f4-b3e561cb251b', '亂後經表兄瓊華觀舊居', '亂後經表兄瓊华观旧居', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["一去仙居似轉蓬，再經花謝倚春叢。","醉中篇什金聲在，別後音書錦字空。","長憶映碑逢若士，未曾攜杖逐壺公。","東風狼籍苔侵徑，蕙草香銷杏帶紅。"]', '["一去仙居似轉蓬，再經花謝倚春叢。","醉中篇什金声在，別後音书錦字空。","长憶映碑逢若士，未曾携杖逐壺公。","东风狼籍苔侵徑，蕙草香銷杏带紅。"]', '诗', 'shi', '', NULL, '亂後經表兄瓊華觀舊居 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02b91c1b-d64c-4361-99ca-0010e7951df0', '秋霽夜吟寄友人', '秋霽夜吟寄友人', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["槐柳蕭疎溽暑收，金商頻伏火西流。","塵衣歲晚緣身賤，雨簟更深滿背秋。","前事悲涼何足道，遠書慵懶未能修。","惟思待月高梧下，更就東牀訪惠休。"]', '["槐柳蕭疎溽暑收，金商頻伏火西流。","塵衣歲晚緣身賤，雨簟更深满背秋。","前事悲涼何足道，远书慵懶未能修。","惟思待月高梧下，更就东牀訪惠休。"]', '诗', 'shi', '', NULL, '秋霽夜吟寄友人 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e03d233-35b3-4f07-829b-d0f03c5afe04', '賀李昌時禁苑新命', '賀李昌时禁苑新命', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["玉簡金文直上清，禁垣丹地閉嚴扃。","黃扉議政參元化，紫殿稱觴拂壽星。","萬戶千門迷步武，非煙非霧隔儀形。","塵中舊侶無音信，知道遼東鶴姓丁。"]', '["玉簡金文直上清，禁垣丹地閉嚴扃。","黄扉議政參元化，紫殿稱觴拂壽星。","万戶千门迷步武，非煙非霧隔儀形。","塵中旧侶無音信，知道遼东鹤姓丁。"]', '诗', 'shi', '', NULL, '賀李昌時禁苑新命 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff0acb7a-48b5-44a1-b398-0ff34501a593', '寄蔣二十四', '寄蔣二十四', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["鳥囀蜂飛日漸長，旅人情味悔思量。","禪門澹薄無心地，世事生疎欲面牆。","二月雲煙迷柳色，九衢風土帶花香。","大知高士禁愁寂，試倚闌干莫斷腸。"]', '["鸟囀蜂飞日漸长，旅人情味悔思量。","禪门澹薄無心地，世事生疎欲面牆。","二月云煙迷柳色，九衢风土带花香。","大知高士禁愁寂，試倚闌干莫斷腸。"]', '诗', 'shi', '', NULL, '寄蔣二十四 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfc8ad54-32ef-4eff-8a00-959196d41164', '寄懷', '寄懷', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["有客傷春復怨離，夕陽亭畔草青時。","淚從紅蠟無由制，腸比朱弦恐更危。","梅向好風惟是笑，柳因微雨不勝垂。","雙溪未去饒歸夢，夜夜孤眠枕獨欹。"]', '["有客傷春复怨離，夕陽亭畔草青时。","泪從紅蠟無由制，腸比朱弦恐更危。","梅向好风惟是笑，柳因微雨不勝垂。","雙溪未去饒归梦，夜夜孤眠枕独欹。"]', '诗', 'shi', '', NULL, '寄懷 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9872ab82-b0ea-41ed-bd0a-936689efd466', '送樊琯司業歸朝', '送樊琯司業归朝', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["近者蘇司業，文雄道最光。","夫君居太學，妙譽繼中行。","汲郡陵初發，汾陰篋久亡。","寂寥方倚席，容易忽升堂。","去日應懸榻，來時定裂裳。","愜心頻拾芥，應手屢穿楊。","辯急如無敵，飛騰固自強。","論心期舌在，問事畏頭長。","駟馬終題柱，諸生悉面牆。","啗螯譏爾雅，賣餅訴公羊。","未見泥函谷，俄驚火建章。","煙塵昏象魏，行在隔巴梁。","紅粟填郿塢，青袍過壽陽。","翦茅行殿濕，伐栢舊陵香。","黌室青衿盡，渠門火斾揚。","雲飛同去國，星散各殊方。","賤子悲窮轍，當年亦擅場。","齏辛尋幼婦，醴酒憶先生。","聖域探姬孔，皇風樂禹湯。","畏誅輕李喜，言命小臧倉。","折樹休盤槊，沈鉤且釣璜。","鴻都問詞客，他日莫相忘。"]', '["近者蘇司業，文雄道最光。","夫君居太学，妙譽繼中行。","汲郡陵初發，汾陰篋久亡。","寂寥方倚席，容易忽升堂。","去日應懸榻，来时定裂裳。","愜心頻拾芥，應手屢穿楊。","辯急如無敵，飞腾固自強。","論心期舌在，问事畏头长。","駟马終題柱，諸生悉面牆。","啗螯譏爾雅，賣餅訴公羊。","未见泥函谷，俄驚火建章。","煙塵昏象魏，行在隔巴梁。","紅粟填郿塢，青袍過壽陽。","翦茅行殿濕，伐栢旧陵香。","黌室青衿尽，渠门火斾揚。","云飞同去国，星散各殊方。","賤子悲窮轍，當年亦擅場。","齏辛尋幼婦，醴酒憶先生。","聖域探姬孔，皇风乐禹湯。","畏誅轻李喜，言命小臧倉。","折樹休盤槊，沈鉤且釣璜。","鴻都问词客，他日莫相忘。"]', '诗', 'shi', '', NULL, '送樊琯司業歸朝 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('023753df-cc33-4e0c-a14c-a5ca1ba11779', '奉使岐下聞唐弘夫行軍爲賊所擒傷而有作', '奉使岐下闻唐弘夫行軍爲賊所擒傷而有作', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["報國捐軀實壯夫，楚囚垂欲復神都。","雲臺畫像皆何者，青史書名或不孤。","散卒半隨袁校尉，寡妻休問辟司徒。","聞君敗績無歸計，氣激星辰坐向隅。"]', '["報国捐軀實壯夫，楚囚垂欲复神都。","云台畫像皆何者，青史书名或不孤。","散卒半隨袁校尉，寡妻休问辟司徒。","闻君敗績無归計，氣激星辰坐向隅。"]', '诗', 'shi', '', NULL, '奉使岐下聞唐弘夫行軍爲賊所擒傷而有作 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef4a9cfd-853b-4655-a89f-efe7b793fd00', '咸通中始聞禇河南歸葬陽翟是歲上平徐方大肆慶賞又詔八品錫其裔孫追敘風概因成二十韻', '咸通中始闻禇河南归葬陽翟是歲上平徐方大肆慶賞又詔八品錫其裔孫追敘风概因成二十韻', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["冊府藏餘烈，皇綱正本朝。","不聽還笏諫，幾覆綴旒祧。","咫尺言終直，愴惶道已消。","淚心傳位日，揮涕授遺朝。","飛燕潛來趙，黃龍豈見譙。","既迷秦帝鹿，難問賈生鵰。","穆卜緘縢秘，金根轍跡遙。","北軍那奪印，東海漫難橋。","羅織黃門訟，笙簧白骨銷。","炎方無信息，丹旐竟淪漂。","邂逅江魚食，淒涼楚客招。","文忠徒諡議，子卯但簫韶。","未見公侯復，尋傷嗣續凋。","流年隨水逝，高誼薄層霄。","柱石林公遠，縑緗故國饒。","奇蹤天驥活，遺軸錦鸞翹。","近者淮夷戮，前年歸馬調。","始聞移北葬，兼議蔭山苗。","聖澤覃將溥，貞魂喜定飄。","異時窮巷客，懷古漫成謠。"]', '["冊府藏餘烈，皇綱正本朝。","不听還笏諫，幾覆綴旒祧。","咫尺言終直，愴惶道已消。","泪心傳位日，揮涕授遺朝。","飞燕潛来趙，黄龙豈见譙。","既迷秦帝鹿，难问賈生鵰。","穆卜緘縢秘，金根轍跡遙。","北軍那奪印，东海漫难橋。","羅织黄门訟，笙簧白骨銷。","炎方無信息，丹旐竟淪漂。","邂逅江鱼食，淒涼楚客招。","文忠徒諡議，子卯但簫韶。","未见公侯复，尋傷嗣續凋。","流年隨水逝，高誼薄層霄。","柱石林公远，縑緗故国饒。","奇蹤天驥活，遺軸錦鸾翹。","近者淮夷戮，前年归马調。","始闻移北葬，兼議蔭山苗。","聖澤覃將溥，貞魂喜定飄。","異时窮巷客，懷古漫成謠。"]', '诗', 'shi', '', NULL, '咸通中始聞禇河南歸葬陽翟是歲上平徐方大肆慶賞又詔八品錫其裔孫追敘風概因成二十韻 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0ca11a0-a942-4e70-aeb5-e44abd63cddd', '岐王宅', '岐王宅', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["朱邸平臺隔禁闈，貴遊陳跡尚依稀。","雲低雍畤祈年去，雨細長楊縱獵歸。","申白賓朋傳道義，應劉文彩寄音徽。","承平舊物惟君盡，猶寫雕鞍伴六飛。"]', '["朱邸平台隔禁闈，貴游陳跡尚依稀。","云低雍畤祈年去，雨細长楊縱獵归。","申白賓朋傳道義，應劉文彩寄音徽。","承平旧物惟君尽，猶寫雕鞍伴六飞。"]', '诗', 'shi', '', NULL, '岐王宅 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3456b884-d9a6-4474-9319-0939544418e7', '東韋曲野思', '东韋曲野思', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["淡霧輕雲匝四垂，綠塘秋望獨顰眉。","野蓮隨水無人見，寒鷺窺魚共影知。","九陌要津勞目擊，五湖閑夢誘心期。","孤燈夜夜愁欹枕，一覺滄洲似昔時。"]', '["淡霧轻云匝四垂，綠塘秋望独顰眉。","野蓮隨水無人见，寒鷺窺鱼共影知。","九陌要津勞目擊，五湖闲梦誘心期。","孤灯夜夜愁欹枕，一覺滄洲似昔时。"]', '诗', 'shi', '', NULL, '東韋曲野思 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b92d3185-92e6-44e1-9295-19324f45c730', '上巳', '上巳', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["上巳接寒食，鶯花寥落晨。","微微潑火雨，草草踏青人。","涼似三秋景，清無九陌塵。","與余同病者，對此合傷神。"]', '["上巳接寒食，鶯花寥落晨。","微微潑火雨，草草踏青人。","涼似三秋景，清無九陌塵。","與余同病者，对此合傷神。"]', '诗', 'shi', '', NULL, '上巳 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3baf222e-20c7-4f89-afa5-b25ce7d80109', '移莎', '移莎', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["移從杜城曲，置在小齋東。","正是高秋裏，仍兼細雨中。","結根方迸竹，疎蔭託高桐。","苒苒齊芳草，飄飄笑斷蓬。","片時留靜者，一夜響鳴蛩。","野露通宵滴，溪煙盡日蒙。","試才卑庾薤，求味笑周菘。","只此霜栽好，他時贈伯翁。"]', '["移從杜城曲，置在小斋东。","正是高秋裏，仍兼細雨中。","結根方迸竹，疎蔭託高桐。","苒苒齊芳草，飄飄笑斷蓬。","片时留静者，一夜响鳴蛩。","野露通宵滴，溪煙尽日蒙。","試才卑庾薤，求味笑周菘。","只此霜栽好，他时贈伯翁。"]', '诗', 'shi', '', NULL, '移莎 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5fce2d0-f012-4ef2-85f1-29a2ab3fbf3d', '西明寺威公盆池新稻', '西明寺威公盆池新稻', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["爲笑江南種稻時，露蟬鳴後雨霏霏。","蓮盆積潤分畦小，藻井垂陰擢秀稀。","得地又生金象界，結根仍對水田衣。","支公尚有三吳思，更使幽人憶釣磯。"]', '["爲笑江南種稻时，露蟬鳴後雨霏霏。","蓮盆積潤分畦小，藻井垂陰擢秀稀。","得地又生金象界，結根仍对水田衣。","支公尚有三吳思，更使幽人憶釣磯。"]', '诗', 'shi', '', NULL, '西明寺威公盆池新稻 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cebb127-e2e6-423d-a597-340dc11ecfdf', '紅葉', '紅葉', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["無處不飄揚，高樓臨道旁。","素娥前夕月，青女夜來霜。","宿雨隨時潤，秋晴著物光。","幽懷長若此，病眼更相妨。","蜀紙裁深色，燕脂落靚粧。","低叢侵小閣，倒影入迴塘。","謝朓留霞綺，甘寧棄錦張。","何人休遠道，是處有斜陽。","薜荔垂書幌，梧桐墜井牀。","晚風生旅館，寒籟近僧房。","桂綠明淮甸，楓丹照楚鄉。","鴈疎臨鄠杜，蟬急傍瀟湘。","樹異桓宣武，園非顧辟疆。","茂陵愁臥客，不自保危腸。"]', '["無处不飄揚，高楼臨道旁。","素娥前夕月，青女夜来霜。","宿雨隨时潤，秋晴著物光。","幽懷长若此，病眼更相妨。","蜀紙裁深色，燕脂落靚粧。","低叢侵小閣，倒影入迴塘。","謝朓留霞綺，甘寧棄錦張。","何人休远道，是处有斜陽。","薜荔垂书幌，梧桐墜井牀。","晚风生旅館，寒籟近僧房。","桂綠明淮甸，楓丹照楚乡。","鴈疎臨鄠杜，蟬急傍瀟湘。","樹異桓宣武，园非顧辟疆。","茂陵愁臥客，不自保危腸。"]', '诗', 'shi', '', NULL, '紅葉 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d52dcd-dea7-4a3c-ae21-ced8ef9101b7', '鸂鶒', '鸂鶒', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["一宿南塘煙雨時，好風搖動綠波微。","驚離曉岸衝花去，暖下春汀照影飛。","華屋撚弦彈鼓舞，綺窗含筆澹毛衣。","畫屏見後長迴首，爭得雕籠莫放歸。"]', '["一宿南塘煙雨时，好风搖动綠波微。","驚離晓岸衝花去，暖下春汀照影飞。","华屋撚弦彈鼓舞，綺窗含笔澹毛衣。","畫屏见後长迴首，爭得雕籠莫放归。"]', '诗', 'shi', '', NULL, '鸂鶒 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbcb90ca-0359-4083-a0ac-a93543f2d958', '螢', '螢', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["日下蕪城莽蒼中，濕螢撩亂起衰叢。","寒煙陳后長門閉，夜雨隋家舊苑空。","星散欲陵前檻月，影低如試北窗風。","羇人此夕方愁緒，心似寒灰首似蓬。"]', '["日下蕪城莽蒼中，濕螢撩亂起衰叢。","寒煙陳后长门閉，夜雨隋家旧苑空。","星散欲陵前檻月，影低如試北窗风。","羇人此夕方愁緒，心似寒灰首似蓬。"]', '诗', 'shi', '', NULL, '螢 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9da82499-8e6f-446b-b6bb-08cb8df2d285', '夜蟬', '夜蟬', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["翠竹高梧夾後溪，勁風危露雨淒淒。","那知北牖殘燈暗，又送西樓片月低。","清夜更長應未已，遠煙尋斷莫頻嘶。","羇人此夕如三歲，不整寒衾待曙雞。"]', '["翠竹高梧夾後溪，勁风危露雨淒淒。","那知北牖殘灯暗，又送西楼片月低。","清夜更长應未已，远煙尋斷莫頻嘶。","羇人此夕如三歲，不整寒衾待曙雞。"]', '诗', 'shi', '', NULL, '夜蟬 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf0a3350-3a21-45ab-b44a-a289d8ba2812', '七夕', '七夕', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["露白風清夜向晨，小星垂佩月埋輪。","絳河浪淺休相隔，滄海波深尚作塵。","天外鳳皇何寂寞，世間烏鵲漫辛勤。","倚闌殿北斜樓上，多少通宵不寐人。"]', '["露白风清夜向晨，小星垂佩月埋輪。","絳河浪淺休相隔，滄海波深尚作塵。","天外鳳皇何寂寞，世间烏鵲漫辛勤。","倚闌殿北斜楼上，多少通宵不寐人。"]', '诗', 'shi', '', NULL, '七夕 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94029bef-b2e6-4192-9162-8bf12dd05595', '中秋夜玩月', '中秋夜玩月', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["一夜高樓萬景奇，碧天無際水無涯。","只留皎月當層漢，並送浮雲出四維。","霧靜不容玄豹隱，冰生惟恐夏蟲疑。","坐來離思憂將曉，爭得嫦娥仔細知。"]', '["一夜高楼万景奇，碧天無際水無涯。","只留皎月當層漢，並送浮云出四維。","霧静不容玄豹隐，冰生惟恐夏蟲疑。","坐来離思憂將晓，爭得嫦娥仔細知。"]', '诗', 'shi', '', NULL, '中秋夜玩月 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69f7d71f-65d5-4553-83cf-bc5788e976f8', '八月十六日夜月', '八月十六日夜月', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["斷腸佳賞固難期，昨夜銷魂更不疑。","丹桂影空蟾有露，綠槐陰在鵲無枝。","賴將吟詠聊惆悵，早是疎頑耐別離。","堪恨賈生曾慟哭，不緣清景爲憂時。"]', '["斷腸佳賞固难期，昨夜銷魂更不疑。","丹桂影空蟾有露，綠槐陰在鵲無枝。","賴將吟詠聊惆悵，早是疎頑耐別離。","堪恨賈生曾慟哭，不緣清景爲憂时。"]', '诗', 'shi', '', NULL, '八月十六日夜月 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65d079f5-4f62-46c1-aeb2-5b013034f2a7', '送韋向之睦州謁使君', '送韋向之睦州謁使君', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["才子南遊多遠情，閑舟蕩漾任春行。","新安江上長如此，何似新安太守清。"]', '["才子南游多远情，闲舟蕩漾任春行。","新安江上长如此，何似新安太守清。"]', '诗', 'shi', '', NULL, '送韋向之睦州謁使君 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddab0d90-c461-4812-b58c-24187819875c', '春殘', '春殘', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["景爲春時短，愁隨別夜長。","暫碁寧號隱，輕醉不成鄉。","風雨曾通夕，莓苔有衆芳。","落花如便去，樓上即河梁。"]', '["景爲春时短，愁隨別夜长。","暫碁寧號隐，轻醉不成乡。","风雨曾通夕，莓苔有衆芳。","落花如便去，楼上即河梁。"]', '诗', 'shi', '', NULL, '春殘 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2355765-ba7d-4e13-93d9-4520f07f015d', '玫瑰', '玫瑰', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["麝炷騰清燎，鮫紗覆綠蒙。","宮妝臨曉日，錦段落東風。","無力春烟裏，多愁暮雨中。","不知何事意，深淺兩般紅。"]', '["麝炷腾清燎，鮫紗覆綠蒙。","宮妝臨晓日，錦段落东风。","無力春烟裏，多愁暮雨中。","不知何事意，深淺兩般紅。"]', '诗', 'shi', '', NULL, '玫瑰 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37186186-dfdd-4f65-8107-39e80ed4c6cb', '牡丹', '牡丹', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["真宰多情巧思新，固將能事送殘春。","爲雲爲雨徒虛語，傾國傾城不在人。","開日綺霞應失色，落時青帝合傷神。","嫦娥婺女曾相送，留下鵶黃作蘂塵。"]', '["真宰多情巧思新，固將能事送殘春。","爲云爲雨徒虛語，傾国傾城不在人。","开日綺霞應失色，落时青帝合傷神。","嫦娥婺女曾相送，留下鵶黄作蘂塵。"]', '诗', 'shi', '', NULL, '牡丹 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('076bef5a-c7b6-4811-ba7c-f479dc78af6a', '秋晚高樓', '秋晚高楼', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["松拂疎窗竹映闌，素琴幽怨不成彈。","清宵霽極雲離岫，紫禁風高露滿盤。","晚蝶飄零驚宿雨，暮鴉淩亂報秋寒。","高樓瞪目歸鴻遠，如信嵇康欲畫難。"]', '["松拂疎窗竹映闌，素琴幽怨不成彈。","清宵霽極云離岫，紫禁风高露满盤。","晚蝶飄零驚宿雨，暮鴉淩亂報秋寒。","高楼瞪目归鴻远，如信嵇康欲畫难。"]', '诗', 'shi', '', NULL, '秋晚高樓 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98a42465-6314-49bb-b34a-1383d7009e22', '離鸞', '離鸾', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["聞道離鸞思故鄉，也知情願嫁王昌。","塵埃一別楊朱路，風月三年宋玉牆。","下疾不成雙點淚，斷多難到九迴腸。","庭前佳樹名梔子，試結同心寄謝娘。"]', '["闻道離鸾思故乡，也知情願嫁王昌。","塵埃一別楊朱路，风月三年宋玉牆。","下疾不成雙点泪，斷多难到九迴腸。","庭前佳樹名梔子，試結同心寄謝娘。"]', '诗', 'shi', '', NULL, '離鸞 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5c2041e-3163-434d-9b52-3c788426e7a3', '柳', '柳', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["春思春愁一萬枝，遠村遙岸寄相思。","西園有雨和苔長，南內無人拂檻垂。","遊客寂寥緘遠恨，暮鶯啼呌惜芳時。","晚來飛絮如霜鬢，恐爲多情管別離。"]', '["春思春愁一万枝，远村遙岸寄相思。","西园有雨和苔长，南內無人拂檻垂。","游客寂寥緘远恨，暮鶯啼呌惜芳时。","晚来飞絮如霜鬢，恐爲多情管別離。"]', '诗', 'shi', '', NULL, '柳 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d2f0e90-02bc-439c-83e6-6036b9b00e38', '春陰', '春陰', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["一寸迴腸百慮侵，旅愁危涕兩爭禁。","天涯已有銷魂別，樓上寧無擁鼻吟。","感事不關河裏笛，傷心應倍雍門琴。","春雲更覺愁于我，閑蓋低村作暝陰。"]', '["一寸迴腸百慮侵，旅愁危涕兩爭禁。","天涯已有銷魂別，楼上寧無擁鼻吟。","感事不关河裏笛，傷心應倍雍门琴。","春云更覺愁于我，闲蓋低村作暝陰。"]', '诗', 'shi', '', NULL, '春陰 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6744cdde-c480-48a0-a8f2-6d7e66463c2b', '春深獨行馬上有作', '春深独行马上有作', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["日烈風高野草香，百花狼籍柳披猖。","連天瑞靄千門遠，夾道新陰九陌長。","衆飲不歡逃席酒，獨行無味放遊韁。","年來與問閑遊者，若箇傷春向路旁。"]', '["日烈风高野草香，百花狼籍柳披猖。","連天瑞靄千门远，夾道新陰九陌长。","衆饮不歡逃席酒，独行無味放游韁。","年来與问闲游者，若箇傷春向路旁。"]', '诗', 'shi', '', NULL, '春深獨行馬上有作 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aea48ef-e54c-43a9-9ef2-8ab5ecd9e232', '春雨', '春雨', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["綺陌夜來雨，春樓寒望迷。","遠客迎燕戲，亂響隔鶯啼。","有恨開蘭室，無言對李蹊。","花欹渾拂檻，柳重欲垂堤。","燈檠昏魚目，薰爐咽麝臍。","別輕天北鶴，夢怯汝南雞。","入戶侵羅幌，捎簷潤繡題。","新豐樹已失，長信草初齊。","亂蝶寒猶舞，驚烏暝不栖。","庾郎盤馬地，却怕有春泥。"]', '["綺陌夜来雨，春楼寒望迷。","远客迎燕戲，亂响隔鶯啼。","有恨开蘭室，無言对李蹊。","花欹渾拂檻，柳重欲垂堤。","灯檠昏鱼目，薰爐咽麝臍。","別轻天北鹤，梦怯汝南雞。","入戶侵羅幌，捎簷潤繡題。","新豐樹已失，长信草初齊。","亂蝶寒猶舞，驚烏暝不栖。","庾郎盤马地，却怕有春泥。"]', '诗', 'shi', '', NULL, '春雨 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7507ea80-0696-42ea-be71-69907ce74308', '漢代', '漢代', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["漢代金爲屋，吳宮綺作寮。","豔詞傳靜婉，新曲定妖嬈。","箭響猶殘夢，籤聲報早朝。","鮮明臨曉日，迴轉度春宵。","半袖籠清鏡，前絲壓翠翹。","靜多如有待，閑極似無憀。","梓澤花猶滿，靈和柳未凋。","障昏巫峽雨，屏掩浙江潮。","未信潘名岳，應疑史姓蕭。","漏因歌暫斷，燈爲雨頻挑。","飲酒闌三雅，投壺賽百嬌。","鈿蟬新翅重，金鴨舊香焦。","水淨疑澄練，霞孤欲建標。","別隨秦柱促，愁爲蜀弦么。","玄[晏]難瘳痹，臨邛但發痟。","聯詩徵弱絮，思友詠甘蕉。","王氏憐諸謝，周郎定小喬。","黼幃翹綵雉，波扇畫文鰩。","荇密妨垂釣，荷欹欲度橋。","不因衣帶水，誰覺路迢迢。"]', '["漢代金爲屋，吳宮綺作寮。","豔词傳静婉，新曲定妖嬈。","箭响猶殘梦，籤声報早朝。","鲜明臨晓日，迴轉度春宵。","半袖籠清镜，前絲壓翠翹。","静多如有待，闲極似無憀。","梓澤花猶满，靈和柳未凋。","障昏巫峽雨，屏掩浙江潮。","未信潘名岳，應疑史姓蕭。","漏因歌暫斷，灯爲雨頻挑。","饮酒闌三雅，投壺賽百嬌。","鈿蟬新翅重，金鴨旧香焦。","水淨疑澄練，霞孤欲建標。","別隨秦柱促，愁爲蜀弦么。","玄[晏]难瘳痹，臨邛但發痟。","聯诗徵弱絮，思友詠甘蕉。","王氏怜諸謝，周郎定小喬。","黼幃翹綵雉，波扇畫文鰩。","荇密妨垂釣，荷欹欲度橋。","不因衣带水，誰覺路迢迢。"]', '诗', 'shi', '', NULL, '漢代 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144bfac6-f8f2-4b32-a3a9-17189f6fb0e7', '牡丹', '牡丹', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["青帝於君事分偏，穠堆浮豔倚朱門。","雖然占得笙歌地，將甚酬他雨露恩。"]', '["青帝於君事分偏，穠堆浮豔倚朱门。","雖然占得笙歌地，將甚酬他雨露恩。"]', '诗', 'shi', '', NULL, '牡丹 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7749544e-0338-421c-b565-63d1d31d54df', '湘妃廟', '湘妃廟', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["劉表荒碑斷水濱，廟前幽草閉殘春。","已將愁淚留斑竹，又感悲風入白蘋。","八族未來誰北拱，四凶猶在莫南巡。","九峰相似堪疑處，望見蒼梧不見人。"]', '["劉表荒碑斷水濱，廟前幽草閉殘春。","已將愁泪留斑竹，又感悲风入白蘋。","八族未来誰北拱，四凶猶在莫南巡。","九峰相似堪疑处，望见蒼梧不见人。"]', '诗', 'shi', '', NULL, '湘妃廟 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f88f3726-a90a-4de7-8204-19cbfeca9e4e', '句', '句', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["獨來成悵望，不去泥欄干。"]', '["独来成悵望，不去泥欄干。"]', '诗', 'shi', '', NULL, '句 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfa7a6b-735f-4c8b-a660-9a85f2f32557', '題甘露寺', '題甘露寺', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["層閣疊危壁，瑞因千古名。","幾連揚子路，獨倚潤州城。","雲近銜江色，鵰高背磬聲。","僧居上方久，端坐見營營。"]', '["層閣叠危壁，瑞因千古名。","幾連揚子路，独倚潤州城。","云近銜江色，鵰高背磬声。","僧居上方久，端坐见營營。"]', '诗', 'shi', '', NULL, '題甘露寺 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9173198a-adfa-4a09-bf35-d36a31e54533', '題玄公院', '題玄公院', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["院深塵自外，如佛值玄公。","常跡或非次，志門因得中。","衣巾離暑氣，牀榻向涼風。","是事不逾分，秪應明德同。"]', '["院深塵自外，如佛值玄公。","常跡或非次，志门因得中。","衣巾離暑氣，牀榻向涼风。","是事不逾分，秪應明德同。"]', '诗', 'shi', '', NULL, '題玄公院 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca467dd8-3d91-4a5d-884c-e10f5680aa34', '福州東禪寺', '福州东禪寺', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["甌閩在郊外，師院號東禪。","物得居來正，人經論後賢。","瓟槽柳塞馬，蓋地月支綖。","鸛鵲尚巢頂，誰堪舉世傳。"]', '["甌閩在郊外，師院號东禪。","物得居来正，人經論後賢。","瓟槽柳塞马，蓋地月支綖。","鸛鵲尚巢頂，誰堪舉世傳。"]', '诗', 'shi', '', NULL, '福州東禪寺 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aef1dfca-db03-4449-8b3e-296dfbd65bda', '贈大溈和尚', '贈大溈和尚', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["大溈清復深，萬象影沈沈。","有客衣多毳，空門偈勝金。","王侯皆作禮，陸子只來吟。","我問師心處，師言無處心。"]', '["大溈清复深，万象影沈沈。","有客衣多毳，空门偈勝金。","王侯皆作禮，陸子只来吟。","我问師心处，師言無处心。"]', '诗', 'shi', '', NULL, '贈大溈和尚 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e9613ea-517b-45df-8fe3-74c6850e3330', '秋夜不寐寄崔溫進士', '秋夜不寐寄崔溫進士', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["愁多難得寐，展轉讀書牀。","不是旅人病，豈知秋夜長。","歸鄉憑遠夢，無夢更思鄉。","枕上移窗月，分明是淚光。"]', '["愁多难得寐，展轉读书牀。","不是旅人病，豈知秋夜长。","归乡憑远梦，無梦更思乡。","枕上移窗月，分明是泪光。"]', '诗', 'shi', '', NULL, '秋夜不寐寄崔溫進士 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c64097e-4738-4cd5-8234-ee75b1a1b6aa', '春中途中寄南巴崔使君', '春中途中寄南巴崔使君', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["旅人遊汲汲，春氣又融融。","農事蛙聲裏，歸程草色中。","獨慙出穀雨，未變暖天風。","子玉和予去，應憐恨不窮。"]', '["旅人游汲汲，春氣又融融。","農事蛙声裏，归程草色中。","独慙出穀雨，未变暖天风。","子玉和予去，應怜恨不窮。"]', '诗', 'shi', '', NULL, '春中途中寄南巴崔使君 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd032b02-6b8b-4c74-828f-5bc73253e095', '寄處士方干', '寄处士方干', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["桐廬江水閑，終日對柴關。","因想別離處，不知多少山。","釣舟春岸泊，庭樹曉鶯還。","莫便求棲隱，桂枝堪恨顏。"]', '["桐廬江水闲，終日对柴关。","因想別離处，不知多少山。","釣舟春岸泊，庭樹晓鶯還。","莫便求棲隐，桂枝堪恨顏。"]', '诗', 'shi', '', NULL, '寄處士方干 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93df7eb4-6e1b-4cb5-b278-56c889930906', '寄塞北張符', '寄塞北張符', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["隴樹塞風吹，遼城角幾枝。","霜凝無暫歇，君貌莫應衰。","萬里平沙際，一行邊鴈移。","那堪朔煙起，家信正相離。"]', '["隴樹塞风吹，遼城角幾枝。","霜凝無暫歇，君貌莫應衰。","万里平沙際，一行邊鴈移。","那堪朔煙起，家信正相離。"]', '诗', 'shi', '', NULL, '寄塞北張符 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88454909-4a51-4b48-be11-a36ea0aab22f', '次梧州却寄永州使君', '次梧州却寄永州使君', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["隨風身不定，今夜在蒼梧。","客淚有時有，猨聲無處無。","潮添瘴海闊，煙拂粤山孤。","却憶零陵住，吟詩半玉壺。"]', '["隨风身不定，今夜在蒼梧。","客泪有时有，猨声無处無。","潮添瘴海闊，煙拂粤山孤。","却憶零陵住，吟诗半玉壺。"]', '诗', 'shi', '', NULL, '次梧州却寄永州使君 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('148a5b30-2fe5-467d-bdf7-b5e327770a4f', '贈念經僧', '贈念經僧', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["菴前古折碑，夜靜念經時。","月皎海霞散，露濃山草垂。","鬼聞拋故塚，禽聽離寒枝。","想得天花墜，馨香拂白眉。"]', '["菴前古折碑，夜静念經时。","月皎海霞散，露濃山草垂。","鬼闻拋故塚，禽听離寒枝。","想得天花墜，馨香拂白眉。"]', '诗', 'shi', '', NULL, '贈念經僧 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd9b236d-5f5a-4d7c-9a2d-efbfa49507a7', '董嶺水', '董嶺水', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["湖州安吉縣，門與白雲齊。","禹力不到處，河聲流向西。","去衙山色遠，近水月光低。","中有高人在，沙中曳杖藜。"]', '["湖州安吉縣，门與白云齊。","禹力不到处，河声流向西。","去衙山色远，近水月光低。","中有高人在，沙中曳杖藜。"]', '诗', 'shi', '', NULL, '董嶺水 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afd85f67-caa1-4ff2-af35-523b3d1908d8', '早春', '早春', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["良夜歲應足，嚴風爲變春。","遍回寒作暖，通改舊成新。","秀樹因馨雨，融冰雨泛蘋。","韶光不偏黨，積漸煦疲民。"]', '["良夜歲應足，嚴风爲变春。","遍回寒作暖，通改旧成新。","秀樹因馨雨，融冰雨泛蘋。","韶光不偏黨，積漸煦疲民。"]', '诗', 'shi', '', NULL, '早春 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4de3847c-0f6f-47ed-9f0d-708229932772', '秋深', '秋深', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["柳色尚沈沈，風吹秋更深。","山河空遠道，鄉國自鳴砧。","巷有千家月，人無萬里心。","長城哭崩後，寂絕至如今。"]', '["柳色尚沈沈，风吹秋更深。","山河空远道，乡国自鳴砧。","巷有千家月，人無万里心。","长城哭崩後，寂絕至如今。"]', '诗', 'shi', '', NULL, '秋深 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42e1f1d2-bfd5-45c8-b800-6b9e4aae8a55', '贈雙峰山和尚', '贈雙峰山和尚', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["峩峩雙髻山，瀑布瀉雲間。","塵世自疑水，禪門長去關。","茯神松不異，藏寶石俱閑。","向此師清業，如何方可攀。"]', '["峩峩雙髻山，瀑布瀉云间。","塵世自疑水，禪门长去关。","茯神松不異，藏寶石俱闲。","向此師清業，如何方可攀。"]', '诗', 'shi', '', NULL, '贈雙峰山和尚 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e94187b-8ccd-495d-a737-b1677735b703', '贈無了禪師', '贈無了禪師', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["不學世所惜，是何無了公。","靈匡虛院外，虎跡亂山中。","晝夜必連去，古今爭敢同。","禪情豈堪問，問答更無窮。"]', '["不学世所惜，是何無了公。","靈匡虛院外，虎跡亂山中。","晝夜必連去，古今爭敢同。","禪情豈堪问，问答更無窮。"]', '诗', 'shi', '', NULL, '贈無了禪師 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edb0d494-c237-43d8-a450-5f5136fff1b0', '王霸壇', '王霸壇', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["王君上升處，信首古居前。","皂樹即須朽，白龜應亦全。","雲間猶一日，塵裏已千年。","碧色壇如黛，時人誰可仙。"]', '["王君上升处，信首古居前。","皂樹即須朽，白龟應亦全。","云间猶一日，塵裏已千年。","碧色壇如黛，时人誰可仙。"]', '诗', 'shi', '', NULL, '王霸壇 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af75607e-7a59-4dad-9d5c-1df896690654', '送梁道士', '送梁道士', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["舊居桐栢觀，歸去愛安閑。","倒樹造新屋，化人修古壇。","晚花霜後落，山雨夜深寒。","應有同溪客，相尋學鍊丹。"]', '["旧居桐栢观，归去愛安闲。","倒樹造新屋，化人修古壇。","晚花霜後落，山雨夜深寒。","應有同溪客，相尋学鍊丹。"]', '诗', 'shi', '', NULL, '送梁道士 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec7329f3-4e6d-49e1-af7e-742cb7e3a143', '邊思', '邊思', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["年高來遠戍，白首罷干戎。","夜色薊門火，秋聲邊塞風。","磧浮悲老馬，月滿引新弓。","百戰陰山去，唯添上將雄。"]', '["年高来远戍，白首罷干戎。","夜色薊门火，秋声邊塞风。","磧浮悲老马，月满引新弓。","百戰陰山去，唯添上將雄。"]', '诗', 'shi', '', NULL, '邊思 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8113c1d-dfb4-46a0-9596-0f254eb3aa43', '哭陳庾', '哭陳庾', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["繫馬向山立，一桮聊奠君。","野煙孤客路，寒草故人墳。","琴韻歸流水，詩情寄白雲。","日斜休哭後，松韻不堪聞。"]', '["繫马向山立，一桮聊奠君。","野煙孤客路，寒草故人墳。","琴韻归流水，诗情寄白云。","日斜休哭後，松韻不堪闻。"]', '诗', 'shi', '', NULL, '哭陳庾 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('172e0de9-61de-4a49-ac01-8a354acf015a', '宿玉泉寺', '宿玉泉寺', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["野寺度殘夏，空房欲暮時。","夜聽猨不睡，秋思客先知。","竹迥煙生薄，山高月上遲。","又登塵路去，難與老僧期。"]', '["野寺度殘夏，空房欲暮时。","夜听猨不睡，秋思客先知。","竹迥煙生薄，山高月上遲。","又登塵路去，难與老僧期。"]', '诗', 'shi', '', NULL, '宿玉泉寺 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48c7611e-eb2e-47ec-8d2e-7fd83ab844fb', '題赤城中巖寺', '題赤城中巖寺', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["浮世師休話，晉時燈照巖。","禽飛穿靜戶，藤結入高杉。","存沒詩千首，廢興經數函。","誰知將俗耳，來此避囂讒。"]', '["浮世師休話，晉时灯照巖。","禽飞穿静戶，藤結入高杉。","存沒诗千首，廢兴經數函。","誰知將俗耳，来此避囂讒。"]', '诗', 'shi', '', NULL, '題赤城中巖寺 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d27ae6e7-0723-4dab-a402-aed1845d1b12', '塞上行', '塞上行', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["秦築長城在，連雲磧氣侵。","風吹邊草急，角絕塞鴻沈。","世世征人往，年年戰骨深。","遼天望鄉者，迴首盡霑襟。"]', '["秦築长城在，連云磧氣侵。","风吹邊草急，角絕塞鴻沈。","世世征人往，年年戰骨深。","遼天望乡者，迴首尽霑襟。"]', '诗', 'shi', '', NULL, '塞上行 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4ad0f91-8da6-4627-aa01-ba3e11adf0e0', '玉泉寺', '玉泉寺', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["寺還名玉泉，澄水亦遭賢。","物尚猶如此，人爭合偶然。","溪流雲斷外，山峻鳥飛還。","初日長廊下，高僧正坐禪。"]', '["寺還名玉泉，澄水亦遭賢。","物尚猶如此，人爭合偶然。","溪流云斷外，山峻鸟飞還。","初日长廊下，高僧正坐禪。"]', '诗', 'shi', '', NULL, '玉泉寺 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d6885a4-d11e-4428-80a8-fcf75d7a41aa', '春宮怨', '春宮怨', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["早被嬋娟誤，欲妝臨鏡慵。","承恩不在貌，教妾若爲容。","風暖鳥聲碎，日高花影重。","年年越溪女，相憶采芙蓉。"]', '["早被嬋娟誤，欲妝臨镜慵。","承恩不在貌，教妾若爲容。","风暖鸟声碎，日高花影重。","年年越溪女，相憶采芙蓉。"]', '诗', 'shi', '', NULL, '春宮怨 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bcdc4bc-0691-4adc-92b3-f81f25cf234c', '宿劉溫書齋', '宿劉溫书斋', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["不掩盈窗日，天然格調高。","涼風移蟋蟀，落葉在離騷。","迴筆挑燈燼，懸圖見海潮。","因論三國志，空載幾英豪。"]', '["不掩盈窗日，天然格調高。","涼风移蟋蟀，落葉在離騷。","迴笔挑灯燼，懸圖见海潮。","因論三国志，空載幾英豪。"]', '诗', 'shi', '', NULL, '宿劉溫書齋 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9539b768-44d3-4717-bb53-0b200a4f63bd', '登福州南澗寺', '登福州南澗寺', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["萬里重山遶福州，南橫一道見溪流。","天邊飛鳥東西沒，塵裏行人早晚休。","曉日青山當大海，連雲古塹對高樓。","那堪望斷他鄉目，只此蕭條自白頭。"]', '["万里重山遶福州，南橫一道见溪流。","天邊飞鸟东西沒，塵裏行人早晚休。","晓日青山當大海，連云古塹对高楼。","那堪望斷他乡目，只此蕭條自白头。"]', '诗', 'shi', '', NULL, '登福州南澗寺 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('669bc8c6-6413-4dcc-a834-88a82403c6d0', '望中懷古', '望中懷古', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["齊心樓上望浮雲，萬古千秋空姓名。","堯水永銷天際去，姬風一變世間平。","高蹤盡共煙霞在，大道長將日月明。","從此安然寰海內，後來無復謾相傾。"]', '["齊心楼上望浮云，万古千秋空姓名。","堯水永銷天際去，姬风一变世间平。","高蹤尽共煙霞在，大道长將日月明。","從此安然寰海內，後来無复謾相傾。"]', '诗', 'shi', '', NULL, '望中懷古 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f8eb51c-6bef-472b-bf1c-93fbd249677c', '昇山寺', '昇山寺', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["昇山自古道飛來，此是神功不可猜。","氣色雖然離禹穴，峰巒猶自接天台。","巖邊折樹泉衝落，頂上浮雲日照開。","南望閩城塵世界，千秋萬古卷塵埃。"]', '["昇山自古道飞来，此是神功不可猜。","氣色雖然離禹穴，峰巒猶自接天台。","巖邊折樹泉衝落，頂上浮云日照开。","南望閩城塵世界，千秋万古卷塵埃。"]', '诗', 'shi', '', NULL, '昇山寺 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d63cf89e-c809-4b70-b190-cd27a51c45dc', '哭李端', '哭李端', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["三年翦拂感知音，哭向青山永夜心。","竹在曉煙孤鳳去，劍荒秋水一龍沈。","新墳日落松聲小，舊色春殘草色深。","不及此時親執紼，石門遙想淚霑襟。"]', '["三年翦拂感知音，哭向青山永夜心。","竹在晓煙孤鳳去，劍荒秋水一龙沈。","新墳日落松声小，旧色春殘草色深。","不及此时親執紼，石门遙想泪霑襟。"]', '诗', 'shi', '', NULL, '哭李端 周朴 shi');
